window.__HRC_SHARD({"shard":"ohchr-investigation-libya","builtAt":"2026-09-03T11:43:29+00:00","documents":[{"rec_id":"rec1EBCegpqCdTa7t","doc_id":"OHCHR Investigation Libya - Official report - 15.02.2016","symbol":"A/HRC/31/47","title":"Investigation by the Office of the United Nations High Commissioner for Human Rights on Libya — Report of the Office of the United Nations High Commissioner for Human Rights","type":"Official report","date":"2016-02-15","year":2016,"bodies":["OHCHR Investigation Libya"],"paragraphCount":90,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/OHCHR Investigation Libya - 15-02-2016 - Official report - A_HRC_31_47 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec7FMRMxNt00GOh1","doc_id":"OHCHR Investigation Libya - CRP - 23.02.2016","symbol":"A/HRC/31/CRP.3","title":"OHCHR Investigation on Libya - Detailed Findings","type":"CRP","date":"2016-02-23","year":2016,"bodies":["OHCHR Investigation Libya"],"paragraphCount":363,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/OHCHR Investigation Libya - 23-02-2016 - CRP - A_HRC_31_CRP.3 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-31-47-u0000","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/31/47\nGeneral Assembly                                                          Distr.: General\n15 February 2016","unnumbered":true},{"id":"a-hrc-31-47-u0001","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":null,"seq":1,"section":null,"text":"Human Rights Council\nThirty-first session\nAgenda items 2 and 10\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nTechnical assistance and capacity-building","unnumbered":true},{"id":"a-hrc-31-47-u0002","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":null,"seq":2,"section":null,"text":"Summary\nThe present report, submitted pursuant to Human Rights Council resolution 28/30,\nhas been prepared on the basis of an investigation carried out by the Office of the United\nNations High Commissioner for Human Rights (OHCHR). It describes widespread\nviolations of international human rights law and international humanitarian law, and abuses\nof human rights, perpetrated by all parties to the conflict in Libya throughout 2014 and\n2015. The report also describes the situation of human rights defenders, journalists,\nmigrants, the Tawerghan community and children, and the administration of justice in\nLibya in this context. It also provides an assessment of the justice sector, and describes\ninitiatives towards accountability.\nIn the report, OHCHR also provides an update on technical assistance and capacity-\nbuilding provided to support key institutions and civil society organizations. It concludes\nthe report with recommendations addressed to all parties to the conflict, the Government,\nthe international community, the Human Rights Council and the Security Council.","unnumbered":true},{"id":"a-hrc-31-47-u0003","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":null,"seq":3,"section":null,"text":"*   The information contained in the present report should be read in conjunction with the conference\nroom paper containing the detailed findings of the investigation of the Office of the United Nations\nHigh Commissioner for Human Rights on Libya (A/HRC/31/CRP.3).","unnumbered":true},{"id":"a-hrc-31-47-p0001","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"1","seq":4,"section":"A. Mandate","text":"On 27 March 2015, the Human Rights Council adopted its resolution 28/30, in\nwhich it requested the United Nations High Commissioner for Human Rights urgently to\ndispatch a mission to investigate violations and abuses of international human rights law\ncommitted in Libya since the beginning of 2014, and to establish the facts and\ncircumstances of such abuses and violations with a view to avoiding impunity and ensuring\nfull accountability, and to submit to the Council a written report on its findings, which\nshould also contain an update on technical assistance, capacity-building and cooperation\nwith the Government of Libya, with recommendations for future capacity-building needs\nthat include but are not limited to the justice system and accountability."},{"id":"a-hrc-31-47-p0002","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"2","seq":5,"section":"A. Mandate","text":"In accordance with the mandate, the mission focused the investigation on violations\nand abuses committed from 1 January 2014, and examined the actions of both State and\nnon-State actors. During the investigation, the Office of the High Commissioner (OHCHR)\nreceived information concerning individuals with alleged responsibility for violations and\nabuses. That information has been retained on a strictly confidential basis."},{"id":"a-hrc-31-47-p0003","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"3","seq":6,"section":"B. Methodology","text":"The Government of Libya 1 expressed its support for the investigation and offered\nassistance should the OHCHR investigation team2 conduct missions to Tobruk and Al-\nBaida, for which the High Commissioner is grateful. Owing to the security situation, only a\none-day visit to Tripoli, limited to the airport, was possible. A list of questions was\ndispatched to the Government, although no response had been received as at January 2016."},{"id":"a-hrc-31-47-p0004","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"4","seq":7,"section":"B. Methodology","text":"The High Commissioner expresses his appreciation to the Government of Tunisia\nfor hosting the team in Tunis, made necessary by the continuing difficult security\nenvironment in Libya. Fact-finding activities were largely undertaken through missions and\nremote contact with individuals in Libya. The team undertook missions in Tunisia and to\nLibya, Egypt, Turkey, Jordan and Italy, and facilitated the travel of some victims and\nwitnesses to Tunis. The team met with more than 250 interlocutors, including more than\n200 victims and witnesses. A public call for submissions was issued in July 2015 and\ndisseminated to States Members of the United Nations in August and September 2015.\nOHCHR received 66 submissions containing more than 900 individual complaint files. The\nteam coordinated closely with the United Nations Support Mission in Libya (UNSMIL) and\nsought inputs from the national human rights institution of Libya, the National Council for\nCivil Liberties and Human Rights and special procedure mandate holders (from whom a\ncoordinated response was received). The team also sought information from other United\nNations entities. The United Nations Entity for Gender Equality and the Empowerment of\nWomen (UN-Women), the United Nations Development Programme and the Operational\nSatellite Applications Programme (UNOSAT) also provided valuable assistance."},{"id":"a-hrc-31-47-p0005","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"5","seq":8,"section":"B. Methodology","text":"Besides the limited access to Libya, another challenge faced by the investigation\nteam was the hostile environment for those raising human rights issues. The political\ndivisions in Libya and the fact that most international organizations are operating remotely\nalso had an impact on investigations. OHCHR was nonetheless able to gather a substantial\nbody of information leading to the finding that there are reasonable grounds to believe that\ngross violations of international human rights law, serious violations of international\nhumanitarian law and serious abuses of human rights have been committed in Libya. The\nHigh Commissioner stresses the need for ongoing international attention to ensure the\neffective, prompt and thorough investigation of these violations and abuses, and that those\nresponsible are held accountable."},{"id":"a-hrc-31-47-p0006","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"6","seq":9,"section":"II. International legal framework","text":"The investigation was carried out considering Human Rights Council resolution\n28/30 as a whole and taking into account the approach of previous investigative missions\nmandated by the Human Rights Council. The investigation was conducted within the\nframework of all relevant international legal norms, including international human rights\nlaw, international humanitarian law and international criminal law."},{"id":"a-hrc-31-47-p0007","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"7","seq":10,"section":"III. Context","text":"Still recovering from the Qadhafi period and the armed conflict of 2011, Libya\nexperienced a dramatic decline in its political and security situation in 2014 and 2015,\namidst competing legislatures, divided State security institutions and forces, and multiple\narmed groups, with devastating effects for the population."},{"id":"a-hrc-31-47-p0008","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"8","seq":11,"section":"III. Context","text":"In the east, in May 2014, retired General Khalifa Haftar launched Al Karamah\n(“Operation Dignity”), reportedly to eradicate “radical terrorist” groups from eastern Libya.\nAn alliance of groups, including Ansar al-Sharia, joined the Benghazi Revolutionaries\nShura Council to fight forces deployed under Operation Dignity. As at December 2015,\nhostilities were still ongoing. In the west, heavy fighting erupted in Tripoli in July 2014.\nOriginally focused on control of Tripoli international airport, Misrata-based armed groups\ntogether with armed groups from Tripoli, Al-Zawiya, Zuwara and other towns launched the\nFajr Libya (“Libya Dawn”) campaign against armed groups affiliated with Zintan.\nThereafter, Libya Dawn gained control of Tripoli as armed groups from Zintan withdrew.\nLibya Dawn expanded to the Warshafana region, and launched counter-offensives in the\nNafusa Mountains area. Ceasefire agreements in 2015 have since reduced the intensity of\nclashes in the west."},{"id":"a-hrc-31-47-p0009","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"9","seq":12,"section":"III. Context","text":"In 2014 and 2015, tribal armed groups engaged in localized hostilities in the south,\nparticularly in Sabha, Awbari and Al-Kufra. Armed conflicts in the north also spilled over\nto the south, with some groups allying with Operation Dignity or Libya Dawn."},{"id":"a-hrc-31-47-p0010","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"10","seq":13,"section":"III. Context","text":"In the meantime, groups pledging allegiance to Islamic State in Iraq and the Levant\n(ISIL) further emerged as a force, particularly in Derna, Sirte and Benghazi. In addition to\nprompting responses by the Libyan National Army aligned with Operation Dignity and a\nnumber of armed groups, Egypt and the United States of America engaged in air strikes\ntargeting these groups.3"},{"id":"a-hrc-31-47-p0011","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"11","seq":14,"section":"III. Context","text":"Political divisions deepened in Libya in 2014 and 2015, resulting in the formation of\nadministrations in both the east and the west. In June 2014, elections were held for a new\nlegislature, the House of Representatives, which confirmed the established Government.\nOwing to the precarious security situation in Tripoli, in August 2014, the Government, led\nby Prime Minister Abdullah Al-Thani, moved to Al-Baida. The House of Representatives\ncommenced its sittings in Tobruk. The previously established legislature, the General\nNational Congress, then re-convened, and parallel ministries were established in Tripoli.\nThe House of Representatives endorsed Operation Dignity, while the General National\nCongress supports the Libya Dawn campaign. Following a year-long political dialogue, the\nLibyan Political Agreement to establish a Government of National Accord was signed on\n17 December 2015."},{"id":"a-hrc-31-47-p0012","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"12","seq":15,"section":"IV. Armed actors in Libya","text":"The current situation should be considered against the background of the rise of\n“revolutionary” armed groups during the 2011 armed conflict, and the lack of progress in\nvetting and integrating those groups into formal security forces. Many groups were placed\nunder the nominal authority of the Ministries of Defence, the Interior or Justice, received\nsalaries from the State and, in some cases, given law enforcement and custodial functions.\nArmed groups appear, however, to have continued to operate with significant autonomy,\nincluding by maintaining their own command structure. The number and membership of\nsuch groups have increased substantially. They have consolidated effective control over\nlarge territorial areas, strategic installations and State institutions. In particular, armed\ngroups are in control of many detention facilities. The already fragmented Libyan National\nArmy has been further divided, with opposing authorities recognizing different\ncommanders."},{"id":"a-hrc-31-47-p0013","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"13","seq":16,"section":"IV. Armed actors in Libya","text":"The major armed actors active in Libya include Operation Dignity (comprising the\nLibyan National Army and armed groups aligned with General Haftar); Shura Councils,\nincluding Ansar al-Sharia opposed to Operation Dignity; Libya Dawn (comprising Libya\nShield Forces and other armed groups); a coalition of armed groups opposing Libya Dawn;\ntribal armed groups (particularly in the south); and groups pledging allegiance to ISIL."},{"id":"a-hrc-31-47-p0014","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"14","seq":17,"section":"A. Unlawful killings and executions","text":"OHCHR documented a number of unlawful killings, in particular the execution of\nindividuals taken captive or detained/abducted, and assassinations of those voicing dissent.\nReports of unlawful killings were documented in all conflict areas and by most major\ngroupings of armed actors."},{"id":"a-hrc-31-47-p0015","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"15","seq":18,"section":"A. Unlawful killings and executions","text":"In eastern Libya, OHCHR documented six cases in which individuals alleged to be\nmembers or supporters of Ansar al-Sharia were executed after their arrest or capture by\nforces aligned with Operation Dignity. In five of the cases investigated, the families only\nbecame aware of the death of their relatives through photographs posted on social media.\nOne member of the Libyan National Army confirmed having received specific orders from\na superior to kill captured Ansar al-Sharia operatives. Some fighters who surrendered were\nNovember 2015.\nalso killed. OHCHR received information of two similar executions carried out by groups\naffiliated with Libya Dawn, though was unable to verify them."},{"id":"a-hrc-31-47-p0016","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"16","seq":19,"section":"A. Unlawful killings and executions","text":"OHCHR investigated seven cases relating to the assassination of perceived\nopponents to those exercising power, six of which were committed in Benghazi.\nResponsibility for the assassinations was most commonly attributed by interviewees to\nAnsar al-Sharia. Of those targeted, four were human rights defenders, one a judicial actor\nand two alleged Qadhafi supporters."},{"id":"a-hrc-31-47-p0017","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"17","seq":20,"section":"A. Unlawful killings and executions","text":"Groups pledging allegiance to ISIL have engaged in the public execution of civilians\nand persons placed hors de combat, mainly in Sirte and Derna, though also in other areas.\nExamples include the beheading of a group of men, including 20 Egyptian Coptic\nChristians, in early 2015, and the killing of captured fighters in August 2015 whose bodies\nwere subsequently desecrated and publically displayed."},{"id":"a-hrc-31-47-p0018","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"18","seq":21,"section":"A. Unlawful killings and executions","text":"Unlawful killings were also reported in Sabha and Awbari in the south, including the\nshooting of several individuals defending their homes from raids or appropriation by rival\ntribal armed groups."},{"id":"a-hrc-31-47-p0019","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"19","seq":22,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"International humanitarian law requires that parties direct their attacks only against\nlegitimate military objectives, respecting the principles of distinction, proportionality and\nprecaution. Many attacks during the conflict in 2014 and 2015 appear to have been\nindiscriminate in nature, with a particular impact on highly populated residential areas,\nincluding in Benghazi, Tripoli, Warshafana, the Nafusa Mountains areas, and in the south.\nMeasures taken to protect civilians were insufficient. Heavy weaponry, such as Grad\nrockets, which are not appropriate for use in highly populated residential areas given that\nthey cannot target with sufficient precision, have been employed. OHCHR was unable to\ndetermine the parties responsible for many specific attacks owing to the limitations to\naccess and information and the similarity of the weapons being employed by the parties to\nthe conflict in Libya. OHCHR did, however, receive reports of indiscriminate attacks in all\nconflict areas."},{"id":"a-hrc-31-47-p0020","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"20","seq":23,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"In one case investigated by OHCHR, two children were killed when on 26 April\n2015 a residential building in the Al-Hada’eq neighbourhood of Benghazi was hit by a\nrocket. In May 2015, three children were killed and two injured when a shell struck a house\nin Balo’n, in the Al-Fuweihat neighbourhood of Benghazi. It was reported that there was no\nfighting in either area at the time of the attacks, nor were there any known military\nobjectives being pursued."},{"id":"a-hrc-31-47-p0021","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"21","seq":24,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"Indiscriminate attacks also took place in Tripoli and other areas, such as Warshafana\nand the Nafusa Mountains, including Kikla. In one case, a rocket said to have been\nlaunched by Libya Dawn groups in Al-Hashan, a neighbourhood south of Warshafana, hit a\ncar containing a family seeking to escape the shelling, killing three family members. Armed\ngroups affiliated with Zintan were also reported to be using weaponry unsuited for precise\ntargeting in highly populated residential areas, such as Grad rockets, tanks, anti-aircraft\nweaponry and mortar shells."},{"id":"a-hrc-31-47-p0022","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"22","seq":25,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"Groups pledging allegiance to ISIL have conducted suicide bombings, which have\nbeen indiscriminate in their effects. In one case, in Al-Qubba, in February 2015, a vehicle\nloaded with explosives was used to target a national security directorate. Two explosions\ncaused the death of many civilians nearby."},{"id":"a-hrc-31-47-p0023","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"23","seq":26,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"The south has not been spared. In one case investigated by OHCHR, in December\n2014, two Tabu children were seriously injured when a shell struck their house in Al-Daisa,\na neighbourhood east of Awbari. As in other similar cases, no hostilities were reported in\nthe neighbourhood at the time, nor is OHCHR aware of any military objectives being\npursued at that location."},{"id":"a-hrc-31-47-p0024","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"24","seq":27,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"The conflict witnessed attacks against or otherwise with an impact on other persons\nand objects given protection under international humanitarian law, including health\nfacilities, ambulances, medical personnel and humanitarian workers. Attacks were\ndocumented, for instance, against the Tripoli Medical Centre by the “Al-Tajeen Brigade”,\nan armed group affiliated with Libya Dawn and against the Al-Zawiya hospital by\nWarshafana armed groups. Shelling struck other facilities, including the Al-Zahraa City\nhospital. Reports were also received of attacks against ambulances marked with the\ndistinctive Red Crescent symbol in the area around Al-Kufra by Brigade 448. OHCHR\ndocumented cases of abduction and hostage-taking of humanitarian workers by members of\nan Al-Magarha armed group in the south."},{"id":"a-hrc-31-47-p0025","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"25","seq":28,"section":"B. Attacks on civilians and civilian objects, and other protected persons","text":"Private property was appropriated, looted and deliberately destroyed in conflict\nareas. OHCHR investigated four cases in Benghazi in which individuals of western origin\nhad their property taken or destroyed by armed groups affiliated with Operation Dignity,\nincluding the Awliaa al-Damm armed group. Similar reports were received relating to\ngroups affiliated with Libya Dawn in the Warshafana area. Reports were also received of\nthe appropriation and destruction of property by groups pledging allegiance to ISIL."},{"id":"a-hrc-31-47-p0026","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"26","seq":29,"section":"C. Arbitrary detention, abductions and disappearances","text":"It is estimated that more than 9,000 people are currently detained in facilities\noperated by the Ministry of Justice and the Department for Combating Illegal Migration of\nthe Ministry of the Interior.4 This figure does not include the significant number of people\ndetained elsewhere, such as in other facilities operated by the Ministry of the Interior, the\nMinistry of Defence and/or those operated by armed groups.5"},{"id":"a-hrc-31-47-p0027","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"27","seq":30,"section":"C. Arbitrary detention, abductions and disappearances","text":"OHCHR interviewed former detainees who had been arbitrarily detained. Few of\nthose arrested were charged with any criminal offence. Some were unaware of the reasons\nfor their arrest or detention. Virtually none had access to rights of due process and most\nwere denied other rights, such as contact with their families. One example related to a 54-\nyear-old man detained in and around Benghazi in May 2014 by the Libyan National Army\naligned with Operation Dignity, reportedly because he was from Derna, and thus presumed\nto be associated with ISIL."},{"id":"a-hrc-31-47-p0028","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"28","seq":31,"section":"C. Arbitrary detention, abductions and disappearances","text":"Given the limited functioning of courts, there is little recourse to judicial review of\nthe legality of detentions. Even when recourse is available, court orders for release have not\nalways been effective. In one case investigated by OHCHR, in January 2014, a judge\nordered the release of a man in Tripoli. On his way home, however, the man was re-\napprehended by the Tripoli Revolutionaries Brigade and returned to the detention facility."},{"id":"a-hrc-31-47-p0029","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"29","seq":32,"section":"C. Arbitrary detention, abductions and disappearances","text":"In some cases, individuals were abducted for potential ransom or prisoner exchange.\nOne man from Warshafana reported that he was abducted in November 2014 by an armed\ngroup and taken to a facility in Sidi Bilal. His family paid an agreed sum for his release. In\nother cases, people were held until exchanged for individuals held by an opposing group."},{"id":"a-hrc-31-47-p0030","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"30","seq":33,"section":"C. Arbitrary detention, abductions and disappearances","text":"Armed groups in particular also control secret or unrecognized detention facilities.\nOHCHR investigated a number of disappearances attributed to State forces and armed\ngroups6 after the launch of Operation Dignity and Libya Dawn. The cases included the\ndisappearance, on 20 October 2014, of Abd al-Nasser al-Jeroushi, a prosecutor in the South\nBenghazi Court. He is understood to have been abducted by an armed group at a checkpoint\nunder the control of the Al Sai’qa battalion of the Libyan National Army, and has not been\nseen or heard of since. In April 2015, the Ministry of Justice informed UNSMIL that he\nwas being held at an unofficial detention facility in Al-Marj, although the Attorney-\nGeneral’s office reported to OHCHR that it was unable to confirm his whereabouts."},{"id":"a-hrc-31-47-p0031","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"31","seq":34,"section":"D. Torture and other ill-treatment","text":"OHCHR documented numerous cases of torture and other forms of cruel, inhuman\nor degrading treatment or punishment, particularly of individuals in detention facilities.\nIndividuals suffered beatings with plastic pipes or electrical cables, prolonged suspension in\nstress positions, solitary confinement, incommunicado detention and electrocution. Many\nwere also deprived of adequate food or water, were subjected to threats of a sexual nature,\nor to the extortion of payment in exchange for freedom. Torture was frequently reported by\ndetainees as having been perpetrated at the time of arrest, during apprehension or\nquestioning during interrogations, or during detention in facilities operated by the State\nand/or armed groups, as well as in makeshift facilities."},{"id":"a-hrc-31-47-p0032","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"32","seq":35,"section":"D. Torture and other ill-treatment","text":"Torture has resulted in the death of detainees in various facilities, including at the\nAl-Birsis facility, the military police facility in Al-Abyar, the Military Intelligence\nBattalion base in Al-Rajma, Al-Sai’qa military base in Bu’atni, and in a facility reportedly\noperated by the Tripoli Revolutionaries Brigade."},{"id":"a-hrc-31-47-p0033","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"33","seq":36,"section":"D. Torture and other ill-treatment","text":"OHCHR observed a lack of redress for alleged cases of torture and other ill-\ntreatment. One illustrative case was that of a man, arrested in June 2014 by the Criminal\nInvestigations Department of Al-Marj. On the day after his arrest, his body, which\nreportedly showed signs of torture, was transferred to Al-Abyar hospital. The autopsy\nreport concluded that severe internal bleeding had been the cause of his death. The\nProsecutor from Al-Marj sought to question an official on the incident. OHCHR\nunderstands that the Ministry of the Interior denied the request, and the case was closed."},{"id":"a-hrc-31-47-p0034","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"34","seq":37,"section":"E. Gender-based violence and discrimination against women","text":"There has been a series of attacks by armed groups against women promoting\nequality, social justice and accountability in Libya. The assassination of activists, such as\nSalwa Bugaighis, Fareeha Al-Berkawi and Intissar Al-Hasaeri, and the threats, harassment\nand assaults suffered by others appear designed to send a broader message that women\nshould not be vocal in the public sphere."},{"id":"a-hrc-31-47-p0035","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"35","seq":38,"section":"E. Gender-based violence and discrimination against women","text":"OHCHR staff spoke with a number of women who reported that they had been\nsubjected to sexual violence but did not wish to provide detailed accounts or have their\nstories shared publicly for fear of retaliation, perceived stigma, family pressure or trauma.\nOHCHR documented the case of one woman who was abducted in Tripoli by an armed\ngroup affiliated with Libya Dawn, drugged and raped repeatedly over a period of six\nmonths. She also provided information according to which six girls as young as 11 years of\nage had been subjected to sexual violence by members of the same group."},{"id":"a-hrc-31-47-p0036","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"36","seq":39,"section":"E. Gender-based violence and discrimination against women","text":"Many women reported greater challenges to their fundamental rights, such as\nfreedom of movement or the right to work, following the armed conflict of 2011. Some\ndrew attention to religious decrees issued by the Mufti of Libya questioning the equality of\nmen and women as evidence of the entrenchment of a rigid ideology that, when\nimplemented, is harmful to women’s rights. Women in Tripoli and Benghazi experienced\ndifficulties in exercising such rights as freedom of movement owing to the requirement that\nthey be accompanied by “male guardians”. Six women reported difficulties in obtaining\nbasic civil services in Tripoli, such as identification documents, and 12 women described\nrestrictions placed upon their ability to work."},{"id":"a-hrc-31-47-p0037","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"37","seq":40,"section":"E. Gender-based violence and discrimination against women","text":"In areas controlled by groups pledging allegiance to ISIL, some women reported\nhaving been confined to their home owing to the fear of being exposed to harassment,\nabduction and servitude. Older girls and women were not allowed to leave their house\nwithout being fully covered up, including covering their face (niqab). Some women\nreported that they were no longer able to work or to be seen without a male guardian for\nfear of reprisals by groups pledging allegiance to ISIL or Ansar al-Sharia."},{"id":"a-hrc-31-47-p0038","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"38","seq":41,"section":"E. Gender-based violence and discrimination against women","text":"OHCHR also interviewed six women whose access to justice was curtailed out of\ntheir fear of retaliation by armed groups controlling relevant facilities and territories,\nparticularly when reporting crimes committed by the groups."},{"id":"a-hrc-31-47-p0039","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"39","seq":42,"section":"F. Economic, social and cultural rights","text":"Enjoyment of economic, social and cultural rights further declined in Libya in 2014\nand 2015. Most of the causes related to the conflict, although the situation appears to have\nbeen compounded by the economic situation and specific budgetary and planning decisions\nmade by the Government. Women, internally displaced persons, children and migrants\nwere particularly affected. Fighting in and around urban areas has led to the destruction of\nhomes and triggered large-scale displacement; according to UNHCR, the number of\ninternally displaced persons increased sharply from 80,000 in May 2014 to 435,000 in May\n2015."},{"id":"a-hrc-31-47-p0040","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"40","seq":43,"section":"F. Economic, social and cultural rights","text":"According to the Office for the Coordination of Humanitarian Affairs, as at\nSeptember 2015, 1.9 million people in Libya required essential humanitarian aid in order to\nmeet basic health-care needs. The security situation, including attacks against or with an\nimpact on health facilities, health-care and humanitarian workers, and the departure of\nforeign medical personnel owing to the violence have been the dominant causes of\ndisruption to health care. Access to health care has also apparently been compromised by\nthe Government’s limited investment in infrastructure and programme delivery budget cuts.\nStructural and administrative deficiencies regarding emergency preparedness and\ncoordination also had an impact on the response."},{"id":"a-hrc-31-47-p0041","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"41","seq":44,"section":"F. Economic, social and cultural rights","text":"Access to education has been significantly curtailed, particularly in the east; for\nexample, the Office for the Coordination of Humanitarian Affairs estimated in September\n2015 that 73 per cent of all schools in Benghazi were not functioning. Schools have been\neither damaged, destroyed, occupied by internally displaced persons, converted into\nmilitary or detention facilities or are otherwise dangerous to reach. OHCHR investigated\nthe case of a primary school in Benghazi that had been used as a base and detention facility\nby an armed group. Children residing in camps for the internally displaced and children\nwith disabilities face particular challenges in their access to education."},{"id":"a-hrc-31-47-p0042","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"42","seq":45,"section":"F. Economic, social and cultural rights","text":"According to the Office for the Coordination of Humanitarian Affairs, food\ninsecurity affects some 1.2 million people in Libya. In addition to the effects of the conflict,\nthe Government’s decision to reduce or cut food subsidies in November 2015 had an\nadverse impact on access to food. Furthermore, major water networks have been disrupted,\nwhich has affected access to safe drinking water, sanitation and hygiene. OHCHR\ninvestigated one case in Al-Sasiriyah where the water supply was apparently deliberately\ncut by an armed group."},{"id":"a-hrc-31-47-p0043","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"43","seq":46,"section":"G. Administration of justice","text":"Judges and prosecutors were at risk of murder, court bombings, assaults and\nabductions throughout 2014 and 2015. At times, attacks were linked to specific demands,\nsuch as the detention or release of certain individuals, or to thwart the arrest and\nprosecution of armed group members. As a result, courts in Derna, Sirte and Benghazi\nceased their activities in 2014; some courts in parts of Benghazi reopened, though only to a\nlimited extent, in 2015. Courts in Tripoli temporarily suspended activities during the\nfighting in mid-2014."},{"id":"a-hrc-31-47-p0044","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"44","seq":47,"section":"G. Administration of justice","text":"On the basis of the information received, OHCHR assesses that the system for\nproviding security for judicial actors through the Judicial Police is inadequate and flawed.\nThe Judicial Police includes in its ranks thousands of members of armed groups integrated\nwithout any comprehensive vetting programme. According to information received by the\nUNSMIL Human Rights Division, which is supported by OHCHR, only about half of\nJudicial Police officers reported for duty during the fighting in 2014. Even at full strength,\nthe Judicial Police force lacks the capacity and equipment to repel well-armed attacks. In\nmany facilities, control is effectively exercised by armed groups. In the absence of proper\nprotection, the judiciary cannot deliver justice. As a former Minister of Justice told\nOHCHR, “a frightened judge cannot rule”."},{"id":"a-hrc-31-47-p0045","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"45","seq":48,"section":"G. Administration of justice","text":"Since the armed conflict in 2011, thousands of individuals remain detained.\nAccording to the Ministry of Justice, as at March 2014, only 10 per cent of the 6,200 people\nheld in its detention facilities were serving prison sentences following a trial. The vast\nmajority continue to be held without having had their cases properly examined to determine\nwhether sufficient evidence exists for them to be charged or released. It is believed that the\nnumber of conflict-related detainees increased during 2014 and 2015."},{"id":"a-hrc-31-47-p0046","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"46","seq":49,"section":"G. Administration of justice","text":"Owing to the collapse of the criminal justice system in many parts of Libya, victims\nhave little recourse to protection, or to an effective remedy for violations and abuses.\nUNSMIL/OHCHR previously reported that little action had been taken to open prompt,\nthorough, effective, impartial and independent investigations and to bring perpetrators to\njustice.7 To date, there have been very few investigations and no prosecution of leaders or\nmembers of armed groups relating to the events of 2014 and 2015. There is also concern\nthat judicial actors have become compromised by succumbing to pressure from armed\ngroups, and that the system is politicized by events such as the appointment of judges by\nthe General National Congress, whose authority is disputed."},{"id":"a-hrc-31-47-p0047","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"47","seq":50,"section":"H. Human rights defenders and journalists","text":"Human rights defenders have been subjected to particular violations and abuses,\nincluding assassination, attempted murder, abduction, threats, surveillance, and raids on\ntheir homes and offices. Cases of this type have been witnessed predominantly in Benghazi\nand Tripoli. The cases that OHCHR documented were most commonly attributed by\ninterviewees to armed groups affiliated with Ansar al-Sharia or Libya Dawn. The fear\ngenerated by such actions and the impunity enjoyed by perpetrators have forced many to go\ninto hiding or to flee, and threaten to silence independent voices."},{"id":"a-hrc-31-47-p0048","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"48","seq":51,"section":"H. Human rights defenders and journalists","text":"Many attacks have targeted high-profile activists, producing a chilling effect on the\nwork of other human rights defenders. Lawyer and human rights activist Salwa Bugaighis\nwas killed in Benghazi on 25 June 2014 (on the same day as elections for the House of\nRepresentatives), and her husband was disappeared. The perpetrators remain unidentified;\nthe main witness died in police custody. The Prosecutor initially working on the case was\nabducted and remains missing. OHCHR documented other cases, including the\nassassination of human rights defenders Tawfik Ben Sa’ud and Sami Al-Kawafi, who were\nshot dead on 19 September 2014. OHCHR also received eight reports of human rights\ndefenders receiving threatening telephone calls and text messages, as well as, in several\ncases, being subjected to arbitrary detention or attempted assassination."},{"id":"a-hrc-31-47-p0049","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"49","seq":52,"section":"H. Human rights defenders and journalists","text":"The national human rights institution of Libya, the National Council of Civil\nLiberties and Human Rights, has been subjected to attacks in the form of raids on its office\nand threats against its staff, and has been reduced to minimal functioning."},{"id":"a-hrc-31-47-p0050","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"50","seq":53,"section":"H. Human rights defenders and journalists","text":"Journalists have faced serious harassment and death threats; some have been\nsubjected to arbitrary detention, abduction and attempted assassination. Female journalists\nhave also been targeted on the basis of their gender. The deaths of several journalists\nreported to OHCHR require further investigation. Media offices have been raided and\nattacked. Journalists also face criminal prosecution for defamation and libel for writing on\npolitical matters.\nI.       Migrants8"},{"id":"a-hrc-31-47-p0051","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"51","seq":54,"section":"H. Human rights defenders and journalists","text":"Subject to exploitation and abuse by authorities, armed groups and smugglers,\nmigrants are particularly at risk in Libya. Cases of prolonged arbitrary detention and other\ndeprivation of liberty, torture and ill-treatment, forced labour and exploitative labour\npractices, extortion, trafficking and sexual violence, were all reported in the interviews\nconducted by OHCHR. Sub-Saharan Africans are at a heightened risk of abuse and racial\ndiscrimination. Migrant women have faced sexual violence and exploitation both in and\noutside detention facilities."},{"id":"a-hrc-31-47-p0052","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"52","seq":55,"section":"H. Human rights defenders and journalists","text":"Libya has long had a considerable population of migrant workers. It is also a transit\ncountry on the migration routes from East and West Africa to Europe. UNHCR estimate\nthat between January to mid-October 2015, more than 140,000 individuals arrived in Italy\nby sea, the majority of whom departed from Libya."},{"id":"a-hrc-31-47-p0053","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"53","seq":56,"section":"H. Human rights defenders and journalists","text":"According to the International Organization for Migration (IOM), 3,770 individuals\ndied in 2015 attempting to cross the Mediterranean.9 Many of the journeys are undertaken\non dangerously overcrowded and ill-equipped boats, often resulting in scores of deaths. In\naddition to death by drowning, suffocation due to the conditions on board was also\nreported. A Sudanese woman who took the boat from Zuwara to Italy in August 2015\ninformed OHCHR that 35 individuals, forced to sit in a room on the lower deck with no\nventilation, had perished on her boat."},{"id":"a-hrc-31-47-p0054","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"54","seq":57,"section":"H. Human rights defenders and journalists","text":"A large number of migrants are currently detained in Libya without access to\njudicial review. According to UNHCR and IOM, as at 4 May 2015, there were at least\n3,245 migrants detained in facilities in western Libya alone, including 329 women and 34\nchildren.10 Detention conditions are inadequate, often characterized by chronic\novercrowding, poor sanitation and health care, and insufficient food. Violence is endemic.\nA Nigerian man held in a centre in Gheryan reported: “a man spilled his soup. One of the\nguards took out a gun and shot him dead”. OHCHR received credible information\nconcerning the incidence of sexual and gender-based violence against migrants both in\ndetention centres and outside, as well as an increase in female victims of trafficking\narriving in Europe through Libya."},{"id":"a-hrc-31-47-p0055","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"55","seq":58,"section":"J. Tawerghan community","text":"In addition to the difficulties that internally displaced persons encounter in enjoying\ntheir rights, groups perceived as having supported the Qadhafi regime during 2011 are at\nparticular risk of human rights violations and abuses. OHCHR received the greatest number\nof reports of violations and abuses from members of the Tawerghan community, which has\nbeen displaced since the attack by Misrata-based armed groups on Tawergha in August\n2011."},{"id":"a-hrc-31-47-p0056","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"56","seq":59,"section":"J. Tawerghan community","text":"Although progress was witnessed in 2015 in the dialogue between Misratan and\nTawerghan communities to allow for safe returns and reparation (including adoption of a\nroad map in December), OHCHR received reports of difficulties associated with the\ncommunity’s continuing displacement, including reduced livelihoods, ethnic discrimination\nand limited access to education and health services. Tawerghans reported being subject to a\ngreater risk of arbitrary detention and ill-treatment, especially by Misrata-based armed\ngroups."},{"id":"a-hrc-31-47-p0057","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"57","seq":60,"section":"K. Children","text":"Besides being exposed to the threats posed by armed conflict, children in Libya face\nsignificant challenges in enjoying their rights."},{"id":"a-hrc-31-47-p0058","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"58","seq":61,"section":"K. Children","text":"Access to education has been limited by the reduced availability of schools. In\naddition, in many areas where schools remain open, parents refrain from sending their\nchildren to school for fear of injury to them during attacks. In areas controlled by Ansar al-\nSharia, some parents described being afraid to send their girls to school for fear of\nabductions. In areas controlled by groups pledging allegiance to ISIL, OHCHR received\nreports that girls were not allowed to attend school or were permitted only if wearing a full-\nface veil. OHCHR also received reports of girls being attacked and harassed by armed\ngroups on their way to school in Tripoli."},{"id":"a-hrc-31-47-p0059","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"59","seq":62,"section":"K. Children","text":"OHCHR received information on the forced recruitment and use of children in\nhostilities by groups pledging allegiance to ISIL. OHCHR interviewed two boys, aged 10\nand 14 years, who had been forcibly taken from their families. They had been forced to\nundergo religious and military training and to watch videos of beheadings. They were also\nsexually abused. One boy interviewed by OHCHR, who was “attached in service” to a\nforeign fighter and was responsible for cleaning clothes and delivering food, reported that,\nmost evenings, “I knew what I had to do, I had to take my clothes off and turn around and\nbend over facing the wall”. According to a press report, the “Islamic State” in Sirte\nwelcomed the “graduation” of 85 boys below the age of 16, describing them as the\n“Khilapha [Caliphate] Cubs”.11 OHCHR also documented a case in which a child was used\nto detonate a bomb in a vehicle by a group pledging allegiance to ISIL in Derna, in June\n2015."},{"id":"a-hrc-31-47-p0060","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"60","seq":63,"section":"VI. Overall findings","text":"On the basis of the information collected and analysed, there are reasonable grounds\nto conclude that there were widespread violations of international human rights law and\ninternational humanitarian law, and abuses of human rights in Libya throughout 2014 and\n2015. These acts, which were committed by all parties to the conflict in Libya, included\nunlawful killings and executions; indiscriminate attacks, with an impact on civilians and\ncivilian objects; attacks against and attacks having an impact on persons and objects\nprotected under international humanitarian law; unwarranted destruction, appropriation and\nlooting of private property; cases of arbitrary detention, abduction and disappearances,\nincluding enforced disappearances; torture and other cruel, inhuman or degrading treatment\nor punishment; sexual and gender-based violence, and other forms of gender-based\ndiscrimination; and violations of economic, social and cultural rights."},{"id":"a-hrc-31-47-p0061","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"61","seq":64,"section":"VI. Overall findings","text":"Judicial actors and court facilities have been attacked. Human rights defenders and\njournalists have been subject to intimidation and attacks, including assassinations. Women\nhave faced additional repressive measures curtailing their freedoms. Migrants have been\narbitrarily detained or deprived of their liberty, frequently in inhumane conditions, and\nsubjected to financial exploitation and forced labour. Tawerghan community members have\nbeen subjected to discrimination, and reported having been subjected to arbitrary detention\nand ill-treatment. Children have faced challenges to their enjoyment of their rights,\nincluding education. Groups pledging allegiance to ISIL have forcibly recruited and used\nchildren in hostilities and, in some cases, subjected them to sexual abuse."},{"id":"a-hrc-31-47-p0062","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"62","seq":65,"section":"VI. Overall findings","text":"Violations and abuses have not been limited to one area of Libya or to one actor;\nOHCHR documented such acts having also been perpetrated by State actors and armed\ngroups, some of which affiliated with Libya Dawn or Operation Dignity. Other groups may\nbe acting independently. Some actors were named with particular frequency during the\ninvestigation as being responsible for violations and abuses, including Operation Dignity\nforces and armed groups, such as the Al-Sai’qa Brigades of the Libyan National Army and\nAwliaa al-Damm; armed groups affiliated with Libya Dawn; Ansar al-Sharia; groups\npledging allegiance to ISIL; and tribal armed groups in the south. Allegations were\nnonetheless not limited to these particular groups; other non-State actors, such as\nsmugglers, also committed human rights abuses."},{"id":"a-hrc-31-47-p0063","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"63","seq":66,"section":"VI. Overall findings","text":"There appears to be no effective oversight or accountability in Libya in relation to\nthe commission of violations and abuses. No party to the conflict appears to have been\nexercising its responsibilities to address violations or abuses, nor have State authorities\nexercised their responsibilities to provide effective remedies to victims, to prevent future\nviolations or abuses and to ensure non-repetition."},{"id":"a-hrc-31-47-p0064","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"64","seq":67,"section":"VI. Overall findings","text":"Many of the violations and abuses documented may amount to war crimes and other\ncrimes under international law. With regard to war crimes, they included subjecting persons\ntaking no active part in hostilities to violence to life and person (including murder,\nmutilation, cruel treatment and torture); the taking of hostages; executions without any prior\npronouncement of a judgement by a regularly constituted court; directing attacks against\nthe civilian population; directing attacks against buildings, medical units and transport and\npersonnel bearing distinctly the emblems of the Geneva Convention; intentionally directing\nattacks against humanitarian personnel; pillaging; rape and other forms of sexual violence;\nthe conscription or enlistment of children under the age of 15 years or using them to\nparticipate actively in hostilities; and destroying or seizing the property of an adversary."},{"id":"a-hrc-31-47-p0065","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"65","seq":68,"section":"VI. Overall findings","text":"The above-mentioned acts should be immediately and fully investigated as part of a\ncomprehensive criminal investigation, and those responsible should be brought to justice."},{"id":"a-hrc-31-47-p0066","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"66","seq":69,"section":"VII. Assessment of the justice sector, and moving towards","text":"The justice system has been significantly compromised by the security situation and\nstructural weaknesses. Both aspects require attention to ensure access to justice and\nconsolidation of the rule of law. Building on the reforms commenced after 2011, it is\nimportant that efforts be renewed to strengthen the justice system."},{"id":"a-hrc-31-47-p0067","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"67","seq":70,"section":"VII. Assessment of the justice sector, and moving towards","text":"The sheer number of allegations of gross violations of international human rights\nlaw, serious violations of international humanitarian law and serious abuses of human\nrights, and the fact that they have been committed by so many different parties in disparate\ngeographical areas, present enormous challenges, in particular in overcoming the prevailing\nimpunity and fostering accountability."},{"id":"a-hrc-31-47-p0068","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"68","seq":71,"section":"VII. Assessment of the justice sector, and moving towards","text":"Criminal justice accountability in Libya is currently being pursued through both the\nInternational Criminal Court and the Libyan justice system."},{"id":"a-hrc-31-47-p0069","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"69","seq":72,"section":"VII. Assessment of the justice sector, and moving towards","text":"In its resolution 1970 (2011), the Security Council referred the situation of Libya to\nthe Prosecutor of the International Criminal Court. The Prosecutor of the Court affirmed\nher belief that the crimes under international law committed in 2014 and 2015 fell within\nthe purview of the referral. The Prosecutor also noted, however, that capacity to pursue\nthese cases had been hampered by resource constraints.12 The High Commissioner supports\nresourcing the Court further to enable it to expand its investigations into the events since\n2014 as vital for breaking the cycle of impunity in Libya. It is however clear that the Court\nis not designed to address, and will never be able to pursue, such a large number of cases\nrelating to crimes under international law arising in Libya."},{"id":"a-hrc-31-47-p0070","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"70","seq":73,"section":"VII. Assessment of the justice sector, and moving towards","text":"While the Government bears primary responsibility for investigating and\nprosecuting those responsible for serious violations and abuses, it appears that the justice\nsystem does not presently have the means or capacity to be able to conduct prompt,\nindependent and credible investigations into allegations or to prosecute those responsible in\na manner consistent with human rights. Challenges relate to the lack of protection for\njudicial actors, victims and witnesses; limitations in the legal framework and the capacities\nof the judicial system; and, in some quarters, the lack of confidence in the ability of the\njustice system to render impartial justice, particularly in “political cases” relating to the\nconflict."},{"id":"a-hrc-31-47-p0071","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"71","seq":74,"section":"VII. Assessment of the justice sector, and moving towards","text":"Priority actions needed include addressing the security threats to the administration\nof justice, particularly by armed groups, and reform of the judicial police (including\ncomprehensive vetting in accordance with standards of due process, and ensuring\nappropriate training and equipment) so that it can provide effective and impartial protection\nfor judicial actors and court facilities. Robust victim and witness protection is required to\nallow individuals to come forward with information and to engage in proceedings."},{"id":"a-hrc-31-47-p0072","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"72","seq":75,"section":"VII. Assessment of the justice sector, and moving towards","text":"Continued reform of the Penal Code and the Code of Criminal Procedure is\nimportant to ensure that crimes under international law are criminalized under domestic\nlaw, and that provision is made for the differing modes of criminal responsibility\nrecognized in international law (including command and superior responsibility). Personnel\ncould be further trained in investigation, prosecution and adjudication of crimes under\ninternational law. Given the large number of cases arising in 2014 and 2015, effective case\nselection and management systems should be established."},{"id":"a-hrc-31-47-p0073","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"73","seq":76,"section":"VII. Assessment of the justice sector, and moving towards","text":"Trust in the ability of the justice system to render justice must be re-established.\nMembers of the judiciary and other judicial actors should undergo a further process of\nvetting in accordance with standards of due process, focusing on the removal of persons\nwith responsibility for corruption, bias, incompetence or the commission of human rights\nviolations or abuses. More generally, further measures should be taken to ensure the\nindependence of the judiciary and of investigations; to build the capacity of justice system\nactors (including the Ministry of Justice); to strengthen the provision of legal services; to\nincrease public access to laws; and to monitor performance. A plan of action addressing the\njustice sector should be devised and implemented accordingly."},{"id":"a-hrc-31-47-p0074","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"74","seq":77,"section":"VII. Assessment of the justice sector, and moving towards","text":"In order to maximize the quality and efficiency of proceedings and of technical\nassistance programmes in this area, the Government might consider creating a specialized\njudicial structure within Libyan courts to focus on crimes under international law. The\nstructure would need to be supported by specifically appointed judges, prosecutors,\ninvestigators and lawyers. Its design would have to take into account security concerns,\nincluding with regard to deciding on its location. Consideration could also be given to\ninitially embedding foreign advisers or experts to work in tandem with Libyan officials."},{"id":"a-hrc-31-47-p0075","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"75","seq":78,"section":"VII. Assessment of the justice sector, and moving towards","text":"Significant discussion would be needed to further such efforts. The High\nCommissioner therefore supports the convening of a high-level meeting to bring together\nLibyan actors and international partners to discuss initiatives to foster accountability for the\ngross violations of international human rights law, serious violations of international\nhumanitarian law and serious abuses of human rights committed in Libya, including those\nthat may amount to crimes under international law."},{"id":"a-hrc-31-47-p0076","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"76","seq":79,"section":"VII. Assessment of the justice sector, and moving towards","text":"In addition to criminal investigations and prosecutions, steps should be taken to\nreinvigorate other transitional justice mechanisms, including truth-seeking, reparations and\ninstitutional reform. The measures taken since 2011 (including the law on transitional\njustice, the law on political and administrative isolation and amnesty laws) should be\nreviewed to ensure compliance with international human rights standards and appropriate\ncoverage of the events of 2014 and 2015."},{"id":"a-hrc-31-47-p0077","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"77","seq":80,"section":"VII. Assessment of the justice sector, and moving towards","text":"The High Commissioner also supports the listing of individuals responsible for\nplanning, directing or committing acts that violate applicable international human rights\nlaw or international humanitarian law, or acts that constitute human rights abuses under the\nsanctions regime of the Security Council,13 while urging that sanctions imposed be\naccompanied by rigorous procedural safeguards to guarantee minimum standards of due\nprocess."},{"id":"a-hrc-31-47-p0078","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"78","seq":81,"section":"VIII. Update on technical assistance","text":"In 2015, the UNSMIL Human Rights Division, supported by OHCHR, continued to\nadvise Libyan counterparts on international human rights and rule of law standards.\nUNMSIL/OHCHR supported the Libyan political dialogue process, and provided technical\nassistance on the inclusion of human rights provisions. Ongoing technical assistance has\nbeen extended to a joint Tawergha/Misrata committee to address issues that include the safe\nreturn of Tawerghans to their homes, reparations, accountability of perpetrators and the\nreconstruction of Tawergha."},{"id":"a-hrc-31-47-p0079","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"79","seq":82,"section":"VIII. Update on technical assistance","text":"UNSMIL/OHCHR gave advice to the Constitutional Drafting Assembly on human\nrights provisions, including during a workshop with some members of the Assembly in\nGeneva in February 2015. In November 2015, a meeting was organized for directors of\nLibyan rehabilitation and correction institutions, which led to the adoption of a new Code\nof Ethics and Conduct for the personnel of such institutions. UNSMIL/OHCHR contributed\nto sessions on human rights monitoring and reporting standards during workshops in\nTunisia organized by partner organizations, for personnel from the National Council for\nCivil Liberties and Human Rights as well as civil society organizations. In August 2015,\nUNSMIL/OHCHR convened a meeting of Libyan civil society organizations to learn from\ncomparative experiences of peacebuilding."},{"id":"a-hrc-31-47-p0080","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"80","seq":83,"section":"VIII. Update on technical assistance","text":"Once the Government of National Accord is established, it is expected that the\nUnited Nations will be able to increase its capacity-building activities."},{"id":"a-hrc-31-47-p0081","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"81","seq":84,"section":"IX. Recommendations","text":"Recognizing the urgent need to bring an end to the widespread human rights\nviolations and abuses being committed in Libya, and to provide for justice and\naccountability, the High Commissioner appeals to all parties to the conflict promptly\nto cease hostilities and to support the establishment of a Government of National\nAccord, to move towards a State based on respect for human rights and the rule of\nlaw."},{"id":"a-hrc-31-47-p0082","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"82","seq":85,"section":"IX. Recommendations","text":"Accordingly, the High Commissioner recommends that all parties to the\nconflict:\n(a)   Desist immediately from all violations of international human rights law\nand international humanitarian law and abuses of human rights, including those\namounting to crimes under international law;\n(b)    Declare that such acts will not be tolerated and remove those suspected\nof such acts from active duty pending investigation."},{"id":"a-hrc-31-47-p0083","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"83","seq":86,"section":"IX. Recommendations","text":"The High Commissioner recommends that the Government of Libya:\n13   See Security Council resolution 2213 (2015), para. 11.\n(a)    Ensure that all people within the territory of Libya whose rights have\nbeen violated are afforded an effective remedy;\n(b)   Ensure prompt, thorough and effective investigations by independent\nand impartial bodies of allegations of violations and abuses, and that those responsible\nare held accountable;\n(c)     Address urgently the proliferation of armed groups, including by\ninstituting a programme of disarmament, demobilization and reintegration;\n(d)    Resume State-building activities as soon as feasible, with a particular\nfocus on building inclusive institutions, effective law enforcement agencies, an\nindependent and impartial justice sector and a unified armed force operating under\ncivilian control;\n(e)    Institute a comprehensive vetting programme compliant with standards\nof due process to remove and prevent the recruitment into State services – including\narmed forces, law enforcement and judicial services – of individuals about whom\nthere are reasonable grounds to believe they have been involved in violations of\ninternational human rights law or international humanitarian law, or abuses of\nhuman rights;\n(f)    Address the situation of conflict-related detainees, including by ensuring\nthat the State is in control of all detention facilities, and that the cases of detainees are\nappropriately screened with a view to either charge or release them in accordance\nwith international standards;\n(g)     Ensure the proper treatment of all individuals in detention or deprived\nof liberty, including by eliminating torture and other ill-treatment, including sexual\nviolence; access must be ensured to medical treatment, sufficient food and water.\nDetainees should have access to legal counsel and courts to seek legal review, as well as\nto their families and other relevant individuals. International and national monitoring\norganizations should be permitted regular, unhindered and without-notice access to\nall places of detention;\n(h)     Support the independence of the National Council for Civil Liberties and\nHuman Rights, and ensure its ability to operate safely and in accordance with\ninternational standards;\n(i)     Respect and promote the role of civil society, including by ensuring the\nprotection of human rights defenders and journalists;\n(j)    Address urgently the situation of migrants to ensure that all individuals,\nregardless of their status, are able to enjoy their human rights, including by adopting\nand implementing an effective refugee status determination procedure and\nimplementing alternatives to migration-related detention, and taking effective action\nto combat human trafficking;\n(k)    Facilitate the voluntary return of persons who are currently internally\ndisplaced, including the Tawerghan community, in a safe and dignified manner;\n(l)   Ensure respect for the rights of children, including by combating\nrecruitment and the use of children by groups pledging allegiance to ISIL, and\nredressing gaps in children’s enjoyment of rights, including the right to education;\n(m) Take effective action to eliminate sexual and gender-based violence,\nincluding by implementing a gender-sensitive protection and reporting mechanism\nand providing rehabilitation services and access to justice for victims;\n(n)    Review budgetary arrangements that limit funding for programmes\nrelating to economic and social rights (such as food, education and health care), and\ntake immediate steps to remedy damage to facilities and to bolster systems of\nemergency response, including through coordinated international assistance;\n(o)    In relation to further criminal justice accountability measures:\n(i) Extend full cooperation with and support for the International\nCriminal Court by assisting its investigations and complying with its\nrulings;\n(ii) Consider the establishment of a specialized judicial structure within\nLibyan courts to focus specifically on crimes under international law,\nsupported by specifically appointed judges, prosecutors, investigators\nand lawyers, with the possibility of at least initially embedding\nforeign advisers or experts to work in tandem with Libyan officials;\n(p)    With regard to the justice sector:\n(i) Urgently ensure protection for judges, prosecutors and other justice\nsystem staff and courts;\n(ii) Implement an effective witness protection programme;\n(iii) Prioritize reform of the Penal Code and the Code of Criminal\nProcedure to encompass violations of international human rights and\nhumanitarian law, including crimes under international law, and\nensure that procedures are consistent with international human\nrights standards;\n(iv) Institute a vetting programme of the judicial police, the judiciary and\nother justice system actors in accordance with standards of due\nprocess to remove and prevent the recruitment of individuals about\nwhom there are reasonable grounds to believe that they have been\ninvolved in human rights violations or abuses, or are responsible for\ncorruption, bias or incompetence;\n(v) Devise and implement a plan of action to strengthen the justice\nsector;\n(q)    Review transitional justice measures introduced after 2011 with a view\nto ensuring compliance with international human rights standards, and appropriate\ncoverage of events in 2014 and 2015. Future transitional justice initiatives should be\nbased on genuine, inclusive national consultations, with a particular focus on victim\ncommunities."},{"id":"a-hrc-31-47-p0084","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"84","seq":87,"section":"IX. Recommendations","text":"The High Commissioner recommends that the international community:\n(a)    Support the International Criminal Court, particularly by providing the\nOffice of the Prosecutor with the resources necessary to investigate and prosecute the\nalleged crimes under international law committed in Libya since 2014;\n(b)   Provide assistance to strengthen the capacity of the justice and related\nsectors, and provide support to transitional justice mechanisms that are compliant\nwith international standards;\n(c)     Support the convening of a high-level meeting in consultation with the\nLibyan authorities to bring together Libyan actors and international partners to\ndiscuss initiatives to increase accountability in Libya;\n(d)    Prioritize support for a programme of demobilization, disarmament and\nreintegration of members of armed groups, to be conducted in compliance with\ninternational human rights standards;\n(e)  Apply stringent screening procedures to recipients of technical assistance\nor other persons involved in peacekeeping or military exchanges or training\nprogrammes;\n(f)    Ensure protection of and practical assistance to Libyan human rights\ndefenders (including by facilitating emergency visas, temporary shelter and relocation\nwhere necessary), and consider the establishment of a fund to support human rights\ndefenders at risk;\n(g)     Ensure respect for the principle of non-refoulement, and provide\nprotection, in accordance with international law, for those with a well-founded fear of\npersecution."},{"id":"a-hrc-31-47-p0085","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"85","seq":88,"section":"IX. Recommendations","text":"The High Commissioner recommends that the Human Rights Council:\n(a)   Continue to monitor developments in Libya and, to that end, to consider\nthe establishment of a mandate of independent expert on Libya, to report to the\nCouncil on progress made towards accountability and on the situation of human\nrights;\n(b)   Encourage relevant special procedure mandate holders to make visits to\nLibya when feasible;\n(c)   Share a copy of the present report with the General Assembly and the\nSecurity Council for deliberation."},{"id":"a-hrc-31-47-p0086","rec_id":"rec1EBCegpqCdTa7t","symbol":"A/HRC/31/47","n":"86","seq":89,"section":"IX. Recommendations","text":"The High Commissioner recommends that the Security Council:\n(a)   Take action with respect to listing individuals responsible for violations\nor abuses under the current sanctions regime of the Security Council, while ensuring\nthat any sanctions imposed are accompanied by rigorous procedural safeguards that\nguarantee minimum standards of due process;\n(b)    Increase the capacity of the Human Rights Division of UNSMIL to carry\nout monitoring and capacity-building activities, and mandate UNSMIL to undertake\nappropriate follow-up to the findings and recommendations contained in the present\nreport."},{"id":"a-hrc-31-crp-3-u0000","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":0,"section":null,"text":"Human Rights Council\nThirty-first session\nAgenda items 2 and 10\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nTechnical assistance and capacity-building","unnumbered":true},{"id":"a-hrc-31-crp-3-u0001","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":1,"section":null,"text":"Summary\nThe present document contains the detailed findings of the investigation by the\nOffice of the United Nations High Commissioner for Human Rights (OHCHR) on Libya.\nThe principal findings and recommendations of OHCHR are provided in document\nA/HRC/31/47.","unnumbered":true},{"id":"a-hrc-31-crp-3-p0001","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"1","seq":2,"section":"A. Mandate","text":"On 27 March 2015, the Human Rights Council adopted its resolution 28/30, in\nwhich it requested the United Nations High Commissioner for Human Rights urgently to\ndispatch a mission to investigate violations and abuses of international human rights law\ncommitted in Libya since the beginning of 2014, and to establish the facts and\ncircumstances of such abuses and violations with a view to avoiding impunity and ensuring\nfull accountability, and to submit to the Council a written report on its findings, which\nshould also contain an update on technical assistance, capacity-building and cooperation\nwith the Government of Libya, with recommendations for future capacity-building needs\nthat include but are not limited to the justice system and accountability. An oral update was\npresented to the Council on 29 September 2015, and was followed by an Interactive\nDialogue on the human rights situation in Libya."},{"id":"a-hrc-31-crp-3-p0002","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"2","seq":3,"section":"A. Mandate","text":"In accordance with the mandate, the mission focused the investigation on violations\nand abuses committed from 1 January 2014, and examined the actions of both State and\nnon-State actors. During the investigation, the Office of the High Commissioner (OHCHR)\nreceived information concerning individuals with alleged responsibility for violations and\nabuses. Considering the importance of this information for its mandate, in particular in\nensuring accountability, OHCHR has recorded this information. For reasons of witness\nprotection, due process, and fair trial guarantees, individual names have not been included\nin this present report, and are retained on a strictly confidential basis by OHCHR."},{"id":"a-hrc-31-crp-3-p0003","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"3","seq":4,"section":"A. Mandate","text":"OHCHR established priorities with regard to the alleged violations and abuses to be\ninvestigated. Particular consideration has been given to the gravity of alleged violations and\nabuses, and the extent to which incidents indicated a pattern of violations and abuses.\nAware of the monitoring already carried out by UNSMIL and OHCHR and other\norganizations during 2014 and 2015,1 this present report seeks to complement these\nassessments and recommendations. In view of the limits related to the investigation team’s\naccess to relevant persons and places some violations or abuses are identified as requiring\nfurther investigation."},{"id":"a-hrc-31-crp-3-p0004","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"4","seq":5,"section":"B. Methodology","text":"As a result of the prevailing security situation in Libya, the Government of Tunisia\nagreed to host the OHCHR investigation team in Tunis. The team was deployed from July\nto December 2015.2"},{"id":"a-hrc-31-crp-3-p0005","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"5","seq":6,"section":"B. Methodology","text":"OHCHR began its work by reviewing available documentation in relation to the\nhuman rights situation in Libya, including Government reports, United Nations reports,\ninternational and Libyan non-governmental organization reports, press reports and audio-\nvisual material, and reports of special procedure mandate holders and treaty bodies. This\nmaterial was used to assist in mapping the nature of alleged violations and in developing\nfurther investigation leads."},{"id":"a-hrc-31-crp-3-p0006","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"6","seq":7,"section":"B. Methodology","text":"A public call for submissions was issued on 29 July 2015, inviting interested States\nMembers of the United Nations, groups and individuals to provide information to OHCHR\nrelated to its mandate. A copy of the call for submissions was disseminated to States\nMembers of the United Nations on 31 August 2015 and redistributed in September 2015. 3\nSpecific invitations were issued to the national human rights institution of Libya, the\nNational Council for Civil Liberties and Human Rights,4 and special procedure mandate\nholders to share their expertise with OHCHR.5 Outreach was also conducted with other\nrelevant office holders of the United Nations including the offices of the Special Adviser on\nthe Prevention of Genocide, the Special Adviser on the Responsibility to Protect, the\nSpecial Representative of the Secretary-General on Sexual Violence in Conflict, and the\nSpecial Representative of the Secretary-General for Children and Armed Conflict. Regular\nmeetings were held with the United Nations Support Mission in Libya (UNSMIL) to\nprovide for coordination of activities."},{"id":"a-hrc-31-crp-3-p0007","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"7","seq":8,"section":"B. Methodology","text":"The Government of Libya 6 expressed its support for the investigation and offered\nassistance should the OHCHR investigation team conduct missions to Tobruk and Al-Baida\nfor which the High Commissioner is grateful. Owing to the security situation, only a one-\nday visit to Tripoli was possible. A list of questions was dispatched to the Government,\nalthough no response had been received as at January 2016. OHCHR staff held meetings\nwith a range of stakeholders (including United Nations entities, Government\nrepresentatives, and non-governmental organization representatives, including human rights\ndefenders) to explain the mandate of the investigation and to invite them to provide\ninformation."},{"id":"a-hrc-31-crp-3-p0008","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"8","seq":9,"section":"B. Methodology","text":"Given the difficult security environment in Libya, the majority of fact-finding\nactivities were undertaken through remote contact with persons in Libya, facilitating the\ntravel of some victims and witnesses to Tunis, and missions. OHCHR undertook missions\nin Tunisia (Tunis, Djerba, Sfax, Sousse, Mahdia), and to Libya (Tripoli), Egypt (Cairo,\nAlexandria), Turkey (Istanbul), Jordan (Amman), and Italy (Rome, Catania and Mineo).\nThe team also consulted satellite imagery provided by the UNITAR Operational Satellite\nApplications Programme (UNOSAT)."},{"id":"a-hrc-31-crp-3-p0009","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"9","seq":10,"section":"B. Methodology","text":"The investigation team met with more than 250 interlocutors, including more than\n200 victims and witnesses. The environment for persons coming forward remained\nchallenging, with many expressing concern about their safety and/or the safety of their\nfamilies in Libya. A particular priority was placed on issues of witness protection. This\nextended to the decision not to include the names of victims and witnesses in this present\nreport, except in the case of some specific high-profile assassinations and enforced\ndisappearances where the details have already been widely reported and it was assessed\nthere were no protection concerns."},{"id":"a-hrc-31-crp-3-p0010","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"10","seq":11,"section":"B. Methodology","text":"As a result of the submissions process, OHCHR received 66 submissions, containing\nmore than 900 individual complaint files.7 Only a limited number of these cases have been\nable to be individually followed up in the time available. However, these cases have been\nused to assist in identifying trends and/or to corroborate other collected accounts. The scope\nof complaints received highlights the magnitude of ongoing violations and abuses being\ncommitted in Libya and the need for further investigations and follow-up."},{"id":"a-hrc-31-crp-3-p0011","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"11","seq":12,"section":"B. Methodology","text":"While considering a range of information, OHCHR has placed a particular emphasis\non first-hand accounts. Findings are made where it has been considered that there are\n“reasonable grounds to believe” that violations and abuses have occurred; that is whenever\nOHCHR has been satisfied that it has obtained a reliable body of information, consistent\nwith other material, based upon which a reasonable and ordinarily prudent person would\nhave reason to believe that such an incident or pattern of conduct has occurred."},{"id":"a-hrc-31-crp-3-p0012","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"12","seq":13,"section":"C. Challenges and constraints","text":"OHCHR faced a number of significant challenges in carrying out its investigation.\nForemost among these was the limited access to Libya owing to the ongoing fighting.\nWorking within existing United Nations security parameters, the team was limited to\ntravelling to Tripoli (Mitiga airport) for a one-day visit. The environment in Libya\nremained hostile for those coming forward with information, and in some cases, victims\nand witnesses initially agreed to speak with OHCHR but did not proceed with being\ninterviewed, citing a distrust or scepticism about the United Nations based upon the\ninternational community’s previous engagement in Libya. The political divisions in Libya\n(reflected in dual authorities operating) and the limited operation of some institutions,\nincluding the National Council for Civil Liberties and Human Rights, also presented\nchallenges."},{"id":"a-hrc-31-crp-3-p0013","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"13","seq":14,"section":"C. Challenges and constraints","text":"Some thematic areas also proved particularly challenging to investigate. Despite\nhaving a specialist adviser on the topic, barriers surrounding the reporting of sexual\nviolence (including stigma, family pressures, and trauma) made this topic difficult to\nexplore by way of first-hand accounts. Without access to Libya, it was not possible to speak\nto persons currently in detention, or to carry out, for example, site visits to locations of\nattacks. The fact that most international organizations are undertaking their work on Libya\noutside of the country, or through local partners within specific security constraints, also\nlimited points of referral to victims and witnesses. Statistical information on the situation in\nLibya, including gender-disaggregated data, also remains scarce. The absence of many\norganizations operating in the south of Libya or in areas controlled by groups pledging\nallegiance to Islamic State in Iraq and the Levant (ISIL) also created a pronounced dearth of\nsecondary information relating to those areas."},{"id":"a-hrc-31-crp-3-p0014","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"14","seq":15,"section":"C. Challenges and constraints","text":"Notwithstanding these constraints, OHCHR was able to gather a substantial body of\ninformation, leading to the finding that there are reasonable grounds to believe that gross\nviolations of international human rights law, serious violations of international\nhumanitarian law, and serious abuses of human rights have been committed in Libya. The\nHigh Commissioner stresses the need for ongoing international attention to ensure the\neffective, prompt, and thorough investigation of these violations and abuses, and that those\nresponsible are held accountable."},{"id":"a-hrc-31-crp-3-p0015","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"15","seq":16,"section":"D. Acknowledgements","text":"Gratitude is expressed for all the assistance provided by so many in connection with\nthe investigation. First and foremost, the High Commissioner wishes to express his\nprofound appreciation to the victims, witnesses, human rights defenders, and other\ninterlocutors who shared their experiences with the investigation team. The High\nCommissioner expresses his appreciation to the Government of Tunisia for hosting the\nteam, and to all those who assisted in relation to OHCHR field missions, particularly the\nGovernments of the States concerned: Libya, Egypt, Turkey, Jordan and Italy; the relevant\nUnited Nations Resident Coordinators; the United Nations Development Programme\n(UNDP); and the United Nations Department of Safety and Security. Special mention\nshould be made of UNSMIL and its Human Rights, Transitional Justice, and Rule of Law\nDivision which provided extensive assistance to the team. A number of other United\nNations entities (including the United Nations Children's Fund (UNICEF) and the Office of\nthe United Nations High Commissioner for Refugees (UNHCR)), intergovernmental\norganizations (including the International Organization for Migration (IOM)), and\nnumerous national and international non-governmental organizations generously shared\ninsights and background information in relation to the situation in Libya. The United\nNations Entity for Gender Equality and the Empowerment of Women (UN-Women) and\nthe Operational Satellite Applications Programme (UNOSAT) also provided valuable\nassistance."},{"id":"a-hrc-31-crp-3-p0016","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"16","seq":17,"section":"II. International legal framework","text":"The investigation was carried out considering Human Rights Council resolution\n28/30 as a whole and taking into account the approach of previous investigative missions\nmandated by the Human Rights Council. The investigation was conducted within the\nframework of all relevant international legal norms, including international human rights\nlaw, international humanitarian law and international criminal law. The general legal\nframework used by OHCHR is set out in the following paragraphs, with more detail of the\nrelevant legal norms presented within each individual Section of Chapter V which\naddresses specific violations and abuses.8"},{"id":"a-hrc-31-crp-3-p0017","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"17","seq":18,"section":"A. International human rights law","text":"Libya is obliged to respect, protect, promote, and fulfil the human rights of all\npersons within its territory and subject to its jurisdiction, without discrimination. This\nincludes the obligation to ensure a prompt, adequate, and effective remedy to those whose\nrights have been violated, including the provision of reparations and guarantees of non-\nrecurrence and to investigate and bring to justice perpetrators of gross violations."},{"id":"a-hrc-31-crp-3-p0018","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"18","seq":19,"section":"A. International human rights law","text":"Libya is a State party to eleven of the eighteen core human rights treaties: the\nInternational Covenant on Civil and Political Rights (ICCPR) and its first Optional Protocol\n(ICCPR-OP1); the International Covenant on Economic, Social and Cultural Rights\n(ICESCR); the Convention against Torture and Other Cruel Inhuman or Degrading\nTreatment or Punishment (CAT); the International Convention on the Elimination of all\nForms of Racial Discrimination (CERD); the Convention on the Elimination of All Forms\nof Discrimination against Women (CEDAW) and its Optional Protocol; the International\nConvention on the Protection of the Rights of All Migrant Workers and Their Families\n(ICRMW); and the Convention on the Rights of the Child (CRC) and its Optional Protocols\non the Involvement of Children in Armed Conflict (OP-CRC-AC), and on the Sale of\nChildren, Child Prostitution and Child Pornography (OP-CRC-SC). In addition, Libya has\nsigned, but not ratified the Convention on the Rights of Persons with Disabilities (CRPD).\nLibya is also bound by relevant rules of international human rights law which form a part of\ncustomary international law."},{"id":"a-hrc-31-crp-3-p0019","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"19","seq":20,"section":"A. International human rights law","text":"There are a range of instruments that assist in understanding and delineating human\nrights obligations, including the Declaration on the Protection of Persons from Enforced\nDisappearances;9 the Guiding Principles on Internal Displacement;10 the Basic Principles on\nthe Use of Force and Firearms by Law Enforcement Officials;11 the Updated Set of\nPrinciples for the Protection and Promotion of Human Rights through Action to Combat\nImpunity;12 and the Basic Principles and Guidelines on the Right to a Remedy and\nReparation for Victims of Gross Violations of International Human Rights Law and Serious\nViolations of International Humanitarian Law.13"},{"id":"a-hrc-31-crp-3-p0020","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"20","seq":21,"section":"A. International human rights law","text":"Libya has not submitted any declaration of a state of emergency under article 4 of\nICCPR. Even were the Libyan authorities to do so, there are a wide range of rights which\nare either explicitly or implicitly non-derogable under the ICCPR.14 International human\nrights law applies at all times.15 The concurrent application of international humanitarian\nlaw and international human rights law in situations of armed conflict means that the\nprovisions of the two bodies of law should be read together and reconciled as far as\npossible."},{"id":"a-hrc-31-crp-3-p0021","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"21","seq":22,"section":"B. International humanitarian law","text":"With a non-international armed conflict occurring in Libya during the mandate\nperiod, OHCHR also took into account international humanitarian law."},{"id":"a-hrc-31-crp-3-p0022","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"22","seq":23,"section":"B. International humanitarian law","text":"International humanitarian law regulates the conduct of parties to an armed conflict.\nLibya is a party to the four Geneva Conventions of 12 August 1949. It is also a party to\nAdditional Protocol I and II to the Geneva Conventions. Libya is also a party to a range of\nspecialist conventions including the Geneva Protocol on Asphyxiating or Poisonous Gases,\nand of Bacteriological Methods 1925; the Convention on the Prohibition of Biological\nWeapons; the Convention prohibiting Chemical Weapons 1993; and the Hague Convention\nfor the Protection of Cultural Property 1954, and its two protocols. In addition, all parties to\nthe conflict are bound alike by the relevant rules of customary international law applicable\nin non-international armed conflict."},{"id":"a-hrc-31-crp-3-p0023","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"23","seq":24,"section":"B. International humanitarian law","text":"Common article 3 to the Geneva Conventions (applying to conflicts not of an\ninternational character) is applicable to the situation in Libya. In addition Additional\nProtocol II to the Geneva Conventions relating to the protection of victims of non-\ninternational armed conflict is applicable to the State forces and those armed groups with\nthe requisite level of organization and control.16 Common article 3 to the Geneva\nConventions and Additional Protocol II contain protections applicable to civilians and other\npersons not taking a direct part in hostilities. Common article 3 binds all parties to the\nconflict to respect, as a minimum, that persons taking no active part in hostilities, including\nthose placed hors de combat, shall be treated humanely, without any adverse distinction.17\nParties to conflicts must, at all times, abide by the principles of distinction, proportionality\nand precautions in attack.18 This means that parties must distinguish between civilian\npersons and objects on the one hand, and lawful military targets on the other, and that only\nmilitary persons and objects are legitimate targets of attacks.19 Attacks that are expected to\ncause incidental loss of life, injury to civilians, damage to civilian objects or a combination\nthereof, which would be excessive in relation to the concrete and direct military advantage\nanticipated, are prohibited.20 Parties must take all feasible precautionary measures to avoid\nand in any event to minimize incidental loss of civilian life, injury to civilians, and damage\nto civilian objects.21"},{"id":"a-hrc-31-crp-3-p0024","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"24","seq":25,"section":"B. International humanitarian law","text":"States must apply fully the relevant norms of international humanitarian law and\ninternational human rights law to women and girls, and take special measures to protect\nwomen and girls from gender-based violence during armed conflict.22"},{"id":"a-hrc-31-crp-3-p0025","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"25","seq":26,"section":"C. International criminal law","text":"International criminal law governs the situations in which individuals can be held\nindividually criminally responsible for gross violations of international human rights law\nand serious violations of international humanitarian law which amount to crimes under\ninternational law. States have the primary obligation to ensure accountability for these\ncrimes. To comply with this obligation, States must ensure that their domestic legislation\nincorporates the necessary legal basis to enable domestic courts to duly exercise jurisdiction\nover such crimes, in accordance with applicable principles of customary and treaty law.23"},{"id":"a-hrc-31-crp-3-p0026","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"26","seq":27,"section":"C. International criminal law","text":"While Libya has not become a party to the Rome Statute of the International\nCriminal Court, the Security Council referred the situation of Libya since 15 February 2011\nto the Prosecutor of the Court in its resolution 1970 (2011). The continuing jurisdiction of\nthe Court over Libya including contemporary crimes has been affirmed by the Prosecutor of\nthe International Criminal Court. 24 In successive resolutions, the Security Council has\ncalled for ongoing cooperation with the Court.25"},{"id":"a-hrc-31-crp-3-p0027","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"27","seq":28,"section":"D. State duty to investigate and prosecute, and provide an effective remedy","text":"As noted in this present report, States are obliged to investigate and prosecute gross\nviolations of international human rights law and serious violations of international\nhumanitarian law, in particular those that amount to crimes under international law. 26\nStates’ investigations into such allegations must be carried out by independent and\nimpartial bodies and be prompt, thorough, and effective. 27 To be in a position to prosecute\ncases where sufficient evidence exists, States must ensure that their domestic legislation has\n23   Updated Set of Principles for the Protection and Promotion of Human Rights through Action to\nCombat Impunity, principles 20, 21.\n24   See for instance, the affirmation that the International Criminal Court jurisdiction granted by virtue of\nSecurity Council resolution 1970 “prima facie extends to contemporary crimes committed on the\nterritory of Libya”: Ninth Report of the Prosecutor of the International Criminal Court to the UN\nSecurity Council pursuant to UNSCR 1970 (2011), 12 May 2015 para. 19; reaffirmed in the Tenth\nReport of the Prosecutor of the International Criminal Court to the Security Council pursuant to\nUNSCR 1970 (2011), 26 October 2015, para. 22.\n25   See for instance, Security Council resolution 2213 (2015) and Security Council resolution 2238\n(2015).\n26   The duty to investigate human rights violations arises as a result of the duty of States to provide an\neffective remedy and provide effective protection of human rights, but is also made explicit in a\nnumber of human rights treaties: e.g. CAT, art.12. The duty to prosecute attaches to human rights\nviolations amounting to crimes under either national or international criminal law and is explicitly\nreferred to in a variety of treaties: e.g. Genocide Convention, art.1; CAT, arts. 4 and 7, and has been\nreferred to more broadly by the Human Rights Committee, in General Comment No. 31, Nature of the\nGeneral Legal Obligation on States Parties to the Covenant, CCPR/C/21/Rev.1/Add.13 (2004). The\nduty to investigate and prosecute serious violations of international humanitarian law is recognized in\ncustomary international law: see ICRC Study on Customary International Humanitarian Law, rule\n158. The Preamble to the Rome Statute refers to the need to ensure crimes under international law\nmust “not go unpunished” and whose “effective prosecution must be ensured”. See also: United\nNations Basic Principles and Guidelines on the Right to a Remedy and Reparations for Victims of\nGross Violations of International Human Rights Law and Serious Violations of International\nHumanitarian Law, and the Updated Set of Principles for the Protection and Promotion of Human\nRights through Action to Combat Impunity.\n27   Human Rights Committee, General Comment No. 31, para. 15. The Human Rights Committee has\nnoted that a failure to investigate allegations could itself constitute a separate breach of the ICCPR.\nthe necessary legal basis to enable domestic courts to duly exercise jurisdiction over such\ncrimes, in accordance with applicable principles of customary and treaty law. 28 States must\nalso prosecute those with responsibility for crimes under international law and duly punish\nthose convicted.29"},{"id":"a-hrc-31-crp-3-p0028","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"28","seq":29,"section":"D. State duty to investigate and prosecute, and provide an effective remedy","text":"As part of the duty to provide effective remedies, States are obliged to ensure\nreparation for the injuries suffered.30 States must ensure the inalienable right to know the\ntruth about violations and take other necessary steps to prevent a recurrence of violations. 31\nTransitional justice measures need to be designed on an inclusive basis and guided by\nconsultations with the victims. Attention must be devoted to ensuring they are gender-\nsensitive and consider the views and interests of children.32"},{"id":"a-hrc-31-crp-3-p0029","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"29","seq":30,"section":"D. Non-State actors","text":"The present report adopts the approach that non-State actors who exercise\ngovernment-like functions and control over a territory are obliged to respect human rights\nnorms when their conduct affects the human rights of the individuals under their control. 33\nNon-State armed groups that are party to an armed conflict are also bound by international\nhumanitarian law. Further, relevant rules of customary international humanitarian law will\napply to non-State armed groups that are party to an armed conflict. The scope of\ninternational criminal law extends to all individuals."},{"id":"a-hrc-31-crp-3-p0030","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"30","seq":31,"section":"D. Non-State actors","text":"In the current Libyan context, the ability to establish the status of actors as either\nState or non-State entities is difficult, given the fragmented nature of State institutions and\nthe inter-linkages between certain authorities and armed groups. This is described further in\nChapters III and IV of this present report. This report has described where information\nindicating links between actors and the State is available (e.g. financial links or the\nendorsement of acts). However, additional investigation of the operation of armed groups,\nin particular, is crucial to attribute responsibility for violations and abuses."},{"id":"a-hrc-31-crp-3-p0031","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"31","seq":32,"section":"III. Context","text":"2014 and 2015 saw a dramatic decline in the political and security situation in Libya,\nwith the outbreak of hostilities in the east, west and south of Libya. In addition, groups\npledging allegiance to ISIL further emerged as a force, particularly in Derna, Sirte, and\nBenghazi. While there were some specific dynamics in 2014 and 2015, events in Libya\nhave also to be considered against a longer term background."},{"id":"a-hrc-31-crp-3-p0032","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"32","seq":33,"section":"1. Legacy of the Qadhafi period and the armed conflict in 2011","text":"The International Commission of Inquiry for Libya described how the Qadhafi\nperiod was characterised by decades of corruption, sustained repression to any opposition,\nand the perpetration of serious human rights violations, often by the very State agencies\nwith the responsibility to uphold and protect those rights.34 In 2011, an armed conflict\ndeveloped after the Qadhafi regime used force against protestors in a reaction to Libyan\ncitizens’ attempts to exercise democratic freedoms. The situation escalated into an armed\nconflict between opposition armed groups and the Qadhafi regime. The North Atlantic\nTreaty Organization (NATO) intervened under a mandate provided by Security Council\nresolution 1973 (2011) to take all necessary measures to protect civilians and civilian\npopulated areas. In October 2011, the National Transitional Council declared victory for the\nopposition armed groups. While the Qadhafi regime had been toppled, substantial\nchallenges were left for a country with little trust in State institutions, no independent\ninstitutions, nor political parties, nor a judiciary able to provide justice and redress."},{"id":"a-hrc-31-crp-3-p0033","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"33","seq":34,"section":"1. Legacy of the Qadhafi period and the armed conflict in 2011","text":"In the period from 2011 to 2013, Libya experienced political volatility and a\nprecarious security situation. Little progress was made in relation to integrating\n“revolutionary” armed groups into an effective national army or police force. 35 In many\nareas, armed groups remained in control of detention facilities and carried out law\nenforcement functions. In some cases, they were authorized by State authorities to do so,\nwith some armed groups theoretically brought under the Ministry of Justice, Ministry of\nDefence, or Ministry of Interior, even while the level of State control exercised was in\nreality minimal.36 Ongoing tensions and competition for political power and influence at\nnational and local levels became manifest in periodic fighting between various armed\ngroups. As an illustration of the precariousness of the situation, then Prime Minister Ali\nZeidan was abducted for several hours in Tripoli in October 2013.37"},{"id":"a-hrc-31-crp-3-p0034","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"34","seq":35,"section":"2. 2014 and 2015","text":"2014 saw the most serious emergence of hostilities since 2011. 38 While the number\nof clashes and attacks are too numerous to outline in this present report, the major contours\nof the hostilities are described below:\n(a)        The east"},{"id":"a-hrc-31-crp-3-p0035","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"35","seq":36,"section":"2. 2014 and 2015","text":"In the east, in May 2014, retired General Khalifa Haftar launched Al Karamah\n(“Operation Dignity”), reportedly to eradicate “radical…terrorist” groups from eastern\nLibya. An alliance of groups, including Ansar al-Sharia, joined the Benghazi\nRevolutionaries Shura Council to fight forces deployed under Operation Dignity. Concerns\nwere raised about airstrikes deployed in built-up areas and other indiscriminate shelling.39\nOperation Dignity mounted a renewed offensive in Benghazi in mid-October 2014.\nHostilities continued unabated, with increasing reliance on snipers, mortar fire, skirmishes\nand ambushes.40 In August 2015, the Special Representative of the Secretary-General for\nLibya described the situation in the east as “a war of trenches with no imminent end\nforeseen”.41 As at December 2015, hostilities were still ongoing.\n(b)        The west"},{"id":"a-hrc-31-crp-3-p0036","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"36","seq":37,"section":"2. 2014 and 2015","text":"Six weeks of heavy fighting erupted in Tripoli in mid-July 2014, sparked initially by\na reaction to an incident at a checkpoint in the Janzour area. Much of the initial fighting\nfocused on Tripoli International Airport, with an attempt by armed groups affiliated with\nMisrata to wrest control of the airport from armed groups affiliated with Zintan. 42 An\nalliance of armed groups, primarily from Misrata, but also from other towns such as Al-\nZawiya and Gheryan, together with Tripoli-based armed groups launched Fajr Libya\n(“Libya Dawn”) against the armed groups affiliated with Zintan. The campaign included\nairstrikes and shelling of populated areas in Tripoli, resulting in considerable casualties, and\na massive displacement of persons."},{"id":"a-hrc-31-crp-3-p0037","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"37","seq":38,"section":"2. 2014 and 2015","text":"By 24 August 2014, Libya Dawn fighters had gained control of the airport and other\nareas of Tripoli, forcing a withdrawal of armed groups affiliated with Zintan. Libya Dawn\nthen expanded to the Warshafana region until Libya Dawn gained control over the region.43\nWeeks of heavy shelling of the Al-Aziziya and Suwani areas between late August and early\nOctober caused a severe humanitarian crisis with more than 120,000 persons displaced.44 In\nthe Nafusa Mountains, groups affiliated with Zintan launched a counter-offensive, attacking\nthe towns of Kikla and Al-Qala’a. Air strikes were also carried out against Mitiga Airport\nin Tripoli, Misrata, and the Ras Jdair border area by the air force aligned with General\nHaftar.45 Clashes continued into 2015, and included a military offensive by Warshafana\nforces to regain areas in the Warshafana tribal belt, including around Al-Aziziya.46\nIntermittent clashes have since continued, but a range of ceasefire agreements negotiated in\n2015 reduced the intensity of clashes in western Libya.47\n(c)        The south"},{"id":"a-hrc-31-crp-3-p0038","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"38","seq":39,"section":"2. 2014 and 2015","text":"As of the beginning of 2014, the south of Libya was lacking in effective governance\nor security infrastructure. In this environment, tribal groups consolidated their control.\nRivalries over political power, security, and resources escalated into localised conflicts. In\nJanuary 2014, fighting broke out between the Tabu and Awlad Suleiman armed groups in\nSabha. The then-parliament, the General National Congress declared a state of emergency\nand the Libyan National Army carried out airstrikes in order to regain control of the\nTamanhind air force base. Sporadic fighting continued to take place in the south,\nparticularly around the towns of Sabha, Al-Kufra and Awbari, involving Arab, Tabu, and\nTuareg communities, many of whom were allied with either Operation Dignity or Libya\nDawn.48 In September 2014, further forces from Misrata were deployed to Sabha, which\ncontributed to some reduction in hostilities.49"},{"id":"a-hrc-31-crp-3-p0039","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"39","seq":40,"section":"2. 2014 and 2015","text":"Reports in early 2015 indicated that armed conflict between Libya Dawn and\nOperation Dignity had spilled over to southern Libya. In early March 2015, fighting broke\nout in Barak al-Shati between the Misrata Third Force brigade and armed groups drawn\nlargely from the local Al-Megharba and Al-Qadhadhifa tribes.50 Negotiations between\nMisratan and Zintani elders resulted in the military base in Barak al-Shati being placed\nunder local control of the Libyan National Army. Fighting between Tabu and Tuareg armed\ngroups continued in Awbari, particularly focused on control of key oil facilities, roads and\nGovernment buildings, with Libya Dawn and Operation Dignity military coalitions seeking\nto influence tribal leaders.51 Despite various ceasefire agreements, clashes have not abated.\n(d)        Emergence of groups pledging allegiance to ISIL"},{"id":"a-hrc-31-crp-3-p0040","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"40","seq":41,"section":"2. 2014 and 2015","text":"A new dynamic became apparent in Libya in late 2014 with groups pledging\nallegiance to ISIL seeking control of territory and engaging in brutal atrocities. The report\nof the Analytical Support and Sanctions Monitoring Team submitted pursuant to paragraph\n13 of Security Council resolution 2214 (2015) referred to a core group of Libyans returning\nfrom Syria and creating the Al-Battar Brigade in 2012 to support ISIL in Syria and Iraq.52\nIn 2014, many of its members returned to Libya and formed the Islamic Youth Shura\nCouncil in Derna which in October 2014 pledged allegiance to ISIL. 53 These groups\ndeclared eastern Libya as the Wilayat Barqa (Cyrenaica Province) of ISIL."},{"id":"a-hrc-31-crp-3-p0041","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"41","seq":42,"section":"2. 2014 and 2015","text":"Derna, Benghazi and Sirte have been the particular focus of the military operations\nof these groups, with more recent movements into Ajdabiya, Sabratha and the south of\nLibya. Resistance to the groups pledging allegiance to ISIL has been met with brutal force\nand repression. Fighting between these groups and Misratan forces intensified around Sirte\nin March 2015, including through a series of airstrikes targeting the groups. When Misratan\nforces withdrew from Sirte (citing a lack of support from Tripoli authorities and other\nelements within Libya Dawn), the groups pledging allegiance to ISIL took control of the\ncity.54 June 2015 witnessed repeated airstrikes by Misratan forces. In Derna, heavy fighting\ntook place in June 2015 between the Derna Mujahideen Shura Council and groups pledging\nallegiance to ISIL who were ejected from Derna but remain present in surrounding areas.\nOperations have been carried out by Operation Dignity in the area around Derna. Egypt and\nthe United States of America have also carried out airstrikes targeting groups pledging\nallegiance to ISIL. 55\n(e)        Political developments"},{"id":"a-hrc-31-crp-3-p0042","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"42","seq":43,"section":"2. 2014 and 2015","text":"As the hostilities in Libya intensified, competing political structures have been\nestablished."},{"id":"a-hrc-31-crp-3-p0043","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"43","seq":44,"section":"2. 2014 and 2015","text":"The General National Congress was elected to serve as the parliament of Libya in\n2012. Following controversy over its expiry date, an agreement was reached to amend the\nConstitutional Declaration so as to hold national elections in June 2014 to elect a new\nparliament. On 25 June 2014, voting took place for the new parliament, the House of\nRepresentatives, amidst some boycotts and violence."},{"id":"a-hrc-31-crp-3-p0044","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"44","seq":45,"section":"2. 2014 and 2015","text":"Owing to the deteriorating political and security situation in Tripoli, the Government\n(led by Prime Minister Abdullah Al-Thani) left Tripoli and moved to Al-Baida in August\n2014. The House of Representatives convened for the first time in Tobruk in August\n2014,56 and confirmed Abdullah Al-Thani as Prime Minister. The House of Representatives\nendorsed Operation Dignity.57 The Libya Dawn coalition in turn challenged the legitimacy\nof the House of Representatives and called for the General National Congress to\nreconvene.58 The Congress reconvened and appointed a rival government (led by Omar Al-\nHasi). This Congress-appointed government took control of Tripoli-based ministries and\nother State institutions, leading to a situation of parallel ministries."},{"id":"a-hrc-31-crp-3-p0045","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"45","seq":46,"section":"2. 2014 and 2015","text":"In November 2014, the Supreme Court declared unconstitutional the amendment of\nthe Constitutional Declaration which had paved the way for elections to create the House of\nRepresentatives. The circumstances of the handing down of this judgement, and in\nparticular whether it was subject to political or security pressures, have been the subject of\ndebate."},{"id":"a-hrc-31-crp-3-p0046","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"46","seq":47,"section":"2. 2014 and 2015","text":"The term of the House of Representatives expired in October 2015. The House\npassed a resolution on 5 October 2015 allowing for its term to be extended."},{"id":"a-hrc-31-crp-3-p0047","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"47","seq":48,"section":"2. 2014 and 2015","text":"As of the time of the functioning of the investigation team, Libya continued to be\ndivided politically between the Government endorsed by the House of Representatives in\nthe east (which is based in Al-Baida while the House is based in Tobruk) and the\nGovernment endorsed by the General National Congress (based in Tripoli), bifurcating the\nadministration of government. The parallel structures extend to line ministries such as the\nMinistry of Defence, the Ministry of Interior and the Ministry of Justice."},{"id":"a-hrc-31-crp-3-p0048","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"48","seq":49,"section":"2. 2014 and 2015","text":"Following a year-long political dialogue facilitated by UNSMIL, the Libyan\nPolitical Agreement was signed on 17 December 2015 with a view to bringing an end to the\npolitical impasse. It provided for the formation of a Government of National Accord and\nestablished a road map for a transition to a unified governance structure. Localised\nreconciliation efforts have also intensified, for example, between the Misratan and\nTawerghan communities, and the Tabu and Tuareg communities. In addition to addressing\nthe political divide, significant work remains to be undertaken in relation to tackling the\nproliferation of armed groups currently operating in Libya.\n(f)        Humanitarian impact"},{"id":"a-hrc-31-crp-3-p0049","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"49","seq":50,"section":"2. 2014 and 2015","text":"The impact of the armed conflicts and internal instability in Libya in 2014 and 2015\nhas been devastating. The Prosecutor of the International Criminal Court has referred to\nsome 1,539 violent deaths during the period from April to August 2015, with 426 out of\n634 separate incidents resulting in civilian deaths.59 The Prosecutor also estimated that no\nless than 60 civilian deaths per month had been recorded in 2015. 60 As of May 2015, some\n435,000 persons were believed to be internally displaced.61 More than half of the\npopulation of Benghazi was estimated to have left the city,62 and some 120,000 persons\nwere estimated to have been displaced from the Warshafana area alone. 12,000 persons are\nestimated to have been displaced from the south since July 2015.63 Large numbers have fled\nto nearby countries including Tunisia, Egypt and Turkey. Some communities who were\ninternally displaced during the armed conflict in 2011, in particular members of the\nTawerghan community remain unable to return to their homes. Access to services such as\nmedical care has decreased, and a significant proportion of the population face food\ninsecurity. There have been shortages of fuel, water, and electricity alongside extensive\ndamage of necessary public infrastructure and a rise in criminal activity. 64"},{"id":"a-hrc-31-crp-3-p0050","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"50","seq":51,"section":"IV. Armed actors in Libya","text":"Libya does not have a straightforward delineation of State security forces and\nopposition forces. Instead, it has a complex set of armed actors, with varying degrees of\nassociation with the State and each other."},{"id":"a-hrc-31-crp-3-p0051","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"51","seq":52,"section":"IV. Armed actors in Libya","text":"The current security arrangements need to be understood against the background of\nthe security apparatus in place in Libya in previous years. The International Commission of\nInquiry on Libya described an “amorphous” system in which Government forces involved\n“different structures operating in different capacities at different times and at different\nplaces”.65 Power and operational commands shifted according to the directions given by\nQadhafi and his cohorts to a variety of structures (such as the armed forces,\nKata’eb/battalions, revolutionary committees and the revolutionary guard). During 2011, a\nloose coalition of brigades rose up against the Qadhafi forces, with the coalition\nsignificantly strengthened by defecting members from the Qadhafi forces. At the end of\n2011, with the unilateral victory declaration by opposition forces, a large number of\n“revolutionary” armed groups (the armed groups that had fought against Qadhafi) organised\nalong geographical and tribal lines, were effectively in control of large parts of the Libyan\nterritory. The formal structures of the Libyan Army and Police were fractured."},{"id":"a-hrc-31-crp-3-p0052","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"52","seq":53,"section":"IV. Armed actors in Libya","text":"Attempts made in the period from 2011 to 2014 to integrate armed groups into a\ncentral security apparatus under civilian authority were not successful. Armed groups were\nincorporated into transitional security forces, placed under the authority of either the\nMinistry of Defence (Libya Shield Force) or the Ministry of Interior (Supreme Security\nCommittee). Other armed group members were incorporated into the Judicial Police (under\nthe authority of the Ministry of Justice). As noted in this present report, through this\naffiliation, armed groups were officially mandated to carry out security or detention\nfunctions.66 Armed groups received salaries from the State with payments administered\nthough the Central Bank, but the State seemingly retained only nominal oversight or\ncontrol. In reality, many armed groups appear to have continued to act with a high degree\nof autonomy, and maintained their own command structure. Revolutionary armed groups\nhave a significant distrust of any security apparatus or personnel who were active in the\nQadhafi regime, and have been quick to act, including through the use of force, when they\nhave felt excluded from the decision-making process or otherwise disgruntled."},{"id":"a-hrc-31-crp-3-p0053","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"53","seq":54,"section":"IV. Armed actors in Libya","text":"The number of armed groups and the membership thereof has increased\ndramatically. The number of “revolutionaries” (persons who fought in the 2011 conflict\nagainst the Qadhafi regime) was estimated to be approximately 25,000 to 30,000. 67 By\n2013, the Warrior Affairs Commission of the Government had registered some 168,000\npersons as revolutionaries.68 Not all are necessarily currently active in armed groups. One\nGovernment committee reported that it was seeking to integrate 110,000 persons as of May\n2015.69 The comparatively high salary paid to armed group members has provided a\nfinancial incentive for membership, while the deterioration in the security situation has also\nencouraged groups to revert to localised security formations. Notwithstanding the outbreak\nof hostilities, it was reported to OHCHR that the Central Bank in Tripoli continues to pay\narmed groups (even opposing armed groups) in a non-partisan manner.70 In November\n2015, UNSMIL/OHCHR reported that armed groups had proliferated, consolidating\n“effective control over large swaths of territory, strategic installations and State\ninstitutions”.71"},{"id":"a-hrc-31-crp-3-p0054","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"54","seq":55,"section":"IV. Armed actors in Libya","text":"It is apparent that armed groups are divided along various lines, such as tribal,72 or\nideological,73 or by geographic affiliation. 74 Some armed groups pursue specific political\nagendas, others operate as local security, while others might be characterised as being\nfocused on criminal enterprises.75 Armed groups have themselves fractured, and allegiances\nand alliances between groups have shifted in the course of 2014 and 2015. Many armed\ngroups are part of or act in support of either Operation Dignity or Libya Dawn. This present\nreport uses the term “affiliated” in a generic sense to indicate a relationship of support, even\nif the precise parameters of the relationship, including any command and control aspects,\nare not known and require further examination."},{"id":"a-hrc-31-crp-3-p0055","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"55","seq":56,"section":"IV. Armed actors in Libya","text":"The Libyan National Army has been further fragmented by the events of 2014 and\n2015, as is evidenced by the competing appointments and command instructions issued by\nthe House of Representatives and the General National Congress. In 2014, the Congress\nappointed Major General Abd al-Salam al-Obaidy as Commander of General Staff of the\nLibyan National Army. Major General al-Obaidy issued a statement ordering all forces of\nthe Libyan National Army to fight against any military force moving towards Benghazi (a\nreference to Operation Dignity forces) after the launch of Operation Dignity. 76 In August\n2014, the House of Representatives appointed Major General Abd al-Razik al-Nadoory as\nCommander of General Staff of the Libyan National Army. Major General al-Nadoory’s\nfirst statement announced that Libya Dawn forces and Ansar al-Sharia were terrorists, and\nthat the Libyan National Army supported Operation Dignity.77"},{"id":"a-hrc-31-crp-3-p0056","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"56","seq":57,"section":"IV. Armed actors in Libya","text":"In March 2015, the House of Representatives created a new post in the army and\nappointed Khalifa Haftar as General Commander and promoted him to the rank of\nLieutenant-General. The Tripoli-based authorities and the General National Congress,\nhowever, dispute the legitimacy of either this appointment or that of Major General al-\nNadoory, and continue to support Major General al-Obaidy. Many of the brigades of the\nLibyan National Army in the western, central and southern regions of Libya remain under\nMajor General al-Obaidy’s control, and a process was launched to integrate all\nrevolutionary armed groups, including Libya Shield Forces, under his control in late 2014.\nMeanwhile in the east, most existing Libyan National Army formations operate under the\ncommand of Lieutenant-General Khalifa Haftar."},{"id":"a-hrc-31-crp-3-p0057","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"57","seq":58,"section":"IV. Armed actors in Libya","text":"Another factor fuelling the conduct of hostilities is the proliferation of weapons and\nammunition. Large stockpiles of arms and ammunition from the Qadhafi period were left\nunsecured after the armed conflict in 2011. Many of these stockpiles were or have since\nbeen appropriated by armed groups. Additional weaponry has been brought in from outside\nLibya. The result is the highly visible presence of a wide range of weaponry in the hands of\narmed groups, from handguns and rifles, to machine-guns, grenade launchers, and even\nrepurposed anti-aircraft artillery."},{"id":"a-hrc-31-crp-3-p0058","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"58","seq":59,"section":"IV. Armed actors in Libya","text":"The number of security actors in Libya makes a comprehensive mapping difficult.\nAn attempt to depict the major groupings involved in Operation Dignity and Libya Dawn in\n2014 based on information collected by OHCHR is set out in Annex II. 78 More work is\nnecessary in this area to understand the full range of actors, and the alliances and inter-\nlinkages. However, some of the key groupings of armed actors seen in Libya during the\nmandate period are:\nOperation Dignity: forces aligned with General Khalifa Haftar"},{"id":"a-hrc-31-crp-3-p0059","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"59","seq":60,"section":"IV. Armed actors in Libya","text":"In the east, (then retired) General Khalifa Haftar launched Operation Dignity against\n“terrorists” in Benghazi in May 2014. Despite having no formal appointment in the Libyan\nNational Army at that time, commanders of several brigades joined him during the first\nstage of the operation including the Al-Sai’qa Brigades (commando forces) based in\nBu’Atni, and the Air Force Brigade. By the second stage of the campaign, launched in\nOctober 2014, most of the remaining brigades of the Libyan National Army in the east had\njoined his forces, including Al-Zawiya Martyrs 21 Brigade based in Qarionis and the 204\nTank Brigade based in Al-Rahba. In addition, a variety of armed groups have also\nparticipated in the campaign. On the basis of the information received by OHCHR, this\nincludes, for instance, Awliaa al-Damm and Shabab al-Manteq “Al-Sahawat”.\nAnsar al-Sharia79 and Shura Councils opposed to Operation Dignity"},{"id":"a-hrc-31-crp-3-p0060","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"60","seq":61,"section":"IV. Armed actors in Libya","text":"The dominant forces fighting against Operation Dignity in the east of Libya are the\nBenghazi Revolutionaries Shura Council and the Derna Mujahideen Shura Council. Within\nthe Benghazi Revolutionaries Shura Council, there are a number of armed groups including\nAnsar al-Sharia, the Eastern Libya Shield, February 17th Martyrs Brigade, Rafallah al-\nSahati Brigade, and Al-Zintan Martyrs. It was initially formed in June 2014 in specific\nresponse to Operation Dignity. In Derna, the Derna Mujahideen Shura Council was created\nin December 2014. It includes Derna-based Ansar al-Sharia and the Abu Salim Martyrs\nBrigade. Both Shura Councils are believed to be allied with some elements of Libya Dawn.\nLibya Dawn"},{"id":"a-hrc-31-crp-3-p0061","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"61","seq":62,"section":"IV. Armed actors in Libya","text":"Among the groups in Libya Dawn are Libya Shield Forces which bring together a\nvariety of revolutionary armed groups who see themselves as “guardians of the revolution”.\nLibya Shield Forces are divided into three main brigades named after their geographical\nlocations: the eastern, central, and western Libya Shields. The western and Misrata-based\ncentral Libya Shield forces remained dominant in the Libya Dawn coalition in 2014. They\nincorporate into their fold, for example, forces from Zleiten, Al-Khoms, Misillata,\nTarhouna, Jadu, the Nafusa Mountains (Gheryan, Kikla, Jadu and Nalut) and Al-Zawiya.\nArmed groups affiliated with Libya Dawn also include the Tripoli Revolutionaries Brigade,\nDeterrence and Assistance Force, the High Security Committee (Abu Salim Branch), and\nthe Janzour Knights Brigade.\nWestern armed groups (opposed to Libya Dawn)"},{"id":"a-hrc-31-crp-3-p0062","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"62","seq":63,"section":"IV. Armed actors in Libya","text":"Amongst the primary armed groups opposed to Libya Dawn are the Zintan-based\n“Al-Sawa’iq”, “Al-Qa’qa’a” and “Al-Madani” Brigades. The coalition also includes the\nWarshafana-based “Jaysh Al-Qaba’el” armed group, that allegedly includes within its\nmembership some members of the army of the former Qadhafi regime. This coalition is\nbroadly allied with Operation Dignity and General Haftar.\nTribal groups in the south of Libya"},{"id":"a-hrc-31-crp-3-p0063","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"63","seq":64,"section":"IV. Armed actors in Libya","text":"In Sabha, the major armed conflicts have taken place between Tabu, Al-Qadhadhifa,\nand Al-Megharba armed groups opposed to the Awlad Suleiman armed group. In Al-Kufra,\nthe conflict has been primarily between the Arab Al-Zwaya and the Tabu armed groups,\nwith the Tabu accusing Al-Zwaya of favouring their own tribe in relation to, for instance,\nthe provision of government services. Several armed clashes have focused on attempts to\ncontrol strategic locations, such as oil fields or smuggling routes. Some level of alliances\nexists between tribal armed groups and either Operation Dignity or Libya Dawn, for\nexample, it has been observed that the Tabu are generally aligned with Operation Dignity;\nwhile the Tuareg are generally aligned with Libya Dawn.\nGroups pledging allegiance to ISIL"},{"id":"a-hrc-31-crp-3-p0064","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"64","seq":65,"section":"IV. Armed actors in Libya","text":"Groups pledging allegiance to ISIL declared eastern Libya as the Wilayat Barqa\n(Cyrenaica Province) of ISIL, in which society is to be governed by a strict interpretation of\nIslamic Sharia. It has been estimated that groups pledging allegiance to ISIL number no\nmore than 2,000 to 3,000 fighters in Libya. 80 At the height of its operations in Derna, they\nwere said to command around 1,100 fighters in the city. 81 Many of them have since left for\nSirte, where the groups are able to command around 1,500 fighters.82"},{"id":"a-hrc-31-crp-3-p0065","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"65","seq":66,"section":"IV. Armed actors in Libya","text":"All the aforementioned major groupings of armed actors have been implicated in\nhuman rights violations and abuses described in Chapter V of this present report."},{"id":"a-hrc-31-crp-3-p0066","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"66","seq":67,"section":"1. Introduction","text":"The Human Rights Council expressed significant concern in relation to the unlawful\nkilling of individuals in Libya in its resolution 28/30. 83 Through its investigation, OHCHR\nhas documented a number of such unlawful killings, particularly in the form of extrajudicial\nexecutions of persons taken into detention or captivity, and assassinations. These acts\nappear to be undertaken with a callous disregard for human life in order to silence and\ndissuade others from voicing opposition to those exercising military or political control.\nThey have also been used as a crude method to deal with those captured or detained. Cases\nof unlawful killings were reported in all conflict areas. A larger number of such killings\nwere reported to OHCHR in the east of Libya than in other areas. However this should be\nconsidered in light of the intense ongoing hostilities in the east for most of the reporting\nperiod, the operation of groups pledging allegiance to ISIL in the eastern and central\nregions and, potentially, access-related limitations of OHCHR in relation to gathering\ninformation."},{"id":"a-hrc-31-crp-3-p0067","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"67","seq":68,"section":"2. Legal framework","text":"International human rights law prohibits the arbitrary deprivation of life. 84 When a\nState actor employs lethal force, it must be both necessary (e.g. linked to a direct threat to\nlife) and proportionate with no other means available such as warnings, capture, or\nincapacitation.85 Force must be restricted to that necessary in the circumstances and lethal\nforce used only in exceptional circumstances. The Basic Principles on the Use of Force and\nFirearms by Law Enforcement Officials detail the specific circumstances in which those\nwith law enforcement functions may use lethal force. The State is responsible for violations\ncommitted by non-State actors operating in support of or as agents of State authorities.\nWhere militias or paramilitary groups are used to guarantee security, States should bring\nthem under an established chain of command/control and must ensure they comply with\nhuman rights obligations, such as respect for the right to life. 86 States also have a positive\nobligation to protect the right to life and prevent any violation thereof (by non-State actors),\nincluding by putting in place effective criminal justice systems of response.87"},{"id":"a-hrc-31-crp-3-p0068","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"68","seq":69,"section":"2. Legal framework","text":"In situations of active ongoing hostilities, the prohibition on arbitrary deprivation of\nlife needs to be considered by reference also to the rules of international humanitarian law.\nInternational humanitarian law requires parties to an armed conflict to respect the principles\nof distinction, proportionality and precautions in attack. Accordingly, it is unlawful to kill\ncivilians and any persons not taking an active part in hostilities. It is prohibited to kill\nmembers of armed forces who have surrendered, or are otherwise hors de combat (e.g.\ncaptured fighters).88 Murder of any person taking no active part in hostilities, is recognized\nas a war crime during non-international armed conflict. 89 Murder may also constitute a\ncrime against humanity, if committed as part of a widespread or systematic attack against\nany civilian population, with knowledge of the attack.90"},{"id":"a-hrc-31-crp-3-p0069","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"69","seq":70,"section":"2. Legal framework","text":"The application of these different rules to the situation in Libya depends on the\nprecise context in which the situation occurs, and whether it occurs in the context of\nongoing active hostilities."},{"id":"a-hrc-31-crp-3-p0070","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"70","seq":71,"section":"3. Findings","text":"OHCHR documented several cases in which persons alleged to be members or\nsupporters of Ansar al-Sharia or Benghazi Revolutionaries Shura Council were executed\nafter having been apprehended or captured by forces aligned with Operation Dignity. The\ncommission of torture was also reported during the preceding period of detention."},{"id":"a-hrc-31-crp-3-p0071","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"71","seq":72,"section":"3. Findings","text":"In mid-October 2014, a 31 year old man was apprehended and detained while on his\nway to morning prayers at a mosque in Al-Baida. Information from several witnesses\nindicates that he was held in four different locations. During his detention, he was\nreportedly tortured and later executed in a facility operated by the military police in Al\nRajma.91 His corpse was found in the Sidi Khalifa cemetery some 40 kilometres away. His\nbody was recovered and taken to Al-Marj hospital. A photograph of his body along with\nfour others was posted on a social media webpage to help with his identification. The photo\nsuggests that all five men had been executed. Their hands were tied behind their backs and\nthey had been blindfolded. A doctor who examined the body of this man confirmed signs of\ntorture."},{"id":"a-hrc-31-crp-3-p0072","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"72","seq":73,"section":"3. Findings","text":"In another case, a man was apprehended in October 2014 by several armed men\naffiliated with the military police and taken from his store in Al-Baida. He is understood to\nhave been apprehended on charges of affiliation with Ansar al-Sharia. He was taken to\nGernada detention facility where he was held for some 24 hours, before being transferred to\na secret detention facility in Al-Baida, allegedly controlled by the military police. His\nwhereabouts and fate remained unknown to his family until several weeks later when one\nof his friends posted a condolence notice on a social media web page, noting that his body\nhad been found. The forensic report disclosed that he had been shot in the head and chest."},{"id":"a-hrc-31-crp-3-p0073","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"73","seq":74,"section":"3. Findings","text":"In early December 2014, a 40 year old man from the Al Hada’eq neighbourhood in\nBenghazi was apprehended by Brigade 36 of the Al-Sai’qa Brigades of the Libyan National\nArmy on charges of illegal arms possession and of affiliation with Ansar al-Sharia. He was\ntaken to an Al-Sai’qa Brigade site in the Bu’Atni neighbourhood. It is understood he was\nheld incommunicado for several days. Family members were denied access to him, though\nwere given some of his clothes bearing evidence of blood on them, and asked to bring new\nclothes for him. Some two weeks later, his family located his body in Benghazi Medical\nCentre. His body showed signs of torture. The forensic report disclosed that he died as a\nresult of being shot in the head and chest. In another case investigated by OHCHR, the\nwhereabouts of a man apprehended by Brigade 36 remained unknown to his family until\nmid-December 2014. His family were told that a photo of his corpse had been seen on the\ninternet webpage “Al-Abyaar, breaking news”. The same photo was later posted on the\nofficial webpage of Benghazi Medical Centre. When the family received his body from the\nhospital, severe injuries were noted to his face and head."},{"id":"a-hrc-31-crp-3-p0074","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"74","seq":75,"section":"3. Findings","text":"Two relatives were apprehended by members of the Libyan National Army at a\ncheckpoint in October 2014. They had been on their way to their family home, having\nreceived a call informing them that it had been subjected to a rocket-propelled grenade\nattack. After their apprehension, both were detained, tortured and later executed. Their\nbodies were found in the industrial zone in Abu-Hdeyma on 16 October 2014. The death\ncertificates of each disclose that they were shot dead, having sustained bullet wounds on\nseveral parts of their bodies."},{"id":"a-hrc-31-crp-3-p0075","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"75","seq":76,"section":"3. Findings","text":"OHCHR received an account from one member of the Libyan National Army that\nspecific orders had been given to kill captured persons, suggesting that that these\nexecutions may indicate a policy rather than the acts of rogue individuals. This soldier\nconfirmed that his unit killed one Egyptian and one Yemeni man after their capture in the\nAl-Sabri neighbourhood in Benghazi in October 2014. They were brought to the naval base\nin Souq Al-Hoot. The soldier explained that after the two confessed to being members of\nAnsar al-Sharia, they were shot dead in accordance with orders given by their commander."},{"id":"a-hrc-31-crp-3-p0076","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"76","seq":77,"section":"3. Findings","text":"A similar fate was reported in relation to persons who surrendered. In one case four\nbrothers who had been involved in fighting against Operation Dignity forces surrendered\nand were taken to “camp 21” in the Tabilino area, west of Benghazi. When they arrived at\nthe camp, they were allegedly fired upon, with one brother being killed and the other three\nsuffering injuries. Two other brothers were taken to a school building which was being used\nas a military base for Al-Sahawat. After this they were transferred to the Al-Birsis detention\nfacility. One of the brothers was detained for 18 days and reported that he was subjected to\ntorture involving the use of plastic hoses and electric cables. Two days after his release, the\nfamily learnt of the death of the other brother through an internet webpage. His body had\nbeen found in Al-Marj, some 60 to 70 kilometres away from the detention centre.\n(b)   Assassinations by groups affiliated with Benghazi Revolutionaries Shura Council\n(particularly Ansar al-Sharia)"},{"id":"a-hrc-31-crp-3-p0077","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"77","seq":78,"section":"3. Findings","text":"OHCHR received many reports of killings by groups affiliated with Benghazi\nRevolutionaries Shura Council, in particular attributed by interviewees to have been\ncommitted by Ansar al-Sharia, primarily in Benghazi. Most of the cases related to the\nassassination of perceived opponents, including human rights defenders. OHCHR received\na list of 229 persons said to have been assassinated by Benghazi Revolutionaries Shura\nCouncil in the period between 15 December 2013 and 30 November 2014. The majority\nwere military and security personnel (further details of the circumstances of the deaths were\nnot made available). The list also included five human rights defenders, five media\nworkers, two judges, two civil servants, one tribal elder, one student, one doctor, two\nartists, 12 religious preachers (Sheikhs), and 27 other civilians. OHCHR has not been in a\nposition to verify the list, although notes that some of the names on the list are consistent\nwith other information received by OHCHR."},{"id":"a-hrc-31-crp-3-p0078","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"78","seq":79,"section":"3. Findings","text":"Of the cases investigated by OHCHR, one concerned a 61 year old man, who was\nshot dead while driving his car to his work in Benghazi in March 2014. At the time he was\nsome 100 metres from his home. A car intercepted his car, before three masked gunmen\njumped out of a second car. Two gunmen shot at and killed him. It is not known why he\nwas targeted, however it was reported to OHCHR that as a result of his previous business\nactivities, he had strong networks with senior officials of the Qadhafi regime, and hence,\nhad been commonly perceived as pro-Qadhafi."},{"id":"a-hrc-31-crp-3-p0079","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"79","seq":80,"section":"3. Findings","text":"In April 2014, a well-known school headmaster was driving his car on the so-called\n“Third Circular Road”, close to the Arab Medical University near the centre of Benghazi.\nGunmen in a car shot at and killed him. The medical report indicates that he sustained\nbullet injuries in the chest and abdomen, and he was pronounced dead on arrival at the\nhospital. The victim was a well-known advocate for the non-politicization of education, and\nthe need to keep schools operating under all circumstances.\n(c)    The west"},{"id":"a-hrc-31-crp-3-p0080","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"80","seq":81,"section":"3. Findings","text":"Although OHCHR has not received as many first-hand accounts from persons in the\nwest of Libya as in the east, it has received information indicating the commission of\nsimilar violations and abuses there, in particular the execution of persons after their arrest\nor capture. Several cases of such executions by Libya Dawn were reported to OHCHR in\nrelation to the fighting in the Warshafana region from August to September 2014. The\nrestricted access of OHCHR to Warshafana as well as witnesses’ reluctance to provide\ndetails (given security concerns for their families) has reduced the ability of OHCHR to\nverify these cases. However, OHCHR notes the consistency of this alleged fact pattern with\nthat seen elsewhere in Libya, and the reports of summary execution of captured fighters by\nboth Libya Dawn and Warshafana armed groups by other monitoring organizations. 92\n(d)    Groups pledging allegiance to ISIL"},{"id":"a-hrc-31-crp-3-p0081","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"81","seq":82,"section":"3. Findings","text":"Numerous accounts have been received of killings carried out by groups pledging\nallegiance to ISIL. These relate in particular to public executions undertaken with a view to\nmaximising public terror. International attention was generated by a video publicly released\nin February 2015 showing persons from groups alleging allegiance to ISIL beheading a\ngroup of men who were predominantly Egyptian Coptic Christians, in Sirte. In April 2015,\nanother video on social media showed operatives beheading and shooting some 28\nEthiopian and Eritrean nationals.93 OHCHR investigations have confirmed a broader use of\nexecutions and desecrations in areas controlled by these groups against persons taking no\nactive part in the hostilities including those placed hors de combat."},{"id":"a-hrc-31-crp-3-p0082","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"82","seq":83,"section":"3. Findings","text":"OHCHR investigated the aforementioned case of Egyptian Coptic Christians and a\nChadian man who were abducted and beheaded by groups pledging allegiance to ISIL in\nearly 2015. Approximately 20 Egyptian Coptic Christians were abducted in two separate\nincidents. Seven were abducted on the afternoon of 28 December 2014 from a location\napproximately 40 kilometers east of Sirte. They had been travelling home to Al-Uwr\nvillage, in Al Minyaa in southern Egypt for the new year holidays. Two cars intercepted\ntheir vehicle and they were taken to an unknown destination. The second group of 13\nindividuals was taken from their houses in the Al-Ayadaat neighbourhood of Sirte in early\nJanuary 2015. The armed men who raided their houses reportedly brought with them a list\nof Coptic Christians living there, and left unharmed Muslims living in the same houses.\nAmongst the victims of the beheading was also a Chadian man, though the circumstances\nof his abduction are not known."},{"id":"a-hrc-31-crp-3-p0083","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"83","seq":84,"section":"3. Findings","text":"A video of the beheadings was released in February 2015. The killers in the video\nidentify themselves as being from the “Tripolitania Province of the Islamic State”, with one\nexecutioner stating “Oh people, recently you have seen us…chopping off the heads that\nhave been carrying the cross for a long time…Today we are on the south of Rome, on the\nland of Islam, Libya…”.94 The on-line magazine of ISIL, DABIQ, contains numerous\nreferences to the killings, including an article that begins “This month, the soldiers of the\nKhilafah in Wilayat Tarabulus95 captured 21 Coptic crusaders”.96 It acknowledges the\nkillings and provides a form of reasoning for why they chose to “target the Coptic\ncrusaders”. The beheadings were claimed as revenge for “sisters who were tortured and\nmurdered by the Coptic Church of Egypt” five years previously. It went on to state:\n“Therefore the Islamic State leadership decided to target the Catholic Christians of\nBaghdad so as to teach the taghut of the Copts – Shenouda – that the price of\nMuslim blood is costly and so accordingly, if his church persecuted any Muslimah in\nEgypt, he would be directly responsible for every single Christian killed anywhere in\nthe world when the Islamic State sought it’s just revenge…”.97"},{"id":"a-hrc-31-crp-3-p0084","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"84","seq":85,"section":"3. Findings","text":"The article concluded that:\n“…it is important for Muslims everywhere to know that there is no doubt in the\ngreat reward to be found on Judgment Day for those who spill the blood of these\nCoptic Crusaders wherever they may be found…”.98"},{"id":"a-hrc-31-crp-3-p0085","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"85","seq":86,"section":"3. Findings","text":"One of the cases referred to OHCHR was that of one of the most prominent Salafi\nleaders of Sirte, Sheikh Khalid Bin Rajb al-Firjani. In August 2015, he was shot by\nmembers of an armed group that has pledged allegiance to ISIL as he was leaving a mosque\nin the city. Another Salafi Sheikh standing close to him sustained injures in the same\nincident. Open sources noted that a week prior to the incident Sheikh al-Firjani denounced\nISIL. The killing triggered armed clashes between residents of the city's Number Three\nneighbourhood (most of them belonging to the al-Firjani tribe) and Salafi groups on the one\nside, and groups pledging allegiance to ISIL on the other. Unconfirmed estimates received\nby UNSMIL/OHCHR placed the number of individuals killed at between 4 and 38.99\nReports were also received that the bodies of four individuals killed were placed on poles\non public display.100"},{"id":"a-hrc-31-crp-3-p0086","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"86","seq":87,"section":"3. Findings","text":"In another case investigated by OHCHR, a man affiliated with the so called “Harawa\nRevolutionaries” was captured by a group pledging allegiance to ISIL at a checkpoint in\nHarawa. Witnesses reported the man was later executed and beheaded. His remains\n(together with those of another man killed at the checkpoint) were then taken around the\ncity for public display. Many people were forced to stop to look at the beheaded bodies.\nThe desecration of bodies post-mortem and placing them in public display was a feature of\nseveral cases reported to OHCHR. In one case, two Salafi fighters were executed following\nthe clashes in the Number Three neighbourhood, and their bodies placed on public display a\nthe main square of Al-Za’faran in Sirte. They were left there until noon the next day under\nthe guardianship of several armed men from groups pledging allegiance to ISIL. Similar\ncases have been reported in the media as having taken place in Derna.\n(e)   The south"},{"id":"a-hrc-31-crp-3-p0087","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"87","seq":88,"section":"3. Findings","text":"Unlawful killings have also taken place in the south of Libya. Several of the killings\nin Sabha took place in the context of individuals seeking to defend their homes from being\nraided, damaged or appropriated. A man from the Awlad Suleiman, tribe reported that his\nhouse had been raided by Tabu armed men in February 2014. He was sitting inside eating\nhis lunch with his family, when several Tabu armed men entered the house, and began\ndestroying and damaging his property. When his adult sons tried to intervene, both were\nshot dead in front of the family. His nephew was similarly shot dead when Tabu armed men\nraided his house. In another case, a man was seeking to resist armed men from the Tabu and\nAl-Qadhadhifa armed groups taking his house for the purpose of using it as a site to launch\nattacks on Awlad Suleiman groups. The man’s body was later found at his house having\nsustained bullet wounds. The house was damaged and in a state of disarray."},{"id":"a-hrc-31-crp-3-p0088","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"88","seq":89,"section":"3. Findings","text":"In another case reported to OHCHR, three men were driving their car south-west of\nSahba in January 2014. When they alighted from their car to investigate apparent\nmechanical problems, around 12 Tabu armed men appeared asking them about their\nidentity. After they disclosed their tribal affiliation as Awlad Suleiman, the Tabu armed\nmen opened fire at them, injuring two of the three men. The three men were taken to the\nCairo neighbourhood (Al-Tayouri) where they were surrounded by Tabu armed men and\nagain fired upon. A Tabu elder was permitted to drive one of the men to hospital for\ntreatment, and en route informed him that the other two had been killed. The whereabouts\nof the bodies of the two men killed remained unknown until they were found in an area\nassigned for garbage collection. OHCHR saw photographs of the two deceased men, one\nappearing to have had his throat slit, with signs of burns on his neck and right hand, and the\nother with stab wounds, also with signs of burns on his hand."},{"id":"a-hrc-31-crp-3-p0089","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"89","seq":90,"section":"3. Findings","text":"In another incident on 1 July 2014, a 53 year old man from Awlad Suleiman was\nreportedly shot dead by a number of armed men affiliated with Tabu and Al-Qadhadhifa\ntribes. The incident took place when the armed men stopped the victim while he was\ndriving his car in the Sabha agricultural project. His family were ordered to leave the car\nand take refuge in one of the neighbouring houses. They heard five gunshots as they were\nheading to the designated house. The man had been shot in his head and neck. OHCHR\nreceived two photographs showing the wounds sustained."},{"id":"a-hrc-31-crp-3-p0090","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"90","seq":91,"section":"3. Findings","text":"OHCHR also received information of individuals from the Tabu community having\nbeen deliberately shot at by Awlad Suleiman armed group members. In an incident in\nJanuary 2014, a 10 year old girl was shot dead with two bullets by armed men affiliated\nwith Awlad Suleiman armed groups. The victim was travelling in a car with her family, and\nthe shooting took place shortly after the car was passing Seif Square where more than 30\narmed men were stationed. There was no fighting going on in the location, but it is alleged\nthat the shots were fired directly at the car."},{"id":"a-hrc-31-crp-3-p0091","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"91","seq":92,"section":"3. Findings","text":"In relation to the fighting in Awbari, OHCHR received a list of 20 Tuareg men who\nwere said to have been killed by Tabu armed men based on their tribal identity in the period\nbetween 22 September 2014 and 14 July 2015. A human rights defender provided OHCHR\nwith a video which detailed an account of two Tuareg men who had been shot on Al-\nBareed Street. They were reportedly unarmed and were turning back after having been\nwarned of a Tabu sniper further ahead. The inability of OHCHR to access the south of\nLibya and many witnesses has, however, prevented it from being able to verify these cases.\n(f)      Groups in focus"},{"id":"a-hrc-31-crp-3-p0092","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"92","seq":93,"section":"3. Findings","text":"Human rights defenders, journalists, judges and prosecutors have also been the\ntargets of assassinations. Their cases are reported more fully in the corresponding sections\nof this present report, in particular Section H on human rights defenders and journalists, and\nSection G on administration of justice. There is a chilling similarity in the cases detailed\ntherein. In addition to the tragedy of their individual deaths, the consequence has been to\ndrastically curtail and restrict the activities of their peers."},{"id":"a-hrc-31-crp-3-p0093","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"93","seq":94,"section":"1. Introduction","text":"Numerous reports have drawn attention to the potential violations of international\nhuman rights and humanitarian law being committed in Libya in the form of prohibited\nattacks on civilians, civilian objects or other protected persons or objects. 101 As described in\nSection A, there have been a number of intentionally targeted killings in violation of\ninternational law, including against captured fighters and civilians. OHCHR investigations\nhave confirmed that many indiscriminate attacks have taken place, in highly populated\nresidential areas, often involving the use of weapons not designed for the precise targeting\nnecessary in such areas. Sufficient precautionary measures to protect the civilian population\nhave not been taken. OHCHR has documented a number of attacks against or impacting on\nprotected persons or objects such as medical personnel or facilities, and humanitarian\nworkers. The picture which emerges is of frequent disregard for the core principles of\ninternational human rights and humanitarian law, with dire consequences for the affected\ncommunities. This was not limited to one geographical region of Libya, but was observed\nin most of the conflict-affected areas."},{"id":"a-hrc-31-crp-3-p0094","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"94","seq":95,"section":"2. Legal framework","text":"It is a fundamental principle of international humanitarian law that civilians and\ncivilian objects are protected from attack. Parties may direct their attacks only against\nlegitimate military objectives, showing respect for the principles of distinction,\nproportionality, and precautions in attack. International humanitarian law thus prohibits:\n•   (intentionally targeted) attacks against civilians or civilian objects, or other protected\npersons/objects; attacks are only permissible against military targets;102\n•   indiscriminate attacks failing to distinguish between civilians or civilian objects, and\nlawful military targets;103\n•   disproportionate attacks expected to cause an incidental loss of life, injury to civilians,\nand/or damage to civilian objects, which would be excessive vis-à-vis the concrete and\ndirect military advantage anticipated.104"},{"id":"a-hrc-31-crp-3-p0095","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"95","seq":96,"section":"2. Legal framework","text":"The principle of distinction requires parties to a conflict to distinguish between\ncivilians and civilian objects on the one hand, and lawful military targets on the other. 105\nAttacks are only permissible against military targets.106 If civilians directly participate in\nhostilities, they lose their protection only for such time as they directly participate in\nhostilities.107 Attacks must also not treat as a single military objective a number of clearly\nseparated and distinct military objectives located in a city, town, village or other area\ncontaining a similar concentration of civilians or civilian objects.108 Such attacks are\nprohibited as indiscriminate."},{"id":"a-hrc-31-crp-3-p0096","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"96","seq":97,"section":"2. Legal framework","text":"Parties to the hostilities are required to take all feasible measures to avoid and in any\nevent to minimize incidental loss of civilian life, injury to civilians, and damage to civilian\nobjects.109 Parties have an obligation to take such precautionary measures in relation to both\nthe attacks they launch, as well as in relation to the protection of civilians from the effects\nof attacks within areas under their control. This includes an obligation to avoid locating\nmilitary objectives within or near densely populated areas to the extent feasible, as well as\ntaking all feasible measures to remove civilian persons and objects under the control of a\nparty to the conflict from the vicinity of military objectives.110"},{"id":"a-hrc-31-crp-3-p0097","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"97","seq":98,"section":"2. Legal framework","text":"International humanitarian law provides explicit protection for certain categories of\npersonnel, recognising the importance of their functions. This includes religious, medical,\nand humanitarian personnel.111 Such personnel are to be respected and protected. This\nmeans that they cannot be the object of attack, and their functions should not be impeded,\nother than for reasons of military necessity and taking into account the principles of\ndistinction, proportionality, and precautions in attack. Protection only ceases should the\npersonnel be involved outside their humanitarian function, in committing acts harmful to\nthe enemy.112 Intentionally directing attacks against the civilian population as such or\nagainst individual civilians not taking direct part in hostilities constitutes a war crime. 113 It\nis also a war crime to intentionally direct attacks against protected persons who use the\ndistinctive emblem of the Geneva Conventions (e.g. medical or religious personnel)114 or\nagainst personnel involved in a humanitarian assistance mission in accordance with the\nCharter of the United Nations.115"},{"id":"a-hrc-31-crp-3-p0098","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"98","seq":99,"section":"2. Legal framework","text":"International humanitarian law provides protection from attack for civilian objects\n(such as towns, residential areas, houses, schools, and civilian transportation). Specific\nreference is made to certain objects as being protected from attack, including medical units\nand medical transports (whether military or civilian);116 objects used for humanitarian relief\noperations;117 cultural property, including places of worship;118 and objects indispensable to\nthe survival of the civilian population (e.g. food, crops, water installations). 119 Medical\nunits have particularly heightened levels of protection. Prior to an attack against a medical\nunit which is being used to commit acts harmful to the enemy, a warning has to be issued\nsetting, whenever appropriate, a reasonable time-limit. An attack can only take place after\nsuch warning has remained unheeded.120"},{"id":"a-hrc-31-crp-3-p0099","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"99","seq":100,"section":"2. Legal framework","text":"Parties to the hostilities must allow and facilitate the rapid and unimpeded impartial\nhumanitarian relief for civilians in need.121 The intentional use of starvation of civilians as a\nmethod of warfare by depriving them of objects indispensable to their survival, including\nwilfully impeding relief supplies, may constitute a war crime in light of customary\ninternational humanitarian law applicable in non-international armed conflict.122"},{"id":"a-hrc-31-crp-3-p0100","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"100","seq":101,"section":"2. Legal framework","text":"International humanitarian law also provides limitations on the destruction and\nappropriation of property. It is thus a violation of international humanitarian law for a party\nto destroy or seize property of an adversary (unless imperatively demanded by the\nnecessities of war),123 or to engage in pillage (appropriating property for private use). 124\nEither type of conduct may constitute a war crime.125"},{"id":"a-hrc-31-crp-3-p0101","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"101","seq":102,"section":"3. Findings","text":"OHCHR investigated and obtained credible and consistent reports of indiscriminate\nattacks impacting on civilians and civilian areas during hostilities in 2014 and 2015. The\nnumber of such attacks has been particularly pronounced in the east, specifically in\nBenghazi, owing to the long term hostilities there. However, a general trend of such attacks\nis apparent across the cities that have experienced conflict. In some instances, whole\nneighbourhoods appear to have been targeted, without distinguishing between military and\ncivilian objectives.126 At other times, misfiring or the use of weaponry unsuited for precise\ntargeting appears to have been the dominant reasons for particular indiscriminate attacks.\nHeavy weaponry such as Grad rockets and rocket-propelled grenades, which are not\nappropriate for use in highly populated residential areas given that they cannot be targeted\nwith sufficient precision, have been employed in built-up residential areas, leading to\nextensive damage of civilian buildings, and death and injury to civilians.127 Without the\nability to conduct site visits and undertake detailed investigations, OHCHR has not been\nable to determine which parties were responsible for many specific attacks (given that the\ntype of weaponry being referred to, with the exception of air-strikes, is used by most\nparties). However, it has received reports of indiscriminate attacks in all conflict areas.\nThe east"},{"id":"a-hrc-31-crp-3-p0102","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"102","seq":103,"section":"3. Findings","text":"In one incident a residential building in the Al-Hada’eq neighbourhood in Benghazi\nwas hit by a rocket in the early evening of 26 April 2015. Two children in an apartment on\nan upper floor were killed. According to medical reports, both children sustained shrapnel\ninjuries in their head, chest, abdomen and limbs. Although there had been some clashes\nbetween Operation Dignity forces and groups affiliated with the Benghazi Revolutionaries\nShura Council in the Al-Laithi neighbourhood (several hundred metres away), it was\nreported that there were no armed clashes taking place on that day in the Al-Hada’eq\nneighbourhood, nor is OHCHR aware of any military objectives being pursued at that\nlocation. Those responsible for the attack remain unknown. The risk to the civilian\ncommunity from such episodes was becoming sufficiently widespread to prompt warnings\non social media, advising residents of the Al-Hada’eq, Al-Zawiya, and Abu Hdeyma\nneighbourhoods to stay away from the windows of their apartments and from areas adjacent\nto Al-Laithi neighbourhood so as to be able to protect themselves from stray bullets and\nindiscriminate shells.128"},{"id":"a-hrc-31-crp-3-p0103","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"103","seq":104,"section":"3. Findings","text":"In another incident, three children were killed and two others were injured when a\nshell struck a house in Bal’oon, Al-Fuweihatt neighbourhood (western district) in Benghazi\nin May 2015. The shell landed in the house garden where the children were playing in the\nearly evening. Again in this instance, OHCHR was informed that no fighting or other type\nof military activity was taking place in the neighbourhood on that day, nor is OHCHR\naware of any known military objectives at the location, though fighting was taking place in\nthe Al-Hawari neighbourhood located some two kilometres to the east."},{"id":"a-hrc-31-crp-3-p0104","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"104","seq":105,"section":"3. Findings","text":"The extent of indiscriminate attacks is illustrated through reference to another case\ndocumented by OHCHR. In this case, a woman sustained a bullet injury in her left thigh\nwhen she was on the rooftop of her building, putting laundry on a clothes-line. The artery\nof her left thigh was lacerated, and her left leg was subsequently amputated. The incident\ntook place in the eastern Salmani neighbourhood in May 2015. At that time, the\nneighbourhood was reported to be calm, with no fighting taking place.\nThe west"},{"id":"a-hrc-31-crp-3-p0105","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"105","seq":106,"section":"3. Findings","text":"A number of reports concerning indiscriminate attacks impacting civilians and\ncivilian objects during the fighting from July to August 2014 between Misratan and other\narmed groups affiliated with Libya Dawn and Zintani armed groups in Tripoli have been\npublished. In a joint UNSMIL/OHCHR report issued in September 2014, for instance,\nindividual cases mentioned included the killing of a middle-aged woman and a 25 year old\nman in the Ghut Al-Sha’al area, and the killing of a nine year old girl after a Grad rocket hit\nher house in the Al-Swani neighbourhood.129 OHCHR investigations have confirmed\nsimilar cases. In one case, a company building located one kilometre north of Tripoli\nInternational Airport sustained damage owing to stray shelling and bullets. One employee\nwas killed by a stray bullet entering the premises. Heavy fighting prevented an ambulance\nbeing able to access the premises, and it was two days before the company was able to\narrange for the transport of his body by a private car. Satellite imagery provided by\nUNOSAT confirms damage to this building."},{"id":"a-hrc-31-crp-3-p0106","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"106","seq":107,"section":"3. Findings","text":"During the fighting in Warshafana, attacks were carried out in residential areas,\nresulting in a significant number of civilian casualties. Estimates provided to OHCHR have\nvaried.130 Amnesty International reported that at least 12 civilians from Warshafana were\ntreated in Al-Rahma Hospital in the city of Mahdia in Tunisia in September 2014, for\nshrapnel injuries sustained as a result of the shelling of residential areas, or of stray bullets,\nbetween August and September 2014 by Libya Dawn.131 OHCHR investigations confirmed\nthat some indiscriminate attacks were carried out by Libya Dawn forces. In one case, for\ninstance, a rocket hit a car containing a family seeking to escape the shelling in the Al-\nHashan neighbourhood south of Warshafana. All four occupants were killed, along with\nthree other civilian bystanders. Witnesses indicated that there was no military activity\ntaking place in the area at the time, and that there were no opposition fighters present in the\nvicinity."},{"id":"a-hrc-31-crp-3-p0107","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"107","seq":108,"section":"3. Findings","text":"OHCHR received a number of reports related to attacks launched by armed groups\naffiliated with Zintan in Kikla and the surrounding Nafusa Mountains area. According to\none interlocutor, in the intense fighting in October and November 2014, some 217 persons\nwere killed (some 79 of whom were alleged to have been directly targeted on the basis of\ntheir origin) and 1,040 injured. The inability of the investigation team to visit Libya and a\nlack of information on the precise circumstances of the attacks means that it is not able to\ndraw a conclusion in relation to these attacks. However armed groups affiliated with Zintan\nhave also been reported to be using weaponry unsuited for precise targeting in highly\npopulated residential areas such as Grad rockets, tanks, anti-aircraft weaponry, and mortar\nshells.\nSuicide bomb attacks by members of groups pledging allegiance to ISIL"},{"id":"a-hrc-31-crp-3-p0108","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"108","seq":109,"section":"3. Findings","text":"OHCHR received information concerning suicide bomb attacks by members of\ngroups pledging allegiance to ISIL against security targets, of such a nature as to constitute\nindiscriminate attacks. On 22 May 2015, for instance, a car bomb attack took place close to\nthe Seventh of April School, a short distance from a security facility of the Hawara\nRevolutionaries. The attack injured two civilians. Another suicide car bomb attack took\nplace in Al-Qoba, on 20 February 2015, outside the national security directorate. The initial\nexplosion killed six security personnel.132 People of the surrounding neighbourhoods ran\ntowards the directorate to see what had happened. Less than two minutes later, while people\nwere heading in the direction of the first explosion, another explosion took place (the\nprecise cause is unknown). Responsibility was claimed by an armed group pledging\nallegiance to ISIL. 133 UNSMIL/OHCHR previously reported that at least 42 people were\nkilled.134 Among the civilian casualties were two young boys. One boy was killed and the\nother left with severe injuries requiring continuing hospitalisation."},{"id":"a-hrc-31-crp-3-p0109","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"109","seq":110,"section":"3. Findings","text":"Open source reports describe similar suicide bomb attacks elsewhere. On 9 August\n2015, a suicide bomb attack was reportedly carried out east of Derna by a member of a\ngroup pledging allegiance to ISIL, killing 10 people, and injuring 21 others. 135 OHCHR\nhowever has not been able to make contact with witnesses from Derna to confirm this\nreport.\nThe south"},{"id":"a-hrc-31-crp-3-p0110","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"110","seq":111,"section":"3. Findings","text":"The south has not been spared from indiscriminate attacks. In one case investigated\nby OHCHR in December 2014, two Tabu children were playing in the hall of their house,\nin Al-Daisa neighbourhood, east of Awbari, when a shell struck their house. This caused a\nfire in the hall, and both children sustained severe burns as a result. No hostilities were\nreported in the neighbourhood at that time, nor is OHCHR aware of any military objectives\nbeing pursued at that location. It would appear that this family was instead the victim of an\nindiscriminate attack.\n(b)         Attacks on protected persons and objects"},{"id":"a-hrc-31-crp-3-p0111","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"111","seq":112,"section":"3. Findings","text":"The conflict has also witnessed attacks against or otherwise impacting persons and\nobjects given special protection under international humanitarian law, in particular\nambulances, health facilities and workers, and humanitarian workers.\nMedical units and transports"},{"id":"a-hrc-31-crp-3-p0112","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"112","seq":113,"section":"3. Findings","text":"OHCHR received reports of several attacks against ambulances marked with the Red\nCrescent symbol. The cases involved ambulances operated by the Department for\nEmergencies and occurred on the outskirts of Al-Kufra, allegedly by an armed group called\nBrigade 448. The first took place in July 2015 and reportedly involved the attacking of an\nambulance, the looting of its contents, and the beating and harassment of the medical staff\nand patients inside the ambulance. The second attack took place in August 2015. It\ninvolved a similar attack, but also involved the abduction of the driver and medical\npersonnel. The patient and her husband were abandoned on the side of the road in a critical\nmedical condition. The driver and the medical staff were released at the end of November\n2015. OHCHR has not been able to verify with the ambulance providers the details of this\nattack owing to lack of access."},{"id":"a-hrc-31-crp-3-p0113","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"113","seq":114,"section":"3. Findings","text":"On 25 July 2014, the Tripoli Medical Center was attacked by an armed group\naffiliated with Libya Dawn (who a witness described as the “Al-Tajeen Brigade”) with at\nleast one doctor being abducted in order to treat injured members of the Brigade. According\nto information received from medical personnel, on 14 September 2014, Warshafana armed\ngroups attacked Al-Zawiya hospital west of Tripoli, injuring a number of civilians,\nincluding a visitor and a nurse. The attack occurred at approximately 5 p.m., and was said\nto have involved a rocket, impacting in particular the first floor emergency department and\nreception areas, with further minor damage inflicted on the Intensive Care Unit on the\nsecond floor. A second rocket hit the hospital morgue around 5.30 p.m. It is reported that\nthe attack was in retaliation for the hospital having treated approximately 12 wounded\nmilitary personnel earlier in the day."},{"id":"a-hrc-31-crp-3-p0114","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"114","seq":115,"section":"3. Findings","text":"It was reported that in October 2014, Al-Zahraa, a town south-west of Janzour,\nshelling resulted in the partial destruction of Al-Zahraa City hospital. UNOSAT satellite\nimagery confirmed damage to an annex to the hospital. However, information received was\ninsufficient to establish whether the hospital was deliberately targeted."},{"id":"a-hrc-31-crp-3-p0115","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"115","seq":116,"section":"3. Findings","text":"Similarly in the east, the protected status of hospitals has not always been respected\nby parties to the conflict. According to information received by UNSMIL/OHCHR, in\nBenghazi, three medical personnel and an ambulance driver were killed on 6 May 2015 as a\nresult of armed clashes between Operation Dignity and Benghazi Revolutionaries Shura\nCouncil. Benghazi Medical Centre was shelled on several occasions between April and July\n2015. One staff member was seriously injured in the context of the shelling, and property\nwas damaged. On a different occasion on 5 July 2015, armed men loyal to Operation\nDignity attacked the Benghazi Medical Centre, threatening the hospital staff and destroying\nfurniture.136 On 8 July 2015, the ground floor of Al-Jalaa hospital in Benghazi was\ndestroyed as a result of shelling leading to the death of one civilian and the injury of three\nothers.137\nHumanitarian workers"},{"id":"a-hrc-31-crp-3-p0116","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"116","seq":117,"section":"3. Findings","text":"On 5 June 2015, three humanitarian workers from the Sheikh al-Tahir al-Zawi\nOrganization were abducted and held hostage by armed men from the Al-Megharba tribe,\nin the Shawaref area. The convoy which consisted of seven trucks delivering non-food\nitems to Awbari was stopped by armed men who abducted the three workers, and released\ntheir other colleagues. The three were apparently abducted for the purpose of an exchange\nwith a man captured by the First Brigade in Al-Zawiya. The three workers were released\nafter negotiations with tribal leaders. The man captured by the First Brigade was released in\nexchange."},{"id":"a-hrc-31-crp-3-p0117","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"117","seq":118,"section":"3. Findings","text":"There are other reported cases of humanitarian workers being attacked, including a\ndelegate of the International Committee of the Red Cross who was killed in Sirte on 4 June\n2014 by unidentified armed men.138\n(c)     Destruction, appropriation or looting of private property"},{"id":"a-hrc-31-crp-3-p0118","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"118","seq":119,"section":"3. Findings","text":"OHCHR received a number of reports of attacks on private property, in particular\nthe burning of houses and property and looting. In many cases the attacks were seen as\ntargeted against particular individuals on the basis of their place of origin and/or their\nperceived political affiliation. In one case in October 2014, a family living in Benghazi\nreported that seven trucks and five cars belonging to them were confiscated by the Awliaa\nal-Damm armed group which is affiliated with Operation Dignity. On the next day, the\nsame family had their house raided, with documents taken concerning their ownership of a\nplot of land and house in Qanfooda (17 kilometres west of Benghazi) before the second\nfloor of their house was destroyed by arson. The family believes these attacks, together\nwith others committed against individuals in their family, were based on their Misratan\norigin."},{"id":"a-hrc-31-crp-3-p0119","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"119","seq":120,"section":"3. Findings","text":"The policy of Awliaa al-Damm was described by victims as uprooting families of\nwestern Libyan origin from Benghazi, with such families viewed as being pro-Libya Dawn\nand pro-political Islam, or affiliated either with Benghazi Revolutionaries Shura Council\nincluding Ansar al-Sharia or with ISIL. In this respect, OHCHR was referred to an audio\nrecording on social media, said to be of a senior Awliaa al-Damm commander inciting\nyouth to set fire to properties of families of western Libyan origin, because they are:\n“non-Libyans, who have no loyalty to Libya. They are the main reason of Libya’s\ndestruction. They are the ones who brought Qataris and Turks to Libya. Look at\nMisratans who have been living in Libya for years, but their loyalty is still to\nMisrata, to the Turks, to the dogs over there…”.139"},{"id":"a-hrc-31-crp-3-p0120","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"120","seq":121,"section":"3. Findings","text":"In the same vein, OHCHR was referred to a video clip also available on social\nmedia, said to be a recording of a commander of Awliaa al-Damm, threatening Misratans\n(referred to as Turks and Qataris) with punitive measures, including “throwing them to sea\nand burning them…”.140"},{"id":"a-hrc-31-crp-3-p0121","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"121","seq":122,"section":"3. Findings","text":"Another family originally from Misrata but residing in Benghazi reported that they\nhad had several stores and residential buildings that they owned deliberately destroyed by\nAwliaa al-Damm in early 2015. The family believes that the destruction of its properties by\nAwliaa al-Damm was based on their western Libyan origin, as well as the desire of Awliaa\nal-Damm to take revenge on two relatives of the family who were allegedly involved in\nattacking protestors in their capacity as Libya Shield operatives during a demonstration on\n8 June 2013. The family requested intervention by Operation Dignity forces to stop the\nattack without success.141"},{"id":"a-hrc-31-crp-3-p0122","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"122","seq":123,"section":"3. Findings","text":"On 5 June 2014, Operation Dignity air forces carried out an air strike which targeted\nnine warehouses located close to Al-Saidaa Aishaa Mosque, in the Al-Hawari area, south-\nwest of Benghazi. The warehouses were destroyed, one civilian was killed, and three others\ninjured. OHCHR was informed that the air force justified their action on the basis that the\nwarehouses were being used by Ansar al-Sharia to store weapons. Those connected with\nthe warehouse deny this allegation, and have stated that the warehouses contained\ncommercial goods and products, including appliances and motors. Instead, they allege that\nthe attack was motivated by the desire of Operation Dignity to uproot all businessmen with\nMisratan origin from Benghazi, under the pretext of fighting Ansar al-Sharia. Although\nOHCHR has not been in a position to verify the legitimacy of the military objective, the\nway in which the attack was carried out raises serious questions about the extent to which\nthe air force took all feasible precautions to protect civilians and civilian objects. The first\ntwo air strikes are understood to have been conducted at 3.45 p.m. and 4.45 p.m.\nrespectively. No casualties were recorded as a result of these air strikes. Subsequently,\nmany civilians went to the warehouse to rescue the remaining goods. At around 8.30 p.m., a\nfurther attack was carried out, reportedly involving some six rockets. As result, one civilian\nwas killed and two other persons were injured requiring several months of treatment."},{"id":"a-hrc-31-crp-3-p0123","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"123","seq":124,"section":"3. Findings","text":"A similar targeting of private properties on the basis of owners’ origins or perceived\npolitical affiliations was reported to have taken place during hostilities in Warshafana.\nWitnesses reported that some 70 to 80 houses were significantly damaged in Al-Sayad and\nAl-Maya neighbourhoods alone. Other houses had been partially damaged or looted and\nlivestock looted. One witness referred to water-wells having been destroyed (including by\nthrowing pumps and destroyed pipes into the wells). Another witness reported having\nreturned to his house in Al-Maya in late September 2014 to discover his house burned, his\ncars destroyed and jewellery stolen. Tens of other houses and several farms and other\nbusinesses in the neighbourhood were either destroyed, burned, or looted. A third witness\nreported that his two-storey house in the Al-Hashan area was set on fire by armed groups\naffiliated with Libya Dawn in late August 2014, with his farm, a tractor, and some\nagricultural materials also being burned. A fourth witness reported that his house and four\nhouses belonging to his sons and their families in the Al-Zahraa neighbourhood were\nburned by a group affiliated with Libya Dawn in late August 2014. In mid-October 2014,\nUNSMIL/OHCHR human rights officers observed houses and shops in the Al-Maya\nneighbourhood damaged or destroyed, with fires still smouldering. 142 The lack of access to\nWarshafana has made it difficult for the OHCHR investigation team to verify these\nallegations. However, strong similarities are noted between accounts and the verification of\nthe extent of destruction at least in certain areas by UNSMIL/OHCHR.\nGroups pledging allegiance to ISIL"},{"id":"a-hrc-31-crp-3-p0124","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"124","seq":125,"section":"3. Findings","text":"Appropriation of property by groups pledging allegiance to ISIL was also reported\nto OHCHR. One victim, for instance, described how his house (located in the Al-Jaiza\nneighbourhood in Sirte), his brother’s house located in the city's “Number Three\nneighbourhood”, and his mother’s apartment located in neighbourhood “656”, were\nappropriated by these groups. He added that some 250 livestock, ten camels and two cars\nbelonging to his cousin were also stolen. The individuals appear to have been targeted for\ntheir alleged participation in clashes against the groups."},{"id":"a-hrc-31-crp-3-p0125","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"125","seq":126,"section":"1. Arbitrary detention","text":"The Human Rights Council expressed grave concern at the rise in number of\nconflict-related detainees, including children, in its resolution 28/30.143 The Council called\nupon the Government to urgently establish full and effective control over all detention\ncentres, so that it could ensure that detainees are treated in accordance with international\nobligations, including fair trial guarantees and humane treatment.144 The precise number of\npersons in detention is unknown. However, it is estimated that more than 9,000 persons are\ncurrently detained in facilities operated by the Ministry of Justice and the Department for\nCombatting Illegal Migration of the Ministry of the Interior alone. 145 This figure does not\ninclude the significant number of persons held elsewhere such as in facilities operated by\nthe Ministry of the Interior, those under the control of the Ministry of Defence, and/or those\noperated by armed groups, and private actors including smugglers. OHCHR has\ninterviewed a range of persons who have been detained in Libya in both formal and\ninformal centres. Its investigation has led it to conclude that there has been widespread\narbitrary detention of persons by both State officials and armed group members with\ndetained persons having little (if any) recourse to judicial review or other rights of due\nprocess to provide redress.\n(b)         Legal framework"},{"id":"a-hrc-31-crp-3-p0126","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"126","seq":127,"section":"1. Arbitrary detention","text":"Under international human rights law, everyone has the right to be free from\narbitrary arrest and detention. 146 A detention is arbitrary if it is not in accordance with\nnational law (e.g. where it is not based on grounds established in a pre-existing law, or\nwhere essential procedural rules have not been followed). Even where sanctioned under\ndomestic law, it will be considered arbitrary if it is otherwise inappropriate, unjust,\nunreasonable, or unnecessary in the circumstances.147 Persons arrested have the right to be\ninformed at the time of arrest of the reasons for the arrest and to be informed promptly of\nany charges against them.148 It is also not to be the general rule that persons awaiting trial\nbe detained in custody.149 Where persons are arrested or detained on a criminal charge, they\nneed to be brought before a judicial authority, and are entitled to trial within a reasonable\nperiod or to release.150 All persons have the right to take proceedings before a court to seek\nreview of the lawfulness of their detention and to be released should the detention be\nunlawful.151"},{"id":"a-hrc-31-crp-3-p0127","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"127","seq":128,"section":"1. Arbitrary detention","text":"States are obliged to take appropriate measures to protect the right to liberty against\ndeprivation by third parties including protecting against abduction or detention by\nindividual criminals or irregular groups (such as armed groups). 152 Where private\nindividuals or entities are empowered or authorised by a State to exercise powers of arrest\nor detention, the State remains responsible for ensuring adherence to all relevant human\nrights standards. The State must therefore rigorously limit the powers given and provide\nstrict and effective control to ensure the powers are not misused and do not lead to arbitrary\nor unlawful arrest or detention. 153"},{"id":"a-hrc-31-crp-3-p0128","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"128","seq":129,"section":"1. Arbitrary detention","text":"Although international treaty law applicable to non-international armed conflict does\nnot deal explicitly with the topic, the requirement that civilians and other protected persons\nbe treated humanely is understood to require protection from arbitrary deprivation of\nliberty.154 Under customary international law, any security related detention must be\njustified by the existence of a present, direct and imperative threat by the individual\nconcerned, and is subject to strict procedural requirements including that the person may\neffectively challenge the lawfulness of the detention, that the detention does not last any\nlonger than absolutely necessary, and that there be initial and periodic reviews by an\nindependent body possessing the same attributes of independence and impartiality as the\njudiciary.155"},{"id":"a-hrc-31-crp-3-p0129","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"129","seq":130,"section":"1. Arbitrary detention","text":"Imprisonment or other severe deprivation of liberty in violation of fundamental rules\nof international law may constitute a crime against humanity if committed as part of a\ncircumstances of a given detention”. See Working Group on Arbitrary Detention, Deliberation No. 7,\npara. 54(b).\nwidespread or systematic attack against any civilian population, with knowledge of the\nattack.156"},{"id":"a-hrc-31-crp-3-p0130","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"130","seq":131,"section":"1. Arbitrary detention","text":"In the present report the term “detention” and its variants (“detainee”, “detention\nfacilities”) is intended to reflect deprivation of liberty by both State and armed groups in\nview of the complex factual situation in Libya, in particular given that armed groups remain\nin control of many facilities, and that many armed groups were theoretically brought under\nthe purview of the Ministries of the Interior, Defence or Justice during integration processes\ncarried out after 2011. The term “conflict-related detainee” is used as a reference to persons\ndetained as a result of the conflicts in Libya in 2011 or 2014 and 2015.\n(c)     Facilities of detention"},{"id":"a-hrc-31-crp-3-p0131","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"131","seq":132,"section":"1. Arbitrary detention","text":"There are four general categories of detention facilities operating in Libya. The first\nthree categories are all ostensibly operated by separate State ministries, namely the Ministry\nof Justice, the Ministry of Defence and the Ministry of the Interior, though armed groups\nremain involved in many of the facilities. The fourth category consists of informal facilities\nin which persons are deprived of liberty, and held in facilities controlled by a range of\nentities, including armed groups, local community or tribal councils, criminals, and\nsmugglers.157"},{"id":"a-hrc-31-crp-3-p0132","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"132","seq":133,"section":"1. Arbitrary detention","text":"Reference has been made earlier in this present report to the manner in which many\narmed groups were brought under the Ministry of Justice, Ministry of Defence, or the\nMinistry of the Interior. In 2013, UNSMIL/OHCHR noted that the formal facilities that\narmed groups controlled were categorized as officially under State authority, while the level\nof State control was often “nominal, with brigades frequently retaining their membership\nand command structures”.158 In some cases, for example, management of facilities was\nobserved to be “shared” between Judicial Police and armed groups. In other cases, the\narmed groups remained fully in control.159 OHCHR has also noted some fluidity in the\nprecise arrangements in relation to specific detention facilities. Some facilities have been\nregarded as under the control of a ministry at one point, then have become subject to\ncontrol by an armed group, or vice-versa."},{"id":"a-hrc-31-crp-3-p0133","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"133","seq":134,"section":"1. Arbitrary detention","text":"The first category of facilities comprises those operated by the Ministry of Justice.\nThey are the most well-known, partly because they are operated by the Judicial Police who\nare part of the justice apparatus and responsible for providing security for court premises.\nThis category includes formal prisons and correctional institutions, some of which have\nidentifiable mandates for specific types of prisoners, such as women."},{"id":"a-hrc-31-crp-3-p0134","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"134","seq":135,"section":"1. Arbitrary detention","text":"The second category of facilities comprises those operated by the Ministry of\nDefence. They are generally operated by the military police, purportedly for detention of\nmilitary and security personnel. OHCHR, however, has documented cases involving\ncivilians held in some of these facilities (including deaths in custody)."},{"id":"a-hrc-31-crp-3-p0135","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"135","seq":136,"section":"1. Arbitrary detention","text":"The third category of facilities comprises those operated by the Ministry of the\nInterior. Within this category are facilities operated by the Department for Combatting\nIllegal Migrants. It is believed there are approximately 19 facilities, all of them allocated to\nthe detention of migrants. Further details of their operation are provided in Section I on\nmigrants. Also within this category are other facilities connected with the Ministry of the\nInterior (e.g. connected with Criminal Investigation Departments, police directorates and\nstations)."},{"id":"a-hrc-31-crp-3-p0136","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"136","seq":137,"section":"1. Arbitrary detention","text":"Examples of facilities, in which armed groups remain in control of facilities which\nare ostensibly State facilities, are the two Abu Salim facilities in Tripoli, detention facilities\nat Mitiga military base in Tripoli, the Al-Birsis detention facility,160 and other detention\nfacilities in Al-Rajma, Abu-Hdeyma, and Tokra."},{"id":"a-hrc-31-crp-3-p0137","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"137","seq":138,"section":"1. Arbitrary detention","text":"The fourth category of facilities comprises numerous and less well-known makeshift\nfacilities scattered throughout the country where persons are deprived of liberty. The\nfacilities are improvised, and operated by groups as diverse as armed groups, local\ncommunity or tribal councils, smugglers, criminals, and vigilantes. The precise number of\nthese facilities is unknown. Figures provided to OHCHR range from 17 to a hundred of\nsuch informal facilities, including make-shift sites, schools, civilian buildings and farms.\nThe existence of these facilities has been acknowledged by the authorities. The Deputy\nMinister of Justice responsible for human rights was quoted in June 2015 as stating that\neven in territories under the control of the Government, there were “illegitimate facilities”,\nadding that the matter had been referred to the Chief Public Prosecutor for investigation. 161\n(d)         Findings"},{"id":"a-hrc-31-crp-3-p0138","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"138","seq":139,"section":"1. Arbitrary detention","text":"OHCHR staff interviewed many former detainees who were arbitrarily detained by\nState officials or armed group members and denied their basic legal rights. Many were\ndetained or abducted without lawful authority, or deprived of their liberty en masse by\nparties to the conflict. Frequently, persons are moved between various facilities with\nvarying levels of oversight by authorities. Some were accused of committing crimes, such\nas being involved in hostile acts. Many reported that they were never informed of the\nreasons for their detention. Most spent a significant period of time in custody without being\nformally charged with any criminal offence. Virtually none had access to rights of due\nprocess, including legal review of their detention or any ability to challenge their detention,\nand were denied other rights, such as to contact their families. In some cases, the rationale\nfor detaining persons was linked to a potential ransom or a prisoner exchange demand. As\nis further elaborated upon in Section D, torture and other forms of cruel, inhuman or\ndegrading treatment or punishment have become routine in many detention facilities, with\nno real potential redress."},{"id":"a-hrc-31-crp-3-p0139","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"139","seq":140,"section":"1. Arbitrary detention","text":"One case documented by OHCHR concerned a 54 year old man from Derna, who\nwas detained in May 2014 at a military checkpoint located at the southern entrance of Al-\nMarj. Armed forces aligned with Operation Dignity apprehended him, along with his\nfriend, as soon they identified themselves as being from Derna. He stated:\n“They took us to a military base in Al-Marj, and then they accused us of being\nmembers of ISIL just because we are from Derna. In the morning they handcuffed\nand blindfolded both of us and put us in the trunk of a military vehicle allocated to\ntransfer the prisoners. They parked the car in the military yard under the sun and\nleft us inside the car for six hours. We were burning inside the metal trunk and were\nsuffocating while suffering heat stroke. The soldiers were cursing us and insulting us\nall the time while we were crying and screaming inside the car as we felt that we\nwere going to die there. In the afternoon, they took us to the military police prison in\nAl-Abyar where we spent one day, before they transferred us again to Gernada\nprison. They put us with another detainee who was brutally tortured. We remained\nin detention for 17 days without being brought before a judge or prosecutor. After\n10 days in detention, they blindfolded both of us and interrogated us separately and\nthen ordered us to sign the interrogation record while we were still blindfolded.\nThen they let us go to our homes a few days later”."},{"id":"a-hrc-31-crp-3-p0140","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"140","seq":141,"section":"1. Arbitrary detention","text":"The case of a 45 year old man from Benghazi interviewed by OHCHR is\nemblematic of the dire situation of many detained persons in Libya:\n“In the night of November 2014, four masked armed men in military uniform broke\ninto my home in Benghazi. They ordered me to go with them. I asked them to identify\nthemselves and to let me know why they wanted to arrest me. They informed me that\nthey are from the “Al-Sa’eqa [army] Interrogation Unit” and I will be informed\nlater of the reason for my arrest. I asked them if they had an arrest warrant, but they\nforced me to go with them. They handcuffed and blindfolded me and then drove me\nto an unknown place. As soon as I stepped out from their car, I was severely\ntortured and insulted by the guards while I was still blindfolded. Nobody informed\nme why I was arrested and why they were beating me like that. They then put me in\na cell with more than 40 detainees. I asked them where we are, but all of them did\nnot know. Nobody interrogated any of us on the next day, but on the day after, [the\narmed group commander] came to the cell with another 15 guards and started\nbeating all of us randomly. This lasted for half an hour and then they left. We did\nnot know why they tortured us like this and most of us were left bleeding on the\nground without receiving any medical treatment”."},{"id":"a-hrc-31-crp-3-p0141","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"141","seq":142,"section":"1. Arbitrary detention","text":"Another detainee from Benghazi was apprehended in October 2014 by the Al-Sai’qa\nBrigades and was moved amongst several military interrogation units in and around\nBenghazi. He was accused of being involved with Ansar al-Sharia. He spent more than two\nmonths in detention and was denied any procedural rights or access to counsel. He was\nnever brought to court and had no opportunity to challenge the legality of his detention."},{"id":"a-hrc-31-crp-3-p0142","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"142","seq":143,"section":"1. Arbitrary detention","text":"Given that courts in many parts of Libya have stopped functioning, possibilities to\nhave the legality of detention adjudicated by a court are limited. Even in cases where\ndetainees have had access to some level of judicial review, orders issued by the courts for\nrelease have not necessarily been effective. In one case, for instance, OHCHR staff\ninterviewed a man who was detained in the west of Libya. After judicial review\nproceedings were instituted by his lawyer, a judge ordered his release in January 2014. On\nhis way home, however, the man was re-apprehended by the Tripoli Revolutionaries\nBrigade, which is affiliated with Libya Dawn, who returned him to the same facility."},{"id":"a-hrc-31-crp-3-p0143","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"143","seq":144,"section":"1. Arbitrary detention","text":"The general lawlessness has provided an opportunity for different armed groups\nincluding criminal gangs to abduct and take into custody civilians, in order to seek ransom,\nor exchange them for those held by rival groups. Many members of armed groups, foreign\nworkers or high-profile civilians have been targeted for these purposes.162"},{"id":"a-hrc-31-crp-3-p0144","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"144","seq":145,"section":"1. Arbitrary detention","text":"One man from Warshafana, for instance, reported to OHCHR that he was abducted\nin November 2014 by an armed group and taken to a facility in Sidi Bilal. He informed\nOHCHR:\n“We were not allowed to contact our family, or to receive legal aid. At some point,\nthey negotiated my release with me, asking me to pay 200,000 Libyan Dinars if I\nwished to get released. I responded saying that I can’t afford this sum. Negotiations\nlasted until December 2014, when I agreed to pay 70,000 [Libyan Dinars] in\nexchange for my release. On that day, they allowed me to call my family to ask them\nto bring the sum to Sidi Bilal prison. Next day… members of my family came to the\nprison where they paid the sum. Soon after they paid the sum, I was released”."},{"id":"a-hrc-31-crp-3-p0145","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"145","seq":146,"section":"1. Arbitrary detention","text":"Another case related to the abduction of a man from Warshafana in April 2015 by an\narmed group affiliated with Libya Dawn. He was handed to another group and later\nreleased in exchange for the release of a Libya Dawn commander who had been captured\nby a Warshafana group."},{"id":"a-hrc-31-crp-3-p0146","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"146","seq":147,"section":"1. Arbitrary detention","text":"Another victim interviewed by OHCHR staff recalled his abduction in September\n2014 in Tripoli. He explained he had been abducted because of his Zintan origins. He\nreported:\n“Soon after the abduction, they forced me to call my family informing them that they\nshould release … [a] commander of Libya Revolutionaries Room, and I would then\nbe released. They detained me in the Fourth Force Battalion base in Gheryan for\nmore than two months waiting for the swap. I was severely tortured on different\noccasions without being interrogated or accused of any crime. On one occasion, the\nguards hit my head into a wall, so my nose was broken. Eventually, I was released\non 24 January 2015 with another 10 detainees from Zintan in a swap for 46 people\nfrom Gheryan including [the commander]”."},{"id":"a-hrc-31-crp-3-p0147","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"147","seq":148,"section":"1. Arbitrary detention","text":"Reports received by OHCHR indicated that during the armed clashes in the south,\nmany civilians were abducted, having been targeted on the basis of their tribal origin. In\nsome cases the whereabouts of persons remains unknown, raising the issue of enforced\ndisappearances."},{"id":"a-hrc-31-crp-3-p0148","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"148","seq":149,"section":"2. Enforced disappearances","text":"The act of enforced disappearance is recognized as an affront to human dignity,\nplacing persons affected outside the protection of the law and inflicting severe suffering on\npersons disappeared and their families.163 Enforced disappearance is regarded as a\ncontinuing violation which is not brought to an end until the person is accounted for.\nOHCHR documented many cases of enforced disappearance attributed to the State as well\nas to armed groups in Libya. In some cases, persons were eventually released. In other\ncases, families have spent days, months or even years looking for their relatives in different\nlocations including hospitals, morgues, and official and unofficial facilities but to no avail.\n(b)         Legal framework"},{"id":"a-hrc-31-crp-3-p0149","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"149","seq":150,"section":"2. Enforced disappearances","text":"An enforced disappearance occurs where a person is detained or otherwise deprived\nof liberty and those responsible refuse to acknowledge the deprivation of liberty or conceal\nthe person’s fate or whereabouts, placing the person outside the protection of the law. 164\nUnder international human rights law, enforced disappearances occur where the deprivation\nof liberty is undertaken by a State agent or a person or group acting with the authorization,\nsupport or acquiescence of the State.165 Under international humanitarian law, enforced\ndisappearance is prohibited and might be carried out by any party to a conflict.166 Under\ninternational criminal law, individuals can be held responsible for an enforced\ndisappearance undertaken by either the State or a political organization or persons acting\nwith the support or acquiescence of such bodies, as part of a crime against humanity.167"},{"id":"a-hrc-31-crp-3-p0150","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"150","seq":151,"section":"2. Enforced disappearances","text":"Enforced disappearance represents a serious breach of both international human\nrights law and international humanitarian law. While Libya is not a party to the\nInternational Convention for the Protection of all Persons from Enforced Disappearance, it\nis a party to ICCPR, many provisions of which are infringed by enforced disappearance,\nincluding the rights to recognition as a person before the law, to security of the person and\nfreedom from arbitrary detention (and associated procedural rights), and to respect for\nprivacy, family, home and correspondence, and it further potentially violates the\nprohibitions on torture and other cruel, inhuman or degrading treatment or punishment, and\nthe right to life. 168 The family of a victim of enforced disappearance may also suffer\nviolations of the prohibition of torture and other ill-treatment by virtue of the anguish and\nstress caused to them by the disappearance and the uncertainty concerning the fate and\nwhereabouts of the victim.169"},{"id":"a-hrc-31-crp-3-p0151","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"151","seq":152,"section":"2. Enforced disappearances","text":"Enforced disappearances also violate or threaten to violate a number of international\nhumanitarian law provisions including the humane treatment of all persons not taking part\nin hostilities,170 the prohibition on arbitrary deprivation of liberty,171 and may lead to\ntorture, cruel or inhuman treatment, and murder.172 It is also inconsistent with parties’\nobligation to register persons they deprive of liberty, to respect family lives, 173 to take all\nfeasible measures to account for persons reported missing as a result of armed conflict, and\nto provide family members with any information they have on their fate.174 Enforced\ndisappearance is recognized as an act which, if committed as part of a widespread or\nsystematic attack against any civilian population, with knowledge of the attack, may\nconstitute a crime against humanity.175"},{"id":"a-hrc-31-crp-3-p0152","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"152","seq":153,"section":"2. Enforced disappearances","text":"Under international human rights law, enforced disappearances occur where the act\nof detention is undertaken by a State agent or a person or group acting with the State’s\nauthorization, support or acquiescence.176 Breaches of relevant international humanitarian\nlaw involved in enforced disappearances might be committed by any party to a conflict. 177\nUnder international criminal law, individuals can be held responsible for an enforced\ndisappearance undertaken by either the State or a political organization or persons acting\nwith the support or acquiescence of such bodies, as part of a crime against humanity.\n(c)     Findings"},{"id":"a-hrc-31-crp-3-p0153","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"153","seq":154,"section":"2. Enforced disappearances","text":"OHCHR investigated enforced disappearances attributed to State forces and armed\ngroups178 after the launch of Operation Dignity and Libya Dawn. Civilians have been taken\nfrom the streets for their political or tribal affiliation before being deprived of their liberty\nand held secretly, usually in deplorable conditions and subject to torture or other cruel,\ninhuman or degrading treatment or punishment."},{"id":"a-hrc-31-crp-3-p0154","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"154","seq":155,"section":"2. Enforced disappearances","text":"Besides the cases described below, disappearances have been carried out in the west\nby the Deterrence and Assistance Force and Tripoli Revolutionaries Brigade armed groups\nwhich are affiliated with Libya Dawn, and in the east by Awliaa al-Damm and Al-Sahawat\narmed groups which are affiliated with Operation Dignity. Armed groups have continued to\ncontrol secret or unrecognized detention facilities outside the remit of any judicial\nauthority. Those detained by armed groups across the country were frequently held\nincommunicado (without being able to communicate with anyone other than his or her\ncaptors and co-detainees) for long periods."},{"id":"a-hrc-31-crp-3-p0155","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"155","seq":156,"section":"2. Enforced disappearances","text":"Families of detained persons reported to OHCHR that they struggled for long\nperiods to obtain information on their relatives’ fate or whereabouts. One man was\napprehended in February 2015 by the Tripoli-based Martyr Hamza Brigade, affiliated with\nLibya Dawn. He reported to OHCHR that:\n“During the first four days of my detention, I was completely incommunicado as I\nwas not able to communicate with any person, call my family or at least know my\nwhereabouts… I was receiving one meal per day, but in one occasion, I was left\nwithout food for two days. I was also not permitted to use the bathroom or to any\noutdoor time. I was hearing from time to time some people crying and shouting\nbecause of harsh torture they were suffering…Just on the seventh day, my family\nmanaged to find out my whereabouts through an unofficial way”."},{"id":"a-hrc-31-crp-3-p0156","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"156","seq":157,"section":"2. Enforced disappearances","text":"On 20 October 2014, Abd al-Nasser al-Jeroushi a prosecutor in South Benghazi\nCourt was abducted by an armed group at a checkpoint close to the Arab Medical\nUniversity in Belaon neighbourhood in Benghazi. This checkpoint was under the control of\nthe Al-Sai’qa Brigades of the Libyan National Army. In April 2015, the Ministry of Justice\ninformed UNSMIL that he was being held in Al-Marj at an unofficial detention facility. 179\nWhen OHCHR raised the case with the Attorney-General’s Office, it was indicated that\ndespite inquires made with Operation Dignity officials no confirmation of his whereabouts\nhad been received."},{"id":"a-hrc-31-crp-3-p0157","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"157","seq":158,"section":"2. Enforced disappearances","text":"Other cases reported to OHCHR related to the disappearance of persons in preceding\nyears, but for whom either the search continues for the family, or information as to the\nwhereabouts of the relative was obtained during the investigation reporting period. In one\nsuch case, a man was apprehended in 2012, taken to Abu Salim prison, and then reportedly\ntransferred to the Misrata-based Al-Saket prison. Both facilities were under the control of\narmed groups affiliated with Libya Dawn. When inquiries were made at Al-Saket prison, all\nknowledge of the man was disavowed. No information was forthcoming until a telephone\ncall was received, indicating where the man was detained, and that he had been severely\ntortured and held in solitary confinement on several occasions. He was permitted to receive\nonly one visit from his family in 2015. He died in detention a short time later."},{"id":"a-hrc-31-crp-3-p0158","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"158","seq":159,"section":"2. Enforced disappearances","text":"OHCHR also received reports of abductions by groups pledging allegiance to ISIL\nin Sirte, but has not been in a position to further investigate these cases because of the lack\nof safe access to relevant persons in Sirte."},{"id":"a-hrc-31-crp-3-p0159","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"159","seq":160,"section":"1. Introduction","text":"Serious concerns have been raised with regard to the treatment of persons in\ndetention in Libya, including in relation to allegations of torture and other forms of cruel,\ninhuman or degrading treatment or punishment. In its resolution 28/30, the Human Rights\nCouncil expressed concern at reports of “torture and sexual and gender-based violence in\ndetention centres”, calling upon the Government to establish full and effective control over\nall detention centres so that it could ensure that detainees, including foreign detainees, are\ntreated in accordance with international obligations, including humane treatment.180\nUNSMIL/OHCHR also issued a joint report in October 2013 on torture and deaths in\ndetention in Libya just prior to the commencement of the investigation mandate period.181\nIn the course of its investigation, OHCHR documented numerous alleged cases of torture\nand other forms of cruel, inhuman or degrading treatment, particularly of individuals in\ndetention facilities. The reports are not restricted to one facility, or one actor, but instead\nreveal alleged cases of torture and other ill-treatment in the majority of places of detention.\nIn some cases, torture has resulted in the death of persons in custody. This Section deals\nprimarily with torture of persons in the context of criminal justice and conflict-related\ndetention. Further alleged cases of torture are addressed in Section E on gender-based\nviolence and discrimination against women, and Section I on migrants."},{"id":"a-hrc-31-crp-3-p0160","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"160","seq":161,"section":"2. Legal framework","text":"International law contains an absolute prohibition of torture and other cruel,\ninhuman or degrading treatment or punishment, as set out inter alia in the Convention\nagainst Torture and Other Cruel, Inhuman or Degrading Treatment or Punishment (CAT)\nand ICCPR.182 The prohibition on torture is a peremptory norm of international law and\ncannot be limited or derogated from under any circumstances.183"},{"id":"a-hrc-31-crp-3-p0161","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"161","seq":162,"section":"2. Legal framework","text":"Under CAT, torture is defined as the intentional infliction of severe pain or suffering\n(whether physical or mental), for a specific purpose (e.g. to obtain information or a\nconfession, as punishment, to intimidate or coerce, or for any reason based on\ndiscrimination of any kind), by or at the instigation of a public official or other person\nacting in an official capacity (or with the consent or acquiescence of such).184 International\nhumanitarian law explicitly prohibits torture and cruel treatment of persons taking no active\npart or persons who have ceased to take part in hostilities.185 Such conduct constitutes a war\ncrime.186 Separately, it may amount to a crime against humanity if committed as part of a\nwidespread or systematic attack against civilians.187"},{"id":"a-hrc-31-crp-3-p0162","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"162","seq":163,"section":"3. Findings","text":"OHCHR documented alleged cases of torture including severe beatings on\ndetainees’ bodies or the soles of their feet with plastic pipes or electrical cables, prolonged\nsuspension in stress positions, solitary confinement, being held incommunicado, and\nelectrocution. Detainees also suffered from a lack of sufficient food or drinking water, and\nwere subjected to threats of a sexual nature and the extortion of payment in exchange for\nfreedom."},{"id":"a-hrc-31-crp-3-p0163","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"163","seq":164,"section":"3. Findings","text":"Torture was frequently reported by detainees as having been perpetrated at the time\nof arrest or apprehension, during interrogations or questioning, or during their detention in a\nnumber of facilities operated by both State and armed groups. The facilities specifically\nmentioned by persons interviewed included in the west:\n• Misrata-based Al-Saket prison\n• Al-Jawiya Institution for Correction and Rehabilitation (Air-Force Detention Centre,\nMisrata)\n• Abu Salim Detention Facility in Tripoli\n• Al-Hadaba Prison in Tripoli\n• Detention facility in Sabratha\n• Tajoura detention facility of the Department of Combatting Crime (Ministry of the\nInterior) in Tajoura operated by the Tripoli Revolutionaries Brigade\n• Military base of Bab Tajoura Battalion in Souq Al-Juma’a in Tajoura\n• Jandouba Prison in Gheryan\n• Fourth Force Battalion facility in Gheryan\n• Detention facilities in Mitiga Airport operated by armed groups\n• Detention facility in Al-Zawiya operated by the Al-Sai’qa Brigades of the Libyan\nNational Army\n• Mazraet Mansour al-Daw a makeshift facility operated by Tripoli Revolutionaries\nBrigade affiliated with Libya Dawn\nIn the east they included:\n• Gernada Prison in Al-Marj\n• Criminal Investigation Department of the Ministry of the Interior in Al-Marj\n• Al-Rajma military camp\n• Al-Fuweihat facility (controlled by the Al-Sai’qa Brigades of the Libyan National Army)\n• Al-Birsis facility (nominally under the control of the Department of Combatting\nTerrorism)\n• Al-Kwaifieh Prison\n• Military Police Facility in Al-Abyar\n• Military Base controlled by the Al-Sai’qa Brigades of the Libyan National Army in\nBu’Atni\n• Hassan Ben Haitham School in Benghazi, a makeshift facility controlled by the Al-Sai’qa\nBrigades of the Libyan National Army\n• Bodzeira Facility"},{"id":"a-hrc-31-crp-3-p0164","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"164","seq":165,"section":"3. Findings","text":"The Special Rapporteur on torture and other cruel, inhuman or degrading treatment\nor punishment sent urgent appeals to the Government of Libya in March and September\n2014 concerning allegations of torture and other cruel, inhuman or degrading treatment or\npunishment in Libya in relation to two individual cases.188"},{"id":"a-hrc-31-crp-3-p0165","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"165","seq":166,"section":"3. Findings","text":"One former detainee interviewed by OHCHR staff spoke of his capture in July 2013\nby Al-Zawiya Brigade, an armed group affiliated with Libya Dawn. He was held in the\nFirst Company (Sariya Al Oula) detention facility in Al-Zawiya until his release in March\n2014. He reported to OHCHR:\n“I was severely tortured during my detention on [an] almost daily basis; they used a\nplastic hose and batons to beat me. The guards were kicking and slapping me from\ntime to time. I was kept in a room with another 12 detainees. They all suffered the\nsame ill-treatment like me”."},{"id":"a-hrc-31-crp-3-p0166","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"166","seq":167,"section":"3. Findings","text":"Another man informed OHCHR that he was apprehended in October 2014 by the\n21st Al-Sai’qa Brigade of the Libyan National Army. He was accused of being involved\nwith Ansar al-Sharia and taken to a school which had been converted to a military base. He\ninformed OHCHR that:\n“Soon after I arrived at the school, I was severely beaten by the guards. They asked\nme to take my shoes off and walk on crushed glass which hurt me and led to severe\npain and bleeding in my feet. They also continued beating me with a hose and [with]\ntheir gun butts on my body including my face. My nose was broken and I was\nseverely bleeding. Nobody interrogated me and they continued insulting and\ntorturing me from 10.00 to 19.00. Then they put me in a dirty toilet while I was still\nhandcuffed. I was tortured again many times while I was in that toilet”."},{"id":"a-hrc-31-crp-3-p0167","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"167","seq":168,"section":"3. Findings","text":"Another case related to a man who was abducted by the Tripoli Revolutionaries\nBrigade in April 2015 from his house in Tajoura, 20 kilometres east of Tripoli. He stated:\n“They took me to a location called Mazra’et Mansour Al Daw (Mansour Al Daw\nfarm). I was severely beaten and some of the armed men would forcefully hit my\nhead against concrete walls until I severely bled from my head, in the meantime they\nwere firing gunshots into the concrete wall right next to my ears. I was threatened\nand beaten again until I fainted. I was taken on the following day to a second\nlocation named the Department of Combatting Crime [of the Ministry of the\nInterior] in Tajoura, which is located close to the airport. I was kept in solitary\nconfinement in a very dark cell for a period of three to four days. I was beaten on\nmultiple occasions for refusing to inform them of the location of my brother. I was\nalso interrogated about my family’s financial status and property. Three weeks\nlater, I was released after elders from my tribe intervened and negotiated my\nrelease”."},{"id":"a-hrc-31-crp-3-p0168","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"168","seq":169,"section":"3. Findings","text":"During the investigation, a video of interrogation sessions in Al-Hadaba prison\ninvolving Saadi Qadhafi was publicly released. He is seen in this video being subjected to\nacts which could constitute torture. UNSMIL urged the General Prosecutor to carry out a\nprompt and effective investigation, and called for the removal of individuals appearing in\nthe video from contact with inmates, pending the outcome of criminal investigations. The\nprosecution announced an investigation, and in response to UNSMIL’s letter stated that\narrests had been carried out without providing further details. 189"},{"id":"a-hrc-31-crp-3-p0169","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"169","seq":170,"section":"3. Findings","text":"Several cases involving public “confessions”, particularly from persons detained in\nAl-Birsis prison, were highlighted to OHCHR. The circumstances surrounding the\nconfessions and the content of the confessions indicate the strong likelihood of torture. In\none such case, an individual was held in custody in several locations, and accused of\nmurdering some 90 security and police officers. This man (whose relatives had been forced\nto flee owing to threats against them based on their western Libyan origins) later appeared\non Libya First Channel, confessing to involvement in the murder of several security and\npolice officers. The same video included the “confession” of a teenager from a family\noriginally from Sirte, but living in Benghazi. He had been apprehended by the Anti-\nTerrorism Force armed group in late December 2014, and was similarly transferred\nbetween detention facilities. In the video, he is seen “confessing” to the murder of 17\nsecurity and police officers. On the same day the video was aired, the Awliaa al-Damm\narmed group set fire to the family’s house. Neither men have been charged with an offence\nand remain in detention."},{"id":"a-hrc-31-crp-3-p0170","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"170","seq":171,"section":"3. Findings","text":"OHCHR received credible information relating to cases where torture or ill-\ntreatment in detention resulted in the death of detainees. At least 10 deaths were reported in\ndetention facilities, including the Al-Birsis facility, the military police facility in Al-Abyar,\nthe Military Intelligence Brigade in Al-Rajma, Al-Sai’qa military base in Bu’Atni, and in a\nfacility reportedly operated by the Tripoli Revolutionaries Brigade."},{"id":"a-hrc-31-crp-3-p0171","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"171","seq":172,"section":"3. Findings","text":"OHCHR has observed a lack of redress for alleged cases of torture and other ill-\ntreatment. For example, OHCHR documented the case of a 38 year old man who was\narrested in June 2014 by officers of the Criminal Investigation Department of Al-Marj\nwhich is part of the Ministry of the Interior. On the day after his arrest, his body, which\nreportedly showed signs of torture, was transferred to Al-Abyar hospital. The autopsy\nreport concluded that severe internal bleeding had been the cause of his death. The\nProsecutor from Al-Marj sought permission to question an official in relation to the\nincident. In this regard, a request was transmitted by the General Prosecutor of the Appeal\nCourt of Benghazi to the Tobruk-based Ministry of Justice. OHCHR was informed that the\nMinistry of the Interior denied the request, and the case was closed."},{"id":"a-hrc-31-crp-3-p0172","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"172","seq":173,"section":"1. Introduction","text":"The armed conflict in Libya has increased violence and discrimination against\nwomen in the country. Women and girls face multiple layers of discrimination and continue\nto suffer violations and abuses in addition to those encountered by the rest of the\npopulation. The assassinations, assaults, harassment and threats against women carried out\nby armed groups appear designed to send a broader message that women should not be\nvocal in the public sphere. Women and girls remain at risk of sexual and gender-based\nviolence, particularly by armed groups. In several parts of Libya, the ability of women to\nexercise their fundamental rights and freedoms such as freedom of movement or the right to\nwork, has been restricted not only as a result of the conflict, but as a result of requirements\nfor accompaniment by “male guardians”. Women also continue to face specific barriers in\nrelation to access to justice."},{"id":"a-hrc-31-crp-3-p0173","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"173","seq":174,"section":"1. Introduction","text":"While reference to violations and abuses carried out against women can be found\nthroughout this present Chapter, this Section seeks to highlight the particular gendered\nelement of many violations and abuses."},{"id":"a-hrc-31-crp-3-p0174","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"174","seq":175,"section":"2. Legal framework","text":"Libya is party to a number of instruments that enshrine the fundamental principle of\nequality and non-discrimination. In both ICCPR190 and ICESCR191 there are clear\nprovisions requiring that men and women enjoy all rights equally and without\ndiscrimination on the basis of sex. CEDAW provides a more detailed elaboration of rights\npertaining to non-discrimination against women. The fundamental importance of non-\ndiscrimination is replicated in other human rights instruments. While international\ninstruments refer to discrimination on the basis of sex, this present report uses the term\n“gender-based discrimination” to take into account the underlying social construction of\nroles between men and women that is evident in many reported violations against women in\nLibya."},{"id":"a-hrc-31-crp-3-p0175","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"175","seq":176,"section":"2. Legal framework","text":"Gender-based violence is a form of prohibited discrimination.192 States are under an\nobligation to take appropriate measures to eliminate gender-based violence and act with due\ndiligence to prevent, investigate, mediate, punish and redress sexual and gender-based\nviolence, including that perpetrated by non-State actors.193 Gender-based violence, in\nparticular sexual violence, violates the prohibition on torture and cruel, inhuman or\ndegrading treatment and also impairs other human rights including the right to the highest\nattainable standard of physical and mental health."},{"id":"a-hrc-31-crp-3-p0176","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"176","seq":177,"section":"2. Legal framework","text":"International humanitarian law expressly prohibits in Additional Protocol II “rape,\nenforced prostitution and any form of indecent assault”.194 Common article 3 to the Geneva\nConventions prohibits “violence to life and person, in particular … cruel treatment and\ntorture” and “outrages upon personal dignity, in particular, humiliating and degrading\ntreatment”. Rape, sexual slavery, enforced prostitution, forced pregnancy, enforced\nsterilisation and other forms of sexual violence are recognised as amounting to war crimes\nunder the Rome Statute195 and may constitute a crime against humanity if part of a\nwidespread or systematic attack on civilians.196 The Security Council has urged parties to\narmed conflict to protect women and children from sexual violence. Security Council\nresolution 1325 (2000) calls on all parties to the conflict to take special measures to protect\nwomen and girls from rape and others forms of sexual abuse. Security Council resolution\n1820 (2008) stresses that “sexual violence, when used or commissioned as a tactic of war in\norder to deliberately target civilians or as part of a widespread or systematic attack against\ncivilian populations, can significantly exacerbate situations of armed conflict”. 197"},{"id":"a-hrc-31-crp-3-p0177","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"177","seq":178,"section":"3. Findings","text":"There has been a series of attacks by armed groups against women who promote\nequality, social justice, and accountability in Libya. The targets of attacks have included\nwomen who were members and founders of non-governmental organizations, women who\nwere members or former members of parliament, and others who were members of civil\nsociety and outspoken in the media."},{"id":"a-hrc-31-crp-3-p0178","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"178","seq":179,"section":"3. Findings","text":"In one such case, lawyer and female activist Salwa Bugaighis198 was assassinated on\n25 June 2014 (on the same day as elections for the House of Representatives) in her house\nin Benghazi. The autopsy revealed that she was shot multiple times in the head and chest.\nHer husband was disappeared. A joint communication was sent by five special procedure\nmandate holders to the Government of Libya on the killing of Salwa Bugaighis and the\ndisappearance of her husband. As at the time of writing, the Government is yet to\nrespond.199"},{"id":"a-hrc-31-crp-3-p0179","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"179","seq":180,"section":"3. Findings","text":"Fareeha Al-Berkawi, a former member of the General National Congress, was\nknown for campaigning against corruption. She was shot dead in her car in Derna on 17\nJuly 2014. Witnesses reported that armed individuals approached her car asking her “Are\nyou Fareeha Al-Berkawi?” before shooting her three times in the chest. She died\ninstantaneously."},{"id":"a-hrc-31-crp-3-p0180","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"180","seq":181,"section":"3. Findings","text":"Intissar Al-Hasaeri was another well-known female activist who organised protests\nagainst armed groups. She was a vocal supporter for democracy and secular government\nand had led many protests against the attacks of Tripoli airport and the seizure of Tripoli by\nLibya Dawn. She was found shot dead after having gone missing the day before on 24\nFebruary 2015. Her body, together with that of her aunt, was found in a car on the outskirts\nof Tripoli."},{"id":"a-hrc-31-crp-3-p0181","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"181","seq":182,"section":"3. Findings","text":"Other attacks against female human rights defenders and journalists have been\ndescribed in this present report in Section H on human rights defenders and journalists.\nSuch attacks, and the brutality of the methods used, appear designed to send a broader\nmessage that women should not be vocal in the public sphere.\n(b)         Sexual and gender-based violence"},{"id":"a-hrc-31-crp-3-p0182","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"182","seq":183,"section":"3. Findings","text":"OHCHR has received credible reports of different armed groups committing sexual\nand gender-based violence against women, girls and boys, with complete impunity. Some\nof these accounts have been described in this present report in Section K on children, and\nSection I on migrants."},{"id":"a-hrc-31-crp-3-p0183","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"183","seq":184,"section":"3. Findings","text":"Owing to the stigma still attached to sexual assault, family pressure, and trauma, it\nremains difficult for the subject to be spoken of openly. Fears have also been expressed of\nretaliation. OHCHR staff spoke with a number of women who reported they were subjected\nto sexual violence but did not wish to provide detailed accounts and/or have their stories\nshared publicly. Further specialist investigation would be necessary to reveal the extent of\nsexual and gender-based violence which has occurred.200 Notwithstanding these limitations,\nOHCHR documented a small number of first-hand accounts of sexual violence, particularly\nin the context of detention or captivity."},{"id":"a-hrc-31-crp-3-p0184","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"184","seq":185,"section":"3. Findings","text":"OHCHR documented the case of one woman who was abducted in Tripoli. She was\non her way to work when abducted by armed men in a vehicle with tinted glass and taken to\na location in a residential area on the outskirts of Tripoli. She was held there for a few days\nand later moved to another location after being drugged. She reported that she was\nrepeatedly raped by an armed group leader for a period of over six months. The leader\nwould always make sure that the room was completely dark when he came in, as he did not\nwant to be identified. She was able to escape with the help of a member of the armed group\nwho was originally from her neighbourhood. The woman stated that she saw six girls as\nyoung as 11 who were subjected to sexual violence by armed group members. After her\nescape, she realized that she was pregnant, and out of her fear of being exposed, she\ntravelled to another country in order to terminate the pregnancy. In addition to the trauma\nfrom the rape, she feared the ongoing social impact of her experience: fearing that she\nwould not be able to get married if exposed. She had also experienced considerable anxiety\nover exposure to a sexually transmitted disease, stating she almost had a nervous\nbreakdown, “I waited for the HIV test for six months, and I couldn’t even be happy when\nthe doctor called me to say that I am free from AIDS”."},{"id":"a-hrc-31-crp-3-p0185","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"185","seq":186,"section":"3. Findings","text":"Physicians interviewed by OHCHR staff have confirmed that their practices have\ncarried out medical abortions for women who were raped by armed group members in\nLibya, while respecting confidentiality and not disclosing details of the women. They have\nrecounted being told of forms of torture and sexual violence perpetrated against the women\nincluding being forced to undress and stand naked for hours, and being tied up to a bed and\nraped."},{"id":"a-hrc-31-crp-3-p0186","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"186","seq":187,"section":"3. Findings","text":"Most of the women that OHCHR have spoken with who have been subjected to\nsexual violence remain heavily traumatized. Suicide attempts are very common amongst\nthis group, and survivors interviewed had visible signs of trauma and severe depression.\n(c)         Equality and non-discrimination"},{"id":"a-hrc-31-crp-3-p0187","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"187","seq":188,"section":"3. Findings","text":"Many women in Libya reported greater challenges to their fundamental rights in the\nenvironment of post-revolution Libya. Some drew attention to religious decrees and\nstatements issued by the Grand Mufti of Libya, undermining equality and imposing\nrestrictions on women. He has publically stated that “[CEDAW] states that any distinction,\nexclusion or restriction on the basis of sex is banned. This is the starting point of the\ndisagreement between the Quran and CEDAW, as God says: the male is not like the female,\nyet they say men and women are equal”.201 Such statements have been seen as evidence of\nthe entrenchment of a rigid ideology that, when implemented, is harmful to women’s rights."},{"id":"a-hrc-31-crp-3-p0188","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"188","seq":189,"section":"3. Findings","text":"In relation to freedom of movement, for instance, women reported that even at\nairports and at border checkpoints in Libya, they had been asked about their male\nguardians. Some were warned not to travel without a male guardian otherwise they would\nbe subject to punishment.202 Some have had their travel rejected by security personnel and\nat times by armed group members because they were travelling without a male guardian.\nOne woman reported that she was stopped by Ansar al-Sharia armed groups in the outskirts\nof Derna while driving her car and was forced to contact her brother to come and drive her\nrather than being permitted to drive home alone. She was threatened to be “lashed” the next\ntime she was found alone on the streets. Her brother was reprimanded for not looking after\n“his property”. Another journalist in Tripoli was stopped by armed men loyal to the\nDeterrence and Assistance Force which is affiliated with Libya Dawn while driving her car\nwith a male colleague on their way to a meeting. They forced her to stop at a corner then\nforcefully took her and her colleague to their headquarters, a house in a residential area.\nAfter prolonged questioning and accusations that she was a “woman of mixed virtues”, she\nwas not released until her father came to their headquarters. Her father was verbally abused,\nand warned not to leave her “running the streets unattended again”."},{"id":"a-hrc-31-crp-3-p0189","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"189","seq":190,"section":"3. Findings","text":"Women have also reported difficulties in accessing basic services from the\nGovernment. Several cases documented by OHCHR in Tripoli concerned difficulties\nwomen faced in obtaining official documentation, such as the issuance of a passport or\nother identity documents, if women approached a civil servant without the presence of a\nmale guardian."},{"id":"a-hrc-31-crp-3-p0190","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"190","seq":191,"section":"3. Findings","text":"In areas controlled by groups pledging allegiance to ISIL, some women have\nreportedly been confined to their home owing to the fear of being exposed to harassment,\nabduction, and servitude by members of those groups. According to reports, older girls and\nwomen are not allowed to leave their houses without being fully covered up, including\ncovering their face (niqab). Some women have reported that they were no longer able to\nwork or even be seen on the streets publicly - especially without a male guardian - out of\nfear of retaliation by groups pledging allegiance to ISIL or Ansar al-Sharia.\n(d)         Access to justice"},{"id":"a-hrc-31-crp-3-p0191","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"191","seq":192,"section":"3. Findings","text":"OHCHR staff interviewed a number of women who said that they had no means to\nfile complaints or seek remedies for violations or abuses committed against them. They\nassessed there to be a high level of risk of retaliation should they complain of the violations\nor abuses. A number of women stated that they would not approach a police station or other\nlaw enforcement facility as they could not be sure whether officials or armed groups were\nin charge, and that if they approached the facility they could be murdered or raped by\narmed group members.203 One of the biggest concerns articulated by women whom\nOHCHR staff interviewed was that there would be continuing impunity for perpetrators of\nhuman rights violations and abuses."},{"id":"a-hrc-31-crp-3-p0192","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"192","seq":193,"section":"1. Introduction","text":"The escalation of fighting since 2014 has adversely affected access to economic,\nsocial and cultural rights including to housing, education, healthcare, and food. Warring\ngroups have looted, damaged, and destroyed homes and other vital infrastructure.\nRoadblocks and security-related threats have significantly impeded the movement of\nessential goods such as food and medicine, and inhibited humanitarian assistance. The\nprovision of services has also been affected by a lack of qualified personnel, and\nGovernment action or inaction in relation to emergency management and use of\nGovernment funds. Available funding has been primarily directed towards wages of civil\nservants. Significantly lesser appropriations have been directed towards service delivery\nand institution strengthening.204 The situation has been compounded by the decision of the\nCentral Bank to withhold payments to many Government entities and programmes to\nsafeguard reserves, in light of the decline in Libya’s national revenue. 205 All these factors\nhave had a negative impact on individuals’ access to services necessary to enjoy their\nrights."},{"id":"a-hrc-31-crp-3-p0193","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"193","seq":194,"section":"1. Introduction","text":"Women, internally displaced persons, children, and migrants face particular\ndifficulties in enjoying their economic, social, and cultural rights. Resources (including\ninternational resources and assistance) need to be urgently harnessed to create conditions\nfor the re-building of necessary systems to underpin the enjoyment of economic, social, and\ncultural rights."},{"id":"a-hrc-31-crp-3-p0194","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"194","seq":195,"section":"2. Legal framework","text":"Libya is a party to ICESCR which contains a range of guarantees, including the\nrights to work, education, physical and mental health, an adequate standard of living social\nsecurity, family and cultural life.206 States are obliged to take steps to the maximum of their\navailable resources with a view to progressively realising these rights. 207 States are obliged\nto respect, protect and fulfil these rights. This includes refraining from any action that\nwould interfere with the enjoyment of the rights, addressing actions by third parties which\ninfringe upon the rights (including actions by armed groups), and taking all necessary\nmeasures to guarantee the enjoyment of these rights on a non-discriminatory basis. While\nan armed conflict may significantly undermine individuals’ enjoyment of these rights\n(including through the destruction of infrastructure), States retain the obligation to prioritise\naccess to these rights and do everything possible to at least realise the “core minimum”\ncontent of rights, including by facilitating access to humanitarian assistance.208"},{"id":"a-hrc-31-crp-3-p0195","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"195","seq":196,"section":"2. Legal framework","text":"International humanitarian law also contains a range of rules that address aspects of\neconomic, social and cultural rights. Amongst these are prohibitions on the use of starvation\nas a method of warfare,209 and the prohibition on attacking, destroying or rendering useless\nobjects indispensable to the survival of the civilian population (e.g. food, crops, and water\ninstallations).210 Parties to armed conflicts must allow and facilitate rapid and unimpeded\nhumanitarian relief for civilians in need.211"},{"id":"a-hrc-31-crp-3-p0196","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"196","seq":197,"section":"3. Findings","text":"Prior to 2011, the Libyan authorities made major investments in the health sector\nthat led to significant improvements in the delivery of healthcare, and in the general health\nof the population.212 The armed conflict in 2011 adversely affected the health system,\nwhich had not properly recovered by the time hostilities broke out in 2014. The health\nsector has been further weakened during the reporting period of the investigation for several\nreasons. Healthcare facilities have been targeted, damaged and/or looted. Healthcare\npersonnel have been harassed and abducted by different armed groups (see Section B on\nattacks on civilians and civilian objects, and other protected persons and objects). Many\nforeign medical personnel have left Libya owing to the violence. OCHA reported that over\n60 per cent of hospitals have been inaccessible or closed in conflict areas between March to\nSeptember 2015, especially in the eastern and southern regions. 213 The result is that as of\nSeptember 2015, 1.9 million people in Libya required essential humanitarian aid in order to\nmeet basic healthcare needs.214"},{"id":"a-hrc-31-crp-3-p0197","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"197","seq":198,"section":"3. Findings","text":"Healthcare facilities that remain operational were impacted by a shortage of drugs\nand medical supplies. In Benghazi, the situation was exacerbated in July 2014 after a\nwarehouse of medical supplies was destroyed, affecting the supply for the entire eastern\nregion. In the east, fighting also led to the destruction of the warehouse at Al-Hawari\nhospital.215"},{"id":"a-hrc-31-crp-3-p0198","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"198","seq":199,"section":"3. Findings","text":"While these attacks and the difficulties associated with the security situation have\nbeen the dominant cause of shortages, the situation has been impacted by governmental\ndecision-making and/or failures to take necessary action. According to information\nreceived, the Government has not taken steps to address, prevent, and ensure non-repetition\nof such attacks, and has further made limited investment to the infrastructure of the health\nsector in Libya. Furthermore, budget cuts implemented across Government departments\nhave had a negative impact on the availability of health services within Libya.216 The\nsystem is thus commonly described as collapsing. As in the Qadhafi era, the Government\ncontinues to pay healthcare expenses for some Libyan citizens to receive necessary\noverseas treatment, although the criteria for the selection of cases remains unclear."},{"id":"a-hrc-31-crp-3-p0199","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"199","seq":200,"section":"3. Findings","text":"Additionally, authorities have not addressed structural and administrative\ndeficiencies on a timely basis. The World Health Organization (WHO) has referred to the\nabsence of clear referral mechanisms, and guidelines, and a lack of effective coordination\nand crisis management skills among crisis (response) committees.217 An increased risk of\ntransmission of communicable diseases was reported in May 2015, and attributed in part to\nthe absence of an early warning alert and response system, and the irregularity of reporting\nto the National Centre for Disease Control in earlier months.218\n(b)         Right to education"},{"id":"a-hrc-31-crp-3-p0200","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"200","seq":201,"section":"3. Findings","text":"In 2005, Libya was considered the country with the highest literacy and educational\nenrolment rates in north Africa.219 According to a study published in June 2015, half of the\nchildren in Libya are not attending school.220"},{"id":"a-hrc-31-crp-3-p0201","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"201","seq":202,"section":"3. Findings","text":"Some 40 per cent of schools in Libya have been damaged since the armed conflict in\n2011.221 That number has further increased following the fighting in 2014 and 2015. In\nBenghazi, it is reported that 73 per cent of all schools are not functioning, 222 with schools\nhaving been either damaged, destroyed, occupied by internally displaced persons,223\nconverted into military or detention facilities, or otherwise dangerous to reach.224 Amongst\nthe cases investigated by OHCHR was, for instance, the use of a primary school in\nBenghazi as a base and a detention facility by an armed group. UNOSAT satellite imagery\nof the school obtained as at August 2015 showed the presence of several cargo vehicles,\npossibly used for military purposes. Many children are residing in camps for internally\ndisplaced persons, without access to proper education facilities. A recent study noted that\nchildren with disabilities have difficulties in accessing any form of education, and are often\ncompletely excluded from the formal education system. 225 OHCHR received very little\ninformation on the steps taken by the Government to address gaps in children’s access to\neducation. This issue is addressed in Section K on children.\n(c)         Right to food and water"},{"id":"a-hrc-31-crp-3-p0202","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"202","seq":203,"section":"3. Findings","text":"The armed conflict has resulted in significant food insecurity affecting over 1.28\nmillion people, including internally displaced persons. The most severe cases are in\nBenghazi and the south. This has resulted mainly from the disruption of commercial supply\nroutes owing to the fighting, and has thus reduced the availability of food stuffs, increased\nprices, and increased the loss of livelihood for individuals and families which has\ncompromised their ability to meet their needs.226 Prices of staple foods such as rice, flour\nand sugar have risen sharply."},{"id":"a-hrc-31-crp-3-p0203","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"203","seq":204,"section":"3. Findings","text":"While many of the reasons for the food shortages are directly related to the conflict\noutside of immediate Government control, Government action and inaction has also played\na role. WFP reported in November 2015 that the Government was reducing or cutting food\nsubsidies.227 When combined with the rise in prices of foodstuffs, families were reportedly\nneeding to reduce portions or miss meals to cope."},{"id":"a-hrc-31-crp-3-p0204","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"204","seq":205,"section":"3. Findings","text":"The armed conflict has resulted in the disruption of main water networks, 228\naffecting access to safe drinking water, and water adequate for sanitation and hygiene. In\nsome cases this disruption appears to have been deliberate. In one case investigated by\nOHCHR in Al-Nasiriyah, armed groups were reported to have destroyed a water-well, by\nbreaking the pumps and congesting the well, rendering it unusable. As with other aspects of\nthe conflict which are disrupting access to economic and social rights, it is imperative that\nsuch actions are urgently addressed and remedied.\n(d)         At risk and marginalised groups"},{"id":"a-hrc-31-crp-3-p0205","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"205","seq":206,"section":"3. Findings","text":"In addition to security threats, a number of social groups face particular difficulties\nin relation to their enjoyment of economic, social and cultural rights. Sections E and K of\nthis present Chapter address specifically the challenges faced by women and children in this\nrespect. As fighting in and around urban areas has led to the destruction of homes, and\ntriggered large-scale displacement, the number of internally displaced persons has sharply\nincreased from 80,000 in May 2014 to 435,000 in May 2015.229 Many live with relatives or\nin make-shift accommodation, including schools and warehouses. They have often lost their\nlivelihoods, and have experienced greater difficulty in accessing education and healthcare.\nInternally displaced persons wishing to return to their homes also lack access to\nmechanisms for property restitution, reconstruction of their homes, or compensation.230\nMigrants face discrimination in accessing services which can undermine their access to\nemployment, housing, healthcare, and education. The absence of a legislative and\nprotection framework for refugees exacerbates the situation.\n(e)     Humanitarian assistance"},{"id":"a-hrc-31-crp-3-p0206","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"206","seq":207,"section":"3. Findings","text":"The delivery of much needed humanitarian aid has been hindered by the security\nsituation, which is illustrated by several attacks by armed groups directed against\nhumanitarian workers (as described in Section B). The conflict has also caused most of the\ninternational humanitarian aid community to relocate to neighbouring countries and\nmanage their operations remotely. According to Sheikh al-Tahir al-Zawi Organization (an\nimplementing partner of several international organizations for the distribution of food and\nnon-food items), several areas cannot be accessed at all. 231 Most national and international\norganizations further cannot access areas controlled by groups pledging allegiance to ISIL.\nMany areas have seen a sharp decrease in basic goods and food, health, and sanitation\nsupplies."},{"id":"a-hrc-31-crp-3-p0207","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"207","seq":208,"section":"1. Introduction","text":"The Libyan judicial system has been the target of crippling, violent attacks with\nactors such as judges and prosecutors being subject to killings, assaults, abductions, and\nthreats. Such attacks have caused the system to come to a halt in many areas of Libya, in\nparticular the eastern and central regions, and have compromised the functioning of the\ncourts that remain open. The system for providing security for judicial actors is inadequate,\nwith armed groups continuing to exercise control over many facilities which are formally\nwithin the Ministry of Justice. Thousands of conflict-related detainees from the armed\nconflict in 2011 remain without access to judicial review, with the same fate experienced by\nthose detained in 2014 and 2015. Key appointments with respect to judges and other\njudicial officials have become caught up in the broader political dispute in Libya. In the\ntrials which are being carried out (such as the high profile trial of the former senior Qadhafi\nregime officials), significant concerns have been noted in relation to fair trial guarantees.\nThe end result is a lack of genuine access to justice."},{"id":"a-hrc-31-crp-3-p0208","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"208","seq":209,"section":"2. Legal framework","text":"International human rights law provides guarantees to any person appearing before\ncourts and tribunals and obliges States to ensure that any person whose rights or freedoms\nare violated has access to an available, prompt and effective remedy. In order to guarantee\nthis, effective administration of justice is crucial. In both criminal and civil cases, persons\nhave a right to a fair and public hearing by a competent, independent, and impartial tribunal\nestablished by law.232 As noted in Section C on arbitrary detention, abductions, and\ndisappearances, persons who are detained have a range of rights in relation to challenging\nthe lawfulness of their detention, and those accused of a criminal offence have rights to trial\nwithin a reasonable time or release, and to compensation in the case of unlawful arrest or\ndetention.233 Detailed rights are provided with respect to ensuring a fair trial in both\ninternational human rights and humanitarian law.234 More broadly, the protection of human\nrights requires a functioning judicial system in order that persons may access lawyers and\ncourts to obtain remedies for violations and ensure the system does not in itself violate the\nrights of persons. Further standards have been developed to elaborate on what is required in\norder to respect the role of actors within the judicial system, including the independence of\nthe judiciary.235 This includes attention to appointment procedures for judges,236 terms of\noffice, conditions of service, security, and protections against conflicts of interest and\nintimidation.237"},{"id":"a-hrc-31-crp-3-p0209","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"209","seq":210,"section":"3. The judiciary and the courts","text":"Attacks targeting the judiciary directly impact the administration of justice and the\nrule of law. The judiciary has been the target of intimidating and lethal attacks. Court\npremises have been bombed and judges and prosecutors238 have been subjected to\nassassinations, assaults, and abductions. The attacks include a fatal bomb attack at the\nSouth Benghazi Court in January 2014, the assassination of a judge and former Prosecutor-\nGeneral in Derna in February 2014, and the abduction of the Deputy Director General of\nthe High Judicial Institute in April 2014. In August 2014, the offices of the Prosecutor-\nGeneral and courts in central Tripoli were shelled. At times, attacks have been linked to\nspecific demands, such as the detention or release of certain individuals, or to thwart the\narrest and prosecution of members of armed groups."},{"id":"a-hrc-31-crp-3-p0210","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"210","seq":211,"section":"3. The judiciary and the courts","text":"Assassinations and abductions of judges and prosecutors have had a particularly\ndebilitating effect. In some parts of Libya, courts have ceased functioning. In Tripoli, courts\nwere forced to suspend activities during the hostilities in July and August 2014. 239 In\nDerna, Sirte and Benghazi, court operations were halted in 2014. It is reported that in South\nBenghazi, judges and prosecutors resolved to resume their work in June 2015, although it\nwould appear that the functioning is significantly reduced. The court of North Benghazi, the\nother court in the city, has remained closed.240 It has been difficult for OHCHR, UNSMIL,\nor other United Nations actors to gain comprehensive up-to-date information on the\nfunctioning of the courts across Libya. It is understood that some courts in the west are\noperational, though their focus is more on handling civil cases which are regarded as less\nsensitive than criminal justice matters."},{"id":"a-hrc-31-crp-3-p0211","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"211","seq":212,"section":"3. The judiciary and the courts","text":"An official within the office of the Attorney-General informed OHCHR that the\noffice is continuing to undertake investigations and issue arrest warrants. Further, the\nofficial reported that many arrest warrants have been issued against members of armed\ngroups, although they have not yet been executed. Further action with respect to arresting\nand charging persons has been put on hold until the security situation improves. As an\nexample of current limits on functioning, the Attorney-General has communicated with\nauthorities in the east on the disappearance of prosecutor Abd al-Nasser al-Jeroushi, but has\nnot received any information concerning his fate or whereabouts."},{"id":"a-hrc-31-crp-3-p0212","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"212","seq":213,"section":"3. The judiciary and the courts","text":"On the basis of the information received and reviewed, OHCHR considers that the\nsystem for providing security for judicial actors (and for those attending court houses and\nother facilities) is inadequate. The Judicial Police have the primary responsibility for\nmaintaining the security of courts, however, their ranks include some 10,000 armed group\nmembers who were integrated during the demobilisation efforts after 2011 without\ncomprehensive vetting.241 It has been reported to OHCHR that some members of the\nJudicial Police retain primary allegiance to these armed groups. This compromises the\nability of the Judicial Police as an institution to provide effective protection against the\nthreat posed by armed groups."},{"id":"a-hrc-31-crp-3-p0213","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"213","seq":214,"section":"3. The judiciary and the courts","text":"UNSMIL/OHCHR previously reported that only about half of Judicial Police\nofficers were estimated to have been reporting for duty during the fighting in 2014. 242 Even\nat full strength, the Judicial Police force lacks the capacity and equipment to repel well-\narmed attacks. In many facilities belonging to the Ministry of Justice, control appears to be\nexercised by localised armed groups rather than the Judicial Police."},{"id":"a-hrc-31-crp-3-p0214","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"214","seq":215,"section":"3. The judiciary and the courts","text":"UNSMIL/OHCHR has previously advised Libyan authorities on the need for threat\nassessments and appropriate security plans for the protection of the courts and the judiciary,\nwith the support of at least the Ministries of the Interior and of Defence.243 In the absence of\nproper protection, the system will not achieve the justice it is obliged to deliver. As a\nformer Minister of Justice told OHCHR, “a frightened judge cannot rule”."},{"id":"a-hrc-31-crp-3-p0215","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"215","seq":216,"section":"4. Conflict-related detainees","text":"Since the armed conflict in 2011, thousands of individuals have been detained, the\nvast majority of whom continue to be held without due process. As of March 2014, some\n6,200 people were held in facilities under the control of the Ministry of Justice. Only 10 per\ncent of these individuals had been tried and were serving prison sentences.244 Cases of\ndetainees were to be screened by prosecutors so that they would either be charged and\nbrought to trial or released. Even before the breakdown of judicial services in 2014,\nprogress was minimal. Deadlines set by national legislation were not met on successive\noccasions.245 The situation is not believed to have improved during 2015. During the\nconflicts in 2014 and 2015, the number of conflict-related detainees has increased. The\nlevel of arbitrary detention and the lack of access to judicial review are described in Section\nC."},{"id":"a-hrc-31-crp-3-p0216","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"216","seq":217,"section":"5. Investigations and prosecutions of human rights violations and abuses","text":"UNSMIL/OHCHR has previously reported that as a result of the collapse of the\ncriminal justice system in many parts of Libya, victims have little recourse to seek\nprotection, or to an effective remedy for violations and abuses.246 It concluded that little\naction has been taken to open prompt, thorough, effective, impartial, and independent\ninvestigations and to bring perpetrators to justice.247 This assessment is consistent with the\nfindings in this present report."},{"id":"a-hrc-31-crp-3-p0217","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"217","seq":218,"section":"5. Investigations and prosecutions of human rights violations and abuses","text":"Furthermore, serious shortcomings have been noted in relation to the criminal justice\nproceedings which have been conducted. In this regard, on 28 July 2015, the Tripoli Court\nof Assize issued its verdict in the trial of 37 senior Qadhafi regime officials on charges\nlinked to crimes committed during the armed conflict in 2011. Saif al-Islam Qadhafi,\nformer intelligence chief Abdullah al-Senussi,248 the last prime minister of the Qadhafi\nregime Al-Baghdadi al-Mahmudi and six other defendants were sentenced to death by\nfiring squad. Eight others received sentences of life imprisonment. The remainder of those\nconvicted were sentenced to between five and 12 year prison terms. UNSMIL/OHCHR\nexpressed serious concerns that proceedings fell short of international fair trial standards.\nThe right to adequate defence was not upheld, complaints of torture by a number of\ndefendants were not investigated, and the prosecution relied solely on the case file as\nevidence without presenting witnesses or documents in open court.249"},{"id":"a-hrc-31-crp-3-p0218","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"218","seq":219,"section":"6. Politicisation","text":"The political divisions between the House of Representatives and the General\nNational Congress have also had an impact on the judicial system. Notwithstanding its\ndisputed status, the Congress has passed laws on the composition of the Supreme Judicial\nCouncil.250 It also appointed a new President of the Supreme Court, 251 upon the retirement\nDefence were given two months to ensure the cases of all detainees held by armed groups were\nscreened. The Law on Transitional Justice of September 2013 set a deadline of 90 days from\npromulgation, requiring detainees accused in relation to crimes under the previous regime to be either\nreleased or referred to the public prosecution.\nof the incumbent President, and appointed 36 judges in October 2015. 252 Owing to the\npolitical divisions, an official appointment of Attorney-General was not made in June 2014\nupon retirement of the incumbent. Instead the most senior Prosecutor is acting as Attorney-\nGeneral on an ad interim basis. In addition to disputed or neglected appointments, as\noutlined further in Chapter VII on the justice sector, some interlocutors expressed concern\nthat judicial actors had become compromised by succumbing to pressure from armed\ngroups in particular."},{"id":"a-hrc-31-crp-3-p0219","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"219","seq":220,"section":"1. Introduction","text":"“Cities of Fear” is a poem written by Abdul Salam al-Mismary, a Libyan poet,\nlawyer, and human rights defender. It is not known whether in the poem he was describing\nhis native city, Benghazi, but Abdul Salam al-Mismary suffered a high price for his\nactivities, being assassinated in mid-2013. He is just one of the human rights defenders who\nhave been targeted as a result of their work. The High Commissioner issued a specific call\nfor the protection of human rights defenders in Libya in October 2014,253 and\nUNSMIL/OHCHR produced a detailed report on their situation in March 2015. 254"},{"id":"a-hrc-31-crp-3-p0220","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"220","seq":221,"section":"1. Introduction","text":"The findings of this investigation are consistent with these earlier reports in so far as\nit has documented a considerable number of violations and abuses carried out against\nhuman rights defenders in Libya in 2014 and 2015. These have included cases of\nassassinations, attempted murders, abductions, threats, and unlawful raids on offices. The\nfear created by such actions, coupled with the impunity enjoyed by the perpetrators, has\nforced many human rights defenders to go into hiding or to flee Libya, and threatens to\nsilence independent voices within the country."},{"id":"a-hrc-31-crp-3-p0221","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"221","seq":222,"section":"2. Legal framework","text":"Human rights defenders is a term used to describe persons who, individually or with\nothers, act to promote or protect human rights.255 A human rights defender is not restricted\nto one profession, but may be any person or group of persons working to promote human\nrights: e.g. staff of a national human rights institution, or a human rights organization,\nhuman rights lawyers, journalists reporting on human rights issues, or doctors treating\nvictims. Human rights defenders enjoy the same rights as other persons."},{"id":"a-hrc-31-crp-3-p0222","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"222","seq":223,"section":"3. Findings","text":"OHCHR received a number of reports on the situation faced by human rights\ndefenders, including lawyers, journalists, bloggers and other activists. Submissions received\nreported that since the beginning of 2014, some 13 human rights defenders had been killed,\n36 arrested or abducted, and many others otherwise harassed, threatened or physically\ninsulted. On the basis of the information received, it is clear that human rights defenders\ncontinue to be targeted in Libya and face grave threats to their lives as a result of their\nactivities."},{"id":"a-hrc-31-crp-3-p0223","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"223","seq":224,"section":"3. Findings","text":"As described in Section A on unlawful killings and executions, a number of human\nrights defenders have been assassinated during the reporting period. Many of these cases\nhave targeted high profile activists, producing a chilling effect on the work of their peers.\nOne of the most prominent cases has been outlined earlier in this present report: the\nassassination of lawyer and human rights activist Salwa Bugaighis on 25 June 2014 (the\nsame day as the elections for the House of Representatives). The autopsy revealed that she\nwas shot multiple times in the head and chest. The main witness to the events was\nreportedly killed in police custody. To the knowledge of the OHCHR, no investigation has\nbeen launched into the witness’ death. The Prosecutor who was initially working on Salwa\nBugaighis’ case was abducted at a checkpoint in Benghazi and remains disappeared. The\nperpetrators of the attack remain unidentified. Several other cases of prominent women\nactivists who have been assassinated have been described in Section E on gender-based\nviolence and discrimination against women."},{"id":"a-hrc-31-crp-3-p0224","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"224","seq":225,"section":"3. Findings","text":"Two human rights defenders Tawfik Ben Sa’ud and Sami al-Kawafi were\nassassinated late at night on 19 September 2014, when driving in the Al-Keesh\nneighbourhood, south of the centre of Benghazi. Three cars accelerated towards them, and a\nnumber of persons travelling in these cars opened fire. Some persons interviewed attribute\nresponsibility to Ansar al-Sharia, noting that Tawfik Ben Sa’ud had previously spoken out\nagainst the brigades and anyone who justified their killings on Facebook as follows: “For\nanyone who [is] still supporting the brigades, particularly Ansar al-Sharia, I wish to\ninform you that the anger of [the] street is a sweeping volcano, so take the side of the\nstreet, not the side against it. The history is ruthless. In my view, anyone [who] justifies the\npractices of killers is a partner of these killers”.256"},{"id":"a-hrc-31-crp-3-p0225","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"225","seq":226,"section":"3. Findings","text":"OHCHR received reports of a number of other assassination attempts on human\nrights defenders. One instance concerned a human rights defender who had an explosive\ndevice placed on his car in Benghazi. The victim attributes responsibility to Ansar al-\nSharia. In another case, a human rights defender referred to having survived an\nassassination attempt in Benghazi in July 2014. His son also reportedly survived an\nabduction attempt a few weeks after by Ansar al-Sharia. He has since left Libya."},{"id":"a-hrc-31-crp-3-p0226","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"226","seq":227,"section":"3. Findings","text":"The chilling effect of such assassinations on other human rights defenders is clear.\nOne human rights defender reported receiving death threats, communicated by telephone\ncalls and text messages or social media. The messages on social media seen by OHCHR\nwere sent anonymously. Notwithstanding these threats, the human rights defender\ncontinued his activities in advocating for disbanding illegal armed groups, and empowering\nState security institutions. Yet, for him, the assassination of fellow human rights defender\nTawfik Ben Sa’ud in September 2014 was the point at which he decided to flee, first his\nhometown and then Libya, to seek safety elsewhere."},{"id":"a-hrc-31-crp-3-p0227","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"227","seq":228,"section":"3. Findings","text":"Families of human rights defenders have also been victims of abuses. A 24 year old\nhuman rights defender from Benghazi reported that his family’s house in Al-Laithi\nneighbourhood was looted and destroyed in November 2014 in response to his advocacy for\nthe rule of law and the disbanding of illegal armed groups. He also received death threats,\nforcing him to move location. The human rights defender reported his belief that Ansar al-\nSharia were responsible."},{"id":"a-hrc-31-crp-3-p0228","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"228","seq":229,"section":"3. Findings","text":"In a number of cases, OHCHR investigated threats against human rights defenders.\nOne human rights defender from Tripoli had established a new association aimed at raising\nawareness on democracy and human rights principles in the community. Soon after their\nfirst activity, he received text messages warning him to stop his advocacy work, otherwise\nhe would be abducted and killed. He reported that:\n“As soon I published statements on my Facebook account stating that I was against\nthe shelling of civilian neighbourhoods during the Libya Dawn operation to control\nTripoli Airport, I received more than 20 messages accusing me of being a\ncollaborator with Haftar’s forces Operation Dignity. My private car was then\nvandalized and a message was left on the car saying “The next is your head”. So I\ndecided to flee the country immediately”."},{"id":"a-hrc-31-crp-3-p0229","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"229","seq":230,"section":"3. Findings","text":"Another case documented by OHCHR was of the abduction of the head of a Tripoli-\nbased human rights organization. He reported that he issued a statement asking the\nparliament to dismiss the General Mufti of Libya, Al-Sadiq al-Gheryani, and to lift his\nimmunity. Soon after, he was abducted from the street in Tripoli, describing his experience\nas follows:\n“Four armed men stepped out from two civilian cars and attacked me while I was\nwalking on the street. They opened fire in the air before approaching me, so I was\ncompletely terrified. I thought they wanted to kill me in public. They handcuffed me\nand covered my head with a plastic bag and put me in the backseat of one of their\ncars. They did not beat me while in the car but they cursed and accused me of being\na collaborator. After driving for around half an hour, we arrived at a military base.\nI was not able to see the people or to identify my whereabouts. They just put me in a\nsmall cell, removed the bag and handcuffs and then left. During the first four days of\nmy detention, I was completely incommunicado as I was not able to communicate\nwith any person, call my family or at least know my whereabouts”."},{"id":"a-hrc-31-crp-3-p0230","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"230","seq":231,"section":"3. Findings","text":"Another prominent human rights defender from Tripoli reported to OHCHR:\n“Due to my activities in human rights and my position against Libya Dawn, I\nreceived many threats on my mobile and recently my wife found a paper on my\nhouse’s front door. The paper included my photo and three words describing me as\nan apostate, collaborator and secular in addition to two more words indicating that\nI’d be killed soon. A real bullet was also enclosed with the letter to confirm the\nseriousness of the threat. Therefore I decided to flee the county as soon as possible”."},{"id":"a-hrc-31-crp-3-p0231","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"231","seq":232,"section":"3. Findings","text":"Women human rights defenders have reported similar threats against them, noting\nthat the intimidation and harassment is designed not only to deter their own activity, but to\ndeter other women from being vocal in the public sphere. This subject is explored further in\nSection E on gender-based violence and discrimination against women.\n(b)   National Council of Civil Liberties and Human Rights"},{"id":"a-hrc-31-crp-3-p0232","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"232","seq":233,"section":"3. Findings","text":"The national human rights institution of Libya, the National Council of Civil\nLiberties and Human Rights (NCCLHR), has been subjected to continuing attacks and has\nbeen reduced to minimal functioning. As UNSMIL/OHCHR reported in October 2014,\nNCCLHR members and staff received threatening calls by persons claiming to be affiliated\nwith Libya Dawn. Armed men apparently associated with Libya Dawn later went to the\nCouncil’s office requesting the handover of keys and official stamps. This request was\nrefused. In a separate visit, armed men wished to question some senior staff and members\nof the NCCLHR who were absent at that time. Further threats were received by individual\nmembers and staff, causing several to leave Libya.257 The Benghazi offices of NCCLHR\nwere raided on 16 March 2015, and one of its staff members reported having survived an\nassassination attempt in January 2015.258 Concern has previously been expressed by\nOHCHR in relation to the situation faced by the NCCLHR.259"},{"id":"a-hrc-31-crp-3-p0233","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"233","seq":234,"section":"3. Findings","text":"Much of the public functioning of the NCCLHR has ceased with the Tripoli office\nclosing in November 2014, and the Benghazi office having suspended operations in\nOctober 2014.260 However, the NCCLHR is undertaking some activities. In May 2015, it\nsubmitted a report in relation to the Universal Periodic Review of Libya. In August 2015,\nthe NCCLHR submitted two human rights reports to the House of Representatives. The\nreports addressed the situation in Sirte and Tarhouna. It is evident, however, that in light of\nthe attacks and intimidation the NCCLHR is not presently able to effectively pursue its full\nmandate."},{"id":"a-hrc-31-crp-3-p0234","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"234","seq":235,"section":"3. Findings","text":"The situation has been further complicated by the political conflict between the\nHouse of Representatives and the General National Congress. The terms of incumbent\nCommissioners of the NCCLHR formally ended at the end of 2014. Repeated calls have\nbeen made for new appointments or extensions to be made pursuant to Law No. 5 of 2011.\nIn September 2015, the House of Representatives Human Rights Committee issued a\nstatement that incumbent commissioners should continue in their mandate until procedures\nfor a new term are complete. In March 2015, the General National Congress adopted a\ndecision appointing a new set of Commissioners for the NCCLHR (that is, creating a\nseparate body). The Government (through the Permanent Mission of Libya to the United\nNations in Geneva) requested that the Human Rights Council ignore the decision of the\nGeneral National Congress. The body appointed by the General National Congress has\nissued a number of statements in the name of the NCCLHR.\n(c)     Journalists"},{"id":"a-hrc-31-crp-3-p0235","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"235","seq":236,"section":"3. Findings","text":"Journalists, who may also be human rights defenders, play a key role in society in\npromoting accountability and as watchdogs of civil liberties and other issues of public\ninterest and concern. Of particular importance to journalists in their work is freedom of\nexpression, including the freedom to access and impart information and ideas of all kinds.\nEqually, however, they are entitled to the full range of protections relating to, for example,\ntheir liberty and security, freedom of movement, and the right to work. Furthermore,\ninternational human rights law requires that they be protected from other acts intended to\ndissuade journalists from their professional duties such as torture, arbitrary detention,\nenforced disappearance, and excessive punitive measures and penalties. Under international\nhuman rights law, imprisonment is never an appropriate penalty for defamation. 261 Under\ninternational humanitarian law, journalists, as part of the civilian population, are protected\nfrom attack."},{"id":"a-hrc-31-crp-3-p0236","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"236","seq":237,"section":"3. Findings","text":"Libya continues to be one of the most hostile countries for journalists. Reporters\nWithout Borders ranked Libya 154 out of 180 countries in 2015 in this regard. 262 With the\ndeterioration of the situation in 2014, journalists struggled with an increasingly difficult\nclimate rendering objective news reporting a life-threatening endeavour. Journalists are\nparticularly at risk if they are perceived as being critical of those exercising power in any\ngiven area of Libya. In the course of the investigation, OHCHR collected first-hand\naccounts, and relied on submissions received and on open source material in which\njournalists have themselves documented their stories. On the basis of the information\navailable, OHCHR has concluded that journalists have faced serious harassment,\nintimidation, death threats and have been subject on occasion to arbitrary detention and\nattempted assassination. There are also several cases in which journalists have been killed\nin circumstances requiring further investigation."},{"id":"a-hrc-31-crp-3-p0237","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"237","seq":238,"section":"3. Findings","text":"Amongst open-source material is the account of Sirine Al-Amari, who worked as\ncorrespondent for France 24 in Tripoli. She left Libya in November 2014 after being\nrepeatedly summoned and questioned by “Islamic groups” about her reports and receiving\nseveral threats.263 In another case referred to OHCHR, on 27 August 2015, a journalist was\ndetained for several hours by an armed group in Tripoli. He was questioned about a\nmeeting he had attended in Tunisia convened by the United Nations, and threatened with\nbeing killed."},{"id":"a-hrc-31-crp-3-p0238","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"238","seq":239,"section":"3. Findings","text":"Several journalists reported intimidation, threats and even assassination attempts that\nthey had faced. In one case, a 28 year old former correspondent with a television channel\nperceived as pro-Operation Dignity, reported that he survived an assassination attempt in\nApril 2014. A car with darkened windows stopped near the taxi he had entered, and three\nbullets were fired, striking the front window of the taxi. This happened just days after he\nhad reported on two lethal attacks attributed to Ansar al-Sharia, and had described them as\na terrorist group. Prior to this, he had received several death threats either through his\ntelephone or on social media."},{"id":"a-hrc-31-crp-3-p0239","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"239","seq":240,"section":"3. Findings","text":"In April 2015, UNSMIL/OHCHR was informed by the Deputy Minister of Justice\nthat five detained persons had confessed to the killing of seven journalists in two separate\nincidents, including two Tunisian journalists, Soufiane Chourabi and Nadhir El-Ktari, who\nhad gone missing in September 2014. No evidence of the killings was provided as it was\nclaimed that the bodies were buried in an area under the control of extremist armed groups\nfrom Derna.264 OHCHR was informed that colleagues of these Tunisian journalists were\nlast able to make contact with them on 8 September 2014, four days after they were\nreportedly abducted. At the time of this last contact, they were informed that the journalists\nwere being held in Ajdabiya by an armed group responsible for guarding oil fields."},{"id":"a-hrc-31-crp-3-p0240","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"240","seq":241,"section":"3. Findings","text":"The assassination of a television journalist, who was shot dead in his office in\nBenghazi in April 2015 was referred to OHCHR. UNSMIL/OHCHR received reports\nsuggesting that this assassination was due to his reports on clashes in Benghazi, which were\nused by several satellite television channels.265 Reports were also received that in\nNovember 2014, three bloggers, Mohamed Bettou, Mohammed al-Mesamari, and Siraj\nGhatess, were found killed with their throats cut in Derna.266 OHCHR received multiple\nreports of journalists and other members of the media who have been killed in unclear\ncircumstances, sometimes after receiving threats in person or on social media, and other\ntimes for reasons that may not be related to their profession."},{"id":"a-hrc-31-crp-3-p0241","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"241","seq":242,"section":"3. Findings","text":"Premises of media stations have been raided and attacked. OHCHR received reports,\nfor instance, on the raid of radio network of Ein-Media Corporation in Benghazi in\nNovember 2014 by unknown persons. At least one staff member was summoned for\ninterrogation and detained by the Criminal Investigation Department of the Ministry of the\nInterior. The majority of staff have since fled Libya. The premises of Al-Asema TV in\nTripoli was likewise reportedly attacked twice, on 23 and 24 August 2014 by an armed\ngroup affiliated with Libya Dawn. The group had accused the station of bias in favour of\nOperation Dignity."},{"id":"a-hrc-31-crp-3-p0242","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"242","seq":243,"section":"3. Findings","text":"A journalist from Benghazi reported to OHCHR that he was working as a presenter\nwith a Benghazi television channel which was shelled, allegedly by Ansar al-Sharia, on 9\nJuly 2014. He decided to leave the city as he started receiving death threats on social media.\nHis house was looted and later burned."},{"id":"a-hrc-31-crp-3-p0243","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"243","seq":244,"section":"3. Findings","text":"Female journalists have faced particularly intense intimidation and threats - not only\nin relation to messages they broadcast, but for the very fact of being women who are vocal\nin the public sphere. Female journalists that OHCHR staff spoke with expressed their fear\nof appearing in public. Most are using pseudonyms to avoid identification and retaliation.\nThey have received harsh public criticism, directed not so much at the content of their\nmaterial, but against them as women. Some have been threatened for appearing without a\nveil. Some were also accused of “indecent appearance”, while others were told that they\nhad to stop working in the media or otherwise would face grave consequences.\nUNSMIL/OHCHR has previously reported that in February 2015, the photographs of 21\nwomen, mainly journalists, activists, and political figures, were circulated on social media\nwebpages. The photographs included inflammatory captions for their alleged support of\nOperation Dignity and for wearing “un-Islamic” attire. Several of the women featured have\nreported receiving persistent threats.267"},{"id":"a-hrc-31-crp-3-p0244","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"244","seq":245,"section":"3. Findings","text":"Journalists also continue to face the threat of legal proceedings, including criminal\nprosecution for defamation and libel, for their writings on political matters. On 17 August\n2014, Amara al-Khatabi, editor of the daily newspaper Al-Ummah, was sentenced in\nabsentia to five years in prison, fined, and banned from practicing journalism in relation to\na conviction for criminal libel. He was reportedly notified of this sentence on 17 November\n2014. He had been arrested on 19 December 2012, and charged in January 2013 with\ninsulting authorities268 after the newspaper published a list of judges and prosecutors\nalleged to be corrupt. The article had accused the persons listed of illicit earnings, accepting\nbribes, and of loyalty to Qadhafi."},{"id":"a-hrc-31-crp-3-p0245","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"245","seq":246,"section":"3. Findings","text":"In addition to increased threats to journalists owing to the conflict, OHCHR also\nnotes steps being taken by authorities to further curtail freedom of the press. On 22 January\n2014, the General National Congress passed Decree No. 5 of 2014 banning satellite\ntelevision stations critical of the Government and of the 2011 uprising.269 Law No. 5 of\n2014 amended article 195 of the Penal Code to stipulate that anyone committing an act\n“that prejudices the 17 February Revolution” shall be punished by imprisonment. 270\nArticles 290 and 291 of the Penal Code stipulate punishments, including imprisonment, for\nperceived insults to or attacks on religion. Such broad and vague language could be used to\narbitrarily curtail freedom of expression and opinion, which is contrary to international\nhuman rights law.\nI.         Migrants271"},{"id":"a-hrc-31-crp-3-p0246","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"246","seq":247,"section":"1. Introduction","text":"Whether present in Libya as migrant workers or for reasons of transit through Libya\n(e.g. seeking asylum in a third country after fleeing from persecution in their home States),\nmigrants in Libya are particularly at risk and are subject to exploitation and abuse by\nauthorities, armed groups, and private actors such as smugglers. OHCHR has received\nreports of migrants being subjected to prolonged arbitrary detention or other deprivation of\nliberty, torture and other ill-treatment, forced labour or labour exploitation, trafficking, and\nsexual abuse. Sub-Saharan Africans are especially vulnerable to abuse as a result of racial\ndiscrimination. Migrant women are also at particular risk of sexual violence."},{"id":"a-hrc-31-crp-3-p0247","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"247","seq":248,"section":"1. Introduction","text":"In the course of its investigation, OHCHR staff interviewed some 20 migrants who\nhad been subjected to human rights violations or abuses in Libya, and supplemented these\nprimary accounts with information from a range of organizations working directly in the\nfield."},{"id":"a-hrc-31-crp-3-p0248","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"248","seq":249,"section":"2. Legal framework","text":"Libya is a party to the International Convention on the Protection of the Rights of\nAll Migrant Workers and Members of Their Families. Libya is also a party to key human\nrights treaties such as ICCPR and ICESCR which apply in general to all persons within the\nterritory and under the jurisdiction of the State, regardless of nationality. Libya is not a\nsignatory to the 1951 Convention relating to the Status of Refugees, nor to its 1967\nProtocol. Libya is a party to the Organization of African Unity Convention Governing the\nSpecific Aspects of Refugee Problems in Africa."},{"id":"a-hrc-31-crp-3-p0249","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"249","seq":250,"section":"3. Findings","text":"Libya has long had a considerable population of migrant workers. It has been a\ntransit country on the migration routes from east and west Africa to Europe. As of July\n2014, UNHCR in Libya had registered more than 36,000 asylum-seekers and refugees,\nincluding Syrians, Palestinians, Iraqis and Eritreans.272 The number of migrants arriving to\nEurope from Libya has substantially increased in recent years. UNHCR estimates that\napproximately 130,000 individuals arrived in Italy from Libya between January and\nOctober 2014.273 From January to mid-October 2015, more than 140,000 migrants arrived\nin Italy by sea. The majority departed from Libya.274"},{"id":"a-hrc-31-crp-3-p0250","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"250","seq":251,"section":"3. Findings","text":"Migrants travelling by land pass through various routes through Libya. Individuals\nfrom Sudan, Ethiopia, Eritrea, and Somalia, often travel the east African route, passing\nthrough the city of Al-Kufra. Individuals from west Africa often travel through Niger, while\nthose from western Sudan and Cameroon often travel from Ndjamena, passing through\nSabha. Individuals from Syria often travel via Algeria towards the northwest coast of Libya."},{"id":"a-hrc-31-crp-3-p0251","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"251","seq":252,"section":"3. Findings","text":"One challenge in ensuring appropriate treatment of refugees in Libya is the absence\nof a legal and policy framework. Libyan law criminalizes any foreign national being\npresent in Libya without lawful authority. However, there are no clear procedures for those\ncoming into Libya irregularly to regularize their status, obtain identification documents or\nensure their protection as temporary residents,275 leaving many potentially subject to\ndetention or deportation. For those seeking asylum, there is no law dealing with the\nprocessing of refugee claims or to guarantee their rights in Libya. Reference to “asylum” in\ndomestic legislation appears in the Constitutional Declaration of the National Transitional\nCouncil from 2011.276 However, this has not yet been transposed into legislation.277\n(b)         Lack of effective control over detention facilities"},{"id":"a-hrc-31-crp-3-p0252","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"252","seq":253,"section":"3. Findings","text":"A large number of migrants are currently detained in Libya. According to UNHCR\nand IOM, as of 4 May 2015, there were at least 3,245 migrants detained in facilities in\nwestern Libya alone, including 329 women and 34 children.278"},{"id":"a-hrc-31-crp-3-p0253","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"253","seq":254,"section":"3. Findings","text":"While detention centres for migrants existed prior to the armed conflict in 2011, and\nwere managed by the Ministry of the Interior, the Department for Combatting Illegal\nMigrants was established as a separate unit within the Ministry in 2012. 279 Although\nofficial confirmation has not been possible to obtain, a number of credible sources referred\nto administration by the Department for Combatting Illegal Migrants of some 19 facilities\nacross the country, with a particular concentration in the west. International organizations\nand monitoring groups have faced challenges in accessing the centres as a result of the\nsecurity situation, such that OHCHR was unable to confirm which facilities remain\noperational and which are closed. Since its establishment, the control of the Department for\n272 UNHCR, UNHCR position on returns to Libya – update 1, October 2015, p. 11. This paper notes that\na more recent figure was not available owing to the lack of access of UNHCR to Libya and\nverification.\n273 UNHCR, UNHCR position on returns to Libya, November 2014, p. 4.\n274 UNHCR, UNHCR position on returns to Libya – update 1, October 2015, p. 13.\n275 MHub, IOM, Detained Youth: the Fate of Young Migrants, Asylum Seekers and Refugees in Libya\nToday, July 2015, p. 41.\n276\nIbid, p. 45.\n277\nUNHCR, UNHCR position on returns to Libya – update 1, October 2015, p. 11.\n278 UNSMIL, The situation of migrants in transit through Libya en route to Europe, Briefing Note, May\n2015. Under international human rights law the detention of children is to be used only as a measure\nof last resort and for the shortest appropriate period of time: CRC, art. 37(b).\n279 Global Detention Project, Libya Detention Profile, Feb 2015; also for terms of reference of the\nDepartment for Combatting Illegal Migrants see MHub, IOM, Detained Youth: the Fate of Young\nMigrants, Asylum Seekers and Refugees in Libya Today, July 2015, p. 78.\nCombatting Illegal Migrants over the detention facilities has itself been interrupted. In\n2012, officials acknowledged to Amnesty International that “they had little involvement in\nthe arrest and detention of migrants and that the Ministry of Interior has oversight over\ndetention centres for migrants, but said that since the [2011] conflict the Ministry had had\nno capacity or resources to continue doing so”.280"},{"id":"a-hrc-31-crp-3-p0254","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"254","seq":255,"section":"3. Findings","text":"In 2013, the Department for Combatting Illegal Migrants regained control of some\nof the detention facilities that had been taken over by armed groups in 2011. 281 Yet in 2014,\na number of the facilities were closed, in particular in southern Libya, owing to the\noutbreak of violence and the lack of funding from the central government. 282 It was\nreported to OHCHR that many detention facilities of the Department are guarded by armed\ngroups."},{"id":"a-hrc-31-crp-3-p0255","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"255","seq":256,"section":"3. Findings","text":"In parallel to the facilities of the Department for Combatting Illegal Migrants, are a\nnumber of unofficial or ad hoc detention facilities, controlled by various armed groups.\nAlthough OHCHR was informed of two additional unofficial detention facilities for\nmigrants, the precise number is uncertain as these facilities are not declared."},{"id":"a-hrc-31-crp-3-p0256","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"256","seq":257,"section":"3. Findings","text":"In the course of this investigation, OHCHR was not been able to access migrant\ndetention facilities inside Libya. Nor was it considered possible to speak with migrants who\nremained in Libya given their vulnerability. The focus has thus been on collecting first-\nhand accounts from individuals now residing outside Libya. Those individuals have shared\ntheir experiences in particular about their detention and treatment in the vicinity of Tripoli\nin the west, and Sabha in the south, during 2014 and 2015. The findings of OHCHR are\nconsistent with the violations and abuses highlighted in previous UNSMIL/OHCHR reports\nand the reports of other organizations including IOM.283"},{"id":"a-hrc-31-crp-3-p0257","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"257","seq":258,"section":"3. Findings","text":"In many cases, particularly involving non-Arabic speaking individuals, those who\nhad been detained did not know the precise location of the facility in which they had been\ndetained, or whether it was an official facility of the Department for Combatting Illegal\nMigrants or an informal facility. What appears to be common however is that migrants are\nfrequently held arbitrarily, without access to due process and fair trial guarantees, and are\nsubject to a wide range of other human rights violations and abuses. The duration of\ndeprivation of liberty is indefinite, and there is a complete lack of judicial or other\nindependent oversight or access to legal assistance."},{"id":"a-hrc-31-crp-3-p0258","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"258","seq":259,"section":"3. Findings","text":"In many cases, release is obtained by either being extorted to pay a “fee”, paying a\nbribe, or being freed by someone who will pay the appropriate sum. Many persons\ninterviewed who had been detained or otherwise deprived of their liberty stated that they\nwere requested to call family members to ask them to transfer money to secure their\nrelease. According to a man who was detained in Sabha,284 “they came to us every day.\nThey would beat those who would not make the call”. After spending a month in detention,\nhe was released once payment had been made. He said others remained in detention for up\nto nine months, unable to pay the sum requested. OHCHR staff spoke to other former\ndetainees who were forced to undertake unpaid labour in exchange for their release."},{"id":"a-hrc-31-crp-3-p0259","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"259","seq":260,"section":"3. Findings","text":"Migrants held in detention do not have any real access to judicial process or\nguarantees. Monitoring systems either do not exist or are insufficient. Thus there is no\noversight in relation to the uncontrolled discretion of the guards, or the commission of\nviolations and abuses.\n(c)     Conditions of detention"},{"id":"a-hrc-31-crp-3-p0260","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"260","seq":261,"section":"3. Findings","text":"Conditions of detention are inadequate, and feature chronic overcrowding, poor\nsanitation, insufficient access to healthcare, and inadequate quantity and quality of food.285\nA Somali man who had been held for two months in a detention centre near Tripoli in early\n2015 said: “the detention room was very dirty, and we slept on the floor without any\ncovers. Everyone was itching and had a skin disease”. An Eritrean man, who was held in\nSouk Al-Ahad detention facility286 in May 2015, reported the same conditions: “it was too\nhot, and we were getting very little food. People were falling sick, but there was no medical\ncare”. An Eritrean man held in an informal detention location in Bani Walid mid-2015 said\nthat individuals were suffocating as a result of the overcrowding and absence of ventilation.\nThe guards eventually broke an opening in the ceiling to provide some air."},{"id":"a-hrc-31-crp-3-p0261","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"261","seq":262,"section":"3. Findings","text":"Reports received by OHCHR suggest that ill-treatment at the hands of detention\nguards (sometimes amounting to torture) is widespread. A Somali woman recounted the\nbeating she suffered in detention: “They counted us every day. If I could not stand fast\nenough, they would beat me. My left arm was injured and hurt because of the beating”.\nChildren are also detained and not necessarily separated from adults. A former detainee\nwho at the age of 17 was held in a facility in Sabha in 2014, described the physical abuse he\nsuffered and witnessed:\n“Men in Khaki uniforms came and took us out of our rooms, forced some of us to\ntake our clothes off, and beat us. They would throw water on us when we lose\n[consciousness]”."},{"id":"a-hrc-31-crp-3-p0262","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"262","seq":263,"section":"3. Findings","text":"A Nigerian man who was held in a detention centre in Gheryan in early 2014 also\ndescribed severe ill-treatment of detainees and an unlawful killing at the centre:\n“There was lots of beating. If the guards open the door, and the detainees do not\nmove fast, the guards would flog them with a chain. Once, a man – I think he was\nEthiopian – spilled his soup. One of the guards took out a gun and shot him dead in\nfront of me. After this incident, I decided I must escape”.\n(d)         Abuses by smugglers"},{"id":"a-hrc-31-crp-3-p0263","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"263","seq":264,"section":"3. Findings","text":"Migrants arriving from the south are particularly vulnerable as they make their way\nthrough the desert en route to northern Libya. During this phase of their trip, migrants are\noften subject to ill-treatment and extortion of payment in exchange for freedom by abusive\nsmugglers, criminals, and armed groups at checkpoints. OHCHR received reports of the use\nof houses or other places (such as warehouses) by smugglers to hold individuals, depriving\nthem of their liberty."},{"id":"a-hrc-31-crp-3-p0264","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"264","seq":265,"section":"3. Findings","text":"Migrants are treated differently according to race and religion. It was frequently\nreported that sub-Saharan Africans suffer racism in Libya, and that Christians face ill-\ntreatment on the basis of their religion. Some migrants interviewed said that they were\nadvised by their employer not to disclose their Christian faiths to ensure their safety. Others\nsaid that smugglers (as well as criminals and armed groups) harassed them whenever it was\nknown that they were Christians."},{"id":"a-hrc-31-crp-3-p0265","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"265","seq":266,"section":"3. Findings","text":"In preparation for their departure via the sea to Europe, smugglers hold migrants in\nhouses close to the coastal departure points. They are typically kept in these locations for\nweeks, and are not allowed to leave. Several of those interviewed reported ill-treatment,\nbeatings, and shortages of food while they were held in these houses.\n(e)         Labour-related violations"},{"id":"a-hrc-31-crp-3-p0266","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"266","seq":267,"section":"3. Findings","text":"Irregular migrants, who are generally paid a lower wage than average, are absorbed\ninto the black market economy. In the absence of legal protection, even when a payment is\nagreed upon, employers may decide not to pay migrants after completion of their task, and\nmight turn them over to detention facilities on the basis of their irregular status, to avoid\npaying the agreed sum."},{"id":"a-hrc-31-crp-3-p0267","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"267","seq":268,"section":"3. Findings","text":"Furthermore, unpaid labour in exchange for release from detention, facilitation of\ntravel, or promises of protection by an employer is common place. A Nigerian man who\nwas held captive in mid-2014 by a commander of an armed group based near Tripoli\nairport, said the commander had promised to release him once he had completed a task on a\nconstruction site. Upon seeing the significant extent of the task, his co-workers helped him\nescape.\n(f)         Sexual violence"},{"id":"a-hrc-31-crp-3-p0268","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"268","seq":269,"section":"3. Findings","text":"OHCHR received credible reports with regard to the commission of sexual violence,\nincluding rape, against women in migrant detention facilities by guards, as well as by non-\nState actors such as smugglers and traffickers more broadly. According to reports received,\nsexual violence, occurring inside or outside of detention, was inflicted on both women and\ngirls. The investigation is aware of reports, for instance, in relation to allegations of the rape\nof women in centres in Sabha, ‘Ain Zara, and Abu Salim.287\n(g)         Difficulties in leaving Libya"},{"id":"a-hrc-31-crp-3-p0269","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"269","seq":270,"section":"3. Findings","text":"Many migrants have sought to flee the violence by crossing the borders into\nneighbouring countries, some of which have intermittently imposed strict restrictions on\nentry. Others, including women, children, and older persons, have sought to leave by sea\nroutes. The cities of Zuwara, Misrata, Sabratha, Garabulli, and Al-Khoms are points of\ndeparture for migrants traveling to Europe by sea."},{"id":"a-hrc-31-crp-3-p0270","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"270","seq":271,"section":"3. Findings","text":"Smugglers organise the travel of migrants to Europe by sea. Many journeys involve\nembarking on dangerously crowded and ill-equipped boats. Seeing the conditions of these\nboats, some have refused to embark, and were then met with violence by the smugglers.\nOne witness traveling on this route in July 2014 reported that he saw five passengers killed\nby smugglers when they refused to board."},{"id":"a-hrc-31-crp-3-p0271","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"271","seq":272,"section":"3. Findings","text":"Thousands have died at sea. IOM has reported that 3,770 individuals died in 2015\nattempting to cross the Mediterranean.288 Amongst the causes of death is suffocation owing\nto conditions on board. A Sudanese woman who took the boat from Zuwara to Italy in\nAugust 2015 informed OHCHR that 35 individuals, forced to sit in a room on the lower\ndeck with no ventilation, had perished on her boat."},{"id":"a-hrc-31-crp-3-p0272","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"272","seq":273,"section":"1. Introduction","text":"In addition to the difficulties internally displaced persons generally encounter in\nenjoying their rights, groups perceived as having supported the Qadhafi regime during 2011\nare at particular ongoing risk. OHCHR has received particular complaints of violations and\nabuses from members of the Tawergha community whose experience of mass displacement\ngoes back to August 2011. While 2015 has seen considerable progress in relation to the\nUNSMIL facilitated dialogue between the Misratan and Tawerghan communities to allow\nfor safe returns, OHCHR received reports of significant challenges faced by this group\nduring the 2014 and 2015 reporting period. Among these challenges were the adverse\nimpact on livelihoods, ongoing discrimination on the basis of their identity, and a\nheightened risk of detention and ill-treatment, especially by Misrata-based armed groups."},{"id":"a-hrc-31-crp-3-p0273","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"273","seq":274,"section":"2. Legal framework","text":"Internally displaced persons are entitled to enjoy all the human rights protected\nunder international law. Similarly, under international humanitarian law, they enjoy the\nsame rights as other persons taking no active part in the hostilities. The Guiding Principles\non Internal Displacement bring together and provide clarification of relevant standards.\nAmong the economic, social, cultural, civil, and political rights displaced persons retain are\nthe right to basic humanitarian assistance (such as food, medicine, shelter), the right to life,\nliberty and security, the right to education, the right to an adequate standard of living,\nfreedom of movement and residence, political rights such as the right to participate in\npublic affairs and the right to participate in economic activities.289 Property of displaced\npersons is protected from, for example, pillage, destruction or arbitrary acts of illegal\nappropriation. Authorities are obliged to establish the conditions and means allowing\ndisplaced persons voluntary, dignified and safe return, resettlement or local integration,\nincluding providing help in recovering lost property and possessions. When restitution is\nnot possible, the Guiding Principles call for compensation or just reparation.290"},{"id":"a-hrc-31-crp-3-p0274","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"274","seq":275,"section":"3. Findings","text":"Following the attack of Misrata-based armed groups on the town of Tawergha in\nAugust 2011, the town’s population (estimated at 42,600) was displaced to various other\nlocations in Libya or fled abroad. The Commission of Inquiry on Libya documented acts of\nmurder, torture, and cruel treatment of Tawerghans by Misrata-based armed groups. In\nlarge part, this was seen as retaliatory action for the community’s perceived support for the\nQadhafi regime, and grave human rights abuses allegedly committed by some Tawerghans\nduring the armed conflict. It may also have been fuelled by widespread discrimination\nagainst dark-skinned Libyans.291 The town of Tawergha was subsequently destroyed, and\nTawerghans have not been able to return to the town since then.292 Thousands of\nTawerghans are said to be scattered across the country, with estimates of some 15,000 in\nthe eastern region, and thousands of others displaced in the western and southern regions.\nDisplaced Tawerghans have been subject to re-displacement owing to ongoing armed\nfighting across the country. For example, on 17 October 2014, residents of the Gar Younes\ncamp for the displaced were evacuated, re-displacing some 2,500 Tawerghans who sought\ntemporary shelter elsewhere. More than 5,600 Tawerghans have been re-displaced from\nfive camps in Benghazi since mid-October.293"},{"id":"a-hrc-31-crp-3-p0275","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"275","seq":276,"section":"3. Findings","text":"OHCHR staff were told of the dire humanitarian situation facing many who are\ndisplaced. In Benghazi, hundreds of Tawerghans are sheltering in schools, with limited\nprivacy, access to running water, and to sanitation. Similar reports were received about\nTawerghans displaced in the south of Libya. Some have fled the country and report ongoing\nfinancial hardship."},{"id":"a-hrc-31-crp-3-p0276","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"276","seq":277,"section":"3. Findings","text":"Specific actions are said to have exacerbated their difficulties, such as the alleged\nconfiscation by Misrata-based armed groups of academic documents of Tawerghan\nstudents, which has made it difficult for them to enrol into universities elsewhere. Reports\nhave also been received that Tawerghan students are discriminated against by being denied\neducational grants to study overseas, as well as not receiving financial support for medical\ncare overseas on a basis that is consistent with what is provided for members of other\nLibyan communities."},{"id":"a-hrc-31-crp-3-p0277","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"277","seq":278,"section":"3. Findings","text":"Access to adequate healthcare was raised by a number of Tawerghans as a matter of\nparticular concern. For those in camps for internally displaced persons, access to health\nfacilities outside of camps is limited owing to security risks, including the possibility of\narbitrary arrest discussed below. Fear was also expressed of discriminatory practices by\ndoctors and nurses working in some clinics and hospitals. Those raising concerns about the\ntreatment of Tawerghans have faced reprisals. A Tawerghan man reported that he was fired\nfrom his workplace at a Government ministry in connection with his critical views on the\npractices of Misratans against Tawerghans. He noted that his supervisor was from Misrata."},{"id":"a-hrc-31-crp-3-p0278","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"278","seq":279,"section":"3. Findings","text":"Several Tawerghans reported a heightened risk of being arrested or apprehended and\ndetained on the basis of their identity. Many Tawerghans are held in detention facilities by\nMisratan armed groups, even if the facilities are nominally under State control.294 Some of\nthese facilities are formal and public; others are secret. The Tawerghan/Misratan Joint\nCommittee informed UNSMIL that some 1,000 Tawerghans are held in detention facilities\nrun by Misratan armed groups.295 OHCHR has received reports that detained Tawerghans\nhave faced torture and other forms of ill-treatment, in some cases leading to death. One case\ndocumented by OHCHR concerned a 34 year old Tawerghan man from Benghazi who was\narrested at a checkpoint erected at the entry of Misrata and taken to Al-Saket Prison. He\nwas held incommunicado for some three months there. In early 2014, his family was\ninformed through an intermediary (who had received a call from an employee at the prison)\nthat the man had been shot dead in prison in the early morning of that day. Later inquiries\nsuggested that the man had been transferred to another prison, and after arrival, was beaten.\nThe victim sought to defend himself, and was shot dead in the resulting affray."},{"id":"a-hrc-31-crp-3-p0279","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"279","seq":280,"section":"1. Introduction","text":"The ongoing armed conflict has had a major impact on children’s enjoyment of their\nrights in Libya: including their rights to life, to an adequate standard of living, to the\nhighest attainable standard of health, to education and to protection of the family. Some of\nthe impacts are noted in previous Sections of this Chapter, for example, in relation to\nindiscriminate attacks causing the death or injury of children, attempted abductions, the\nbombardment of houses, and the impact of the reduction of health care facilities. This\nSection describes findings in relation to two particular case-studies: the first is children’s\naccess to education and the second is use of children in hostilities. As well as being exposed\nto the threats posed by armed conflict, children in Libya continue to face significant\nchallenges in enjoying their basic rights, and in some cases are exposed to extreme\nexploitation and abuse, including sexual violence and forcible recruitment into groups\npledging allegiance to ISIL."},{"id":"a-hrc-31-crp-3-p0280","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"280","seq":281,"section":"2. Legal framework","text":"Libya is a party to the Convention on the Rights of the Child (CRC), which outlines\na range of rights for children, including with respect to their education, health, and\ndevelopment. In the specific context of armed conflict, States are required under CRC to\ntake all feasible measures to ensure protection and care of children who are affected by an\narmed conflict.296 Libya has also acceded to the Optional Protocol to CRC on the\ninvolvement of children in armed conflict, thus accepting the prohibition on the recruitment\nor use of children in hostilities under 18 years of age by non-State armed groups and the\nobligation to take all feasible steps to prevent such recruitment or use in hostilities. 297 States\nare obliged to take all feasible measures to ensure that members of armed forces aged under\n18 do not take a direct part in hostilities.298 State parties are to ensure that persons under 18\nfacility (under the control of the Supreme Security Committee affiliated with Libya Dawn). All are\nreportedly located in Misrata. OHCHR further received information that both Al-Wahda and Internal\nSecurity Prisons are no longer operating. In terms of secret detention facilities, references were made\nto three detention facilities; one controlled by Awlad Eissa Brigade, the second a pasta factory which\nwas turned into a secret detention facility; and the third a residential building turned into a detention\nfacility. All are reportedly located in Misrata, and controlled by Misrata-based armed groups.\nyears are not compulsorily recruited into their armed forces, and by virtue of its binding\ndeclaration deposited at the time of accession, Libya has recognized 18 years as the\nminimum age for voluntary recruitment into its armed forces. Under international\nhumanitarian law, all parties to a non-international armed conflict are obliged to provide\nchildren with the care and aid they require. 299 International criminal law recognises as a war\ncrime conscripting or enlisting children under the age of 15 years of age into armed forces\nor groups or using them to participate actively in hostilities.300"},{"id":"a-hrc-31-crp-3-p0281","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"281","seq":282,"section":"3. Findings","text":"Children’s access to education has been severely compromised by the conflict in\nLibya in 2014 and 2015. Numerous schools have been destroyed or damaged as a result of\nshelling and airstrikes. In many areas where schools remain standing and are still\noperating,301 parents report that they refrain from sending their children to school out of\nfear of injury to them during attacks."},{"id":"a-hrc-31-crp-3-p0282","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"282","seq":283,"section":"3. Findings","text":"In some areas controlled by Ansar al-Sharia (e.g. on the outskirts of Derna), parents\ndescribed being afraid to send their girls to school out of fear of abductions. Reports from\nSirte and other areas controlled by groups pledging allegiance to ISIL, indicate that girls are\nno longer allowed to go to schools or are only permitted if wearing a full face veil. OHCHR\nhas also received accounts of girls who were attacked and harassed by armed groups on\ntheir way to school in Tripoli.\n(b)         Recruitment of children and use in hostilities"},{"id":"a-hrc-31-crp-3-p0283","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"283","seq":284,"section":"3. Findings","text":"OHCHR encountered challenges in gathering information on the recruitment and use\nof children in hostilities given limited access and the limited monitoring currently being\nundertaken in Libya. 302 Other organizations have reported that children have been recruited\ninto armed groups.303 In terms of information obtained from first-hand accounts, OHCHR\nreceived specific information on the forced recruitment and use of children by groups\npledging allegiance to ISIL. OHCHR staff interviewed two boys of 10 and 14 years of age,\nwho had been forcibly taken from their families and transferred to the locations of these\ngroups. The children were forced to receive religious and military training. They underwent\nmilitary training that lasted from two to four weeks and included how to use and load guns\nand different weapons and how to aim and shoot at targets using live ammunition which\ncontinued until they were able to do so competently. They were also forced to watch videos\nof beheadings. A grand Imam in the “madrassa” within the camp taught them to recite the\nQuran and explained to them that “killing infidels is [their] gateway to heaven”."},{"id":"a-hrc-31-crp-3-p0284","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"284","seq":285,"section":"3. Findings","text":"According to the accounts received, these children were subjected to sexual abuse.\nOne of them was “attached in service” to a foreign fighter. He was responsible for cleaning\nthe fighter’s clothes and delivering food. He reported that most evenings “I knew what I\nhad to do, I had to take my clothes off and turn around and bend over facing the wall”. The\nother boy recounted how he was raped by several of the fighters in order to “break me so\nthat I will never say no”, in addition to being repeatedly raped with objects."},{"id":"a-hrc-31-crp-3-p0285","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"285","seq":286,"section":"3. Findings","text":"OHCHR also investigated a case in which a child was used to detonate a bomb in a\nvehicle by groups pledging allegiance to ISIL during clashes with the Derna Mujahideen\nShura Council in June 2015."},{"id":"a-hrc-31-crp-3-p0286","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"286","seq":287,"section":"3. Findings","text":"Rather than resiling from the recruitment of children, groups pledging allegiance to\nISIL appear to celebrate the practice. According to a press report on 4 December 2015, the\n“Islamic State… in… Sirte” celebrated the “graduation” of 85 boys all below the age of 16,\ndescribing them as the “Khilapha [Caliphate] Cubs”.304 They were trained in conducting\nsuicide attacks, using weapons, and booby-trapping. During the event, the young boys were\ndressed in army uniforms and were paraded. The event was announced through the local\nradio station and residents of Sirte were invited to attend. This incident appears to follow\nthe example set by ISIL elsewhere, as evidenced in the publications of ISIL promoting the\nrecruitment of children into the ranks of ISIL. In the March 2015 DABIQ magazine, for\ninstance, the group had a special article featuring child soldiers in Iraq and Syria calling\nthem “The Lion Cubs of the Khilapha”.305"},{"id":"a-hrc-31-crp-3-p0287","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"287","seq":288,"section":"VI. Overall findings","text":"On the basis of the information collected and analysed, there are reasonable grounds\nto conclude that there were widespread violations of international human rights law and\ninternational humanitarian law, and abuses of human rights in Libya throughout 2014 and\n2015. These acts, which were committed by all parties to the conflict in Libya include those\nset out below."},{"id":"a-hrc-31-crp-3-p0288","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"288","seq":289,"section":"1. Unlawful killings and executions","text":"Most major groupings of armed actors have carried out unlawful killings, in\nparticular executions of individuals taken captive or detained, and the assassination of those\nvoicing dissent."},{"id":"a-hrc-31-crp-3-p0289","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"289","seq":290,"section":"1. Unlawful killings and executions","text":"Forces aligned with Operation Dignity have executed some individuals alleged to be\nmembers or supporters of Ansar al-Sharia after their arrest or capture. Some fighters who\nsurrendered have faced a similar fate. OHCHR received reports of similar executions\ncarried by armed groups affiliated with Libya Dawn, but could not verify them owing to the\nlimitations to access and information."},{"id":"a-hrc-31-crp-3-p0290","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"290","seq":291,"section":"1. Unlawful killings and executions","text":"The assassination of perceived opponents to those exercising power have been\nfrequent, particularly in Benghazi. In most cases the assassinations were attributed by\ninterviewees to Ansar al-Sharia. Those targeted included political figures, human rights\ndefenders, journalists, judicial actors, religious leaders, and alleged Qadhafi supporters"},{"id":"a-hrc-31-crp-3-p0291","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"291","seq":292,"section":"1. Unlawful killings and executions","text":"Groups pledging allegiance to ISIL have engaged in the public execution of civilians\nand others taking no active part in hostilities, in particular those placed hors de combat,\nmainly in Sirte and Derna, though also in other areas."},{"id":"a-hrc-31-crp-3-p0292","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"292","seq":293,"section":"1. Unlawful killings and executions","text":"Unlawful killings have also taken place in the south, including the shooting of\nindividuals defending their homes from raids or appropriation by rival tribal armed groups."},{"id":"a-hrc-31-crp-3-p0293","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"293","seq":294,"section":"2. Attacks on civilians and civilian objects, and other protected persons and objects","text":"Many attacks during the armed conflict in Libya in 2014 and 2015 appear to have\nbeen indiscriminate in nature, impacting in particular on highly populated residential areas,\nincluding in Benghazi, Tripoli, Warshafana, the Nafusa Mountains area, and in the south of\nLibya. Sufficient precautions were not taken to protect civilians. Heavy weaponry such as\nGrad rockets, which are not appropriate for use in highly populated residential areas given\nthat they cannot be targeted with sufficient precision, have been employed. OHCHR was\nunable to determine the parties responsible for many specific attacks owing to the\nlimitations to access and information, and the similarity of the weapons being employed by\nthe parties to the conflict in Libya. OHCHR did however receive reports of indiscriminate\nattacks in all conflict areas."},{"id":"a-hrc-31-crp-3-p0294","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"294","seq":295,"section":"2. Attacks on civilians and civilian objects, and other protected persons and objects","text":"Attacks by armed groups have been directed against or otherwise had an impact on\npersons and objects given protection under international humanitarian law, including health\nfacilities, ambulances and medical workers, and humanitarian workers. Humanitarian\nworkers have been abducted or held hostage by armed groups."},{"id":"a-hrc-31-crp-3-p0295","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"295","seq":296,"section":"2. Attacks on civilians and civilian objects, and other protected persons and objects","text":"Armed groups affiliated with Operation Dignity and those affiliated with Libya\nDawn have deliberately destroyed and looted private property. Groups pledging allegiance\nto ISIL have also appropriated and destroyed private property when targeting perceived\nadversaries."},{"id":"a-hrc-31-crp-3-p0296","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"296","seq":297,"section":"3. Arbitrary detention, abductions and disappearances","text":"Many individuals have been arbitrarily detained in Libya in 2014 and 2015, and held\nin facilities operated by the State and/or armed groups. Frequently, persons are arrested\nwithout charge. Some who were detained were unaware of the reason for their arrest or\ndetention. Detainees are regularly deprived of the rights of due process and other rights,\nsuch as contact with their families or legal counsel."},{"id":"a-hrc-31-crp-3-p0297","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"297","seq":298,"section":"3. Arbitrary detention, abductions and disappearances","text":"Given the limited functioning of courts, there is little recourse to judicial review to\nchallenge the legality of detentions. Even when recourse is available, court orders for\nrelease have not always been effective."},{"id":"a-hrc-31-crp-3-p0298","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"298","seq":299,"section":"3. Arbitrary detention, abductions and disappearances","text":"Individuals have been abducted for potential ransom or prisoner exchange. State\nforces and armed groups have also been responsible for a number of disappearances,\nincluding enforced disappearances, following the launch of Operation Dignity and Libya\nDawn."},{"id":"a-hrc-31-crp-3-p0299","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"299","seq":300,"section":"4. Torture and other ill-treatment","text":"Numerous alleged cases of torture and other forms of cruel, inhuman or degrading\ntreatment have taken place, particularly of individuals in detention facilities controlled by\nthe State and/or armed groups. Detainees have suffered severe beatings with plastic pipes or\nelectrical cables, prolonged suspension in stress positions, solitary confinement, being held\nincommunicado, and electrocution. Some of the facilities where torture has been reported,\nincluding where torture has resulted in the death of detainees, have been listed in Chapter\nV, Section D on torture and other ill-treatment. Many detainees were also deprived of\nadequate food or water, and were subjected to threats of a sexual nature, and extortion of\npayment in exchange for freedom. OHCHR also observed a lack of redress for numerous\nalleged cases of torture and other ill-treatment."},{"id":"a-hrc-31-crp-3-p0300","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"300","seq":301,"section":"5. Gender-based violence and discrimination against women","text":"There has been a series of attacks by armed groups against women. High-profile\nwomen activists promoting equality, social justice, and accountability in Libya have been\nassassinated. Such assassinations, along with other assaults, harassment and threats appear\ndesigned to send a broader message that women should not be vocal in the public sphere.\nMembers of armed groups have committed sexual and gender-based violence, with\nOHCHR documenting cases against women, girls and boys. Further investigation is\nwarranted on this topic in light of the difficulty in gathering information"},{"id":"a-hrc-31-crp-3-p0301","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"301","seq":302,"section":"5. Gender-based violence and discrimination against women","text":"In several parts of Libya, women’s ability to exercise fundamental rights and\nfreedoms such as freedom of movement and the right to work has been restricted by the\nrequirement that they be accompanied by a “male guardian”. This was particularly the case\nin areas controlled by Ansar al-Sharia and groups pledging allegiance to ISIL, but\nrestrictions were also reported by women in Tripoli seeking access to civil services such as\nobtaining identification documents. Women have faced barriers in accessing justice arising\nout of their fear of retaliation by armed groups controlling relevant facilities and territories,\nin particular when reporting crimes committed by these groups."},{"id":"a-hrc-31-crp-3-p0302","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"302","seq":303,"section":"6. Economic, social and cultural rights","text":"Enjoyment of economic, social and cultural rights, including healthcare, food, and\neducation has declined in Libya in 2014 and 2015. Women, internally displaced persons,\nchildren, and migrants have been particularly affected. Access to healthcare has been\ncompromised by the ongoing conflict, including attacks on or impacting health facilities\nand workers, and the departure of many foreign medical personnel owing to the violence.\nHowever, it has also been impacted by the Government’s limited investment in\ninfrastructure, and programme delivery budget cuts. Access to education has been\nsignificantly curtailed, in particular in the east. Many schools have been either damaged,\ndestroyed, occupied by internally displaced persons, converted into military or detention\nfacilities, or are otherwise dangerous to reach. Children residing in camps for internally\ndisplaced persons, as well as children with disabilities have experienced particular\ndifficulties in accessing education. Food prices have increased as supply routes have been\ninterrupted, but access to food has also been affected by the Government decision to reduce\nor cut food subsidies in November 2015. Access to safe drinking water, sanitation, and\nhygiene has reduced as a result of the conflict, including on occasion, the deliberate action\nof armed groups."},{"id":"a-hrc-31-crp-3-p0303","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"303","seq":304,"section":"7. Administration of justice","text":"Judicial actors, in particular judges and prosecutors, have been subjected to killings,\ncourt bomb attacks, assaults, and abductions. Some attacks have been linked to the\ndetention or release of certain individuals, or to thwart the arrest and prosecution of\nmembers of armed groups. As a result of such attacks, many courts stopped functioning.\nOwing to the collapse of the criminal justice system in many parts of Libya, victims of\nhuman rights violations and abuses have little recourse to seek protection, or to an effective\nremedy. Thousands of “conflict-related detainees” remain in detention without having had\ntheir cases properly examined to determine if sufficient evidence exists for them to be\ncharged or released."},{"id":"a-hrc-31-crp-3-p0304","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"304","seq":305,"section":"8. Human rights defenders and journalists","text":"Human rights defenders and journalists have been subjected to intimidation and\nattacks, including assassinations, particularly in Benghazi and Tripoli, and particularly by\nAnsar al-Sharia and armed groups affiliated with Libya Dawn. These attacks have forced\nmany to go into hiding or to flee, and threaten to silence independent voices. Many attacks\nhave targeted high-profile activists, producing a chilling effect limiting the work of other\nhuman rights defenders. The national human rights institution of Libya, the National\nCouncil of Civil Liberties and Human Rights, has been subjected to attacks and\nintimidation, reducing it to a minimal level of functioning. Journalists have also faced\nharassment and threats, with some subjected to arbitrary detention and attempted\nassassination. Journalists have also faced criminal prosecution for defamation and libel for\ntheir reporting on political matters."},{"id":"a-hrc-31-crp-3-p0305","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"305","seq":306,"section":"9. Migrants","text":"A large number of migrants are currently detained in Libya in facilities operated by\nthe Department for Combatting Illegal Migrants of the Ministry of the Interior, or armed\ngroups, without access to judicial review of their cases. Others are deprived of their liberty\nby smugglers. The conditions in which persons are detained or deprived of their liberty are\ninadequate, with chronic overcrowding, poor sanitation and healthcare, insufficient food,\nand the commission of torture and other forms of ill-treatment. Migrant women have been\nsubjected to sexual and gender-based violence both in and outside of the context of\ndetention facilities. Migrants are subject to being exploited within the labour sector. Those\ndeprived of liberty are subject to extortion of payment in exchange for freedom. Journeys\nacross the Mediterranean often involve dangerously overcrowded and ill-equipped boats,\nresulting in many deaths. In addition to drowning, migrants have also suffocated as a result\nof conditions on board."},{"id":"a-hrc-31-crp-3-p0306","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"306","seq":307,"section":"10. Tawerghan community","text":"Members of the Tawerghan community, internally displaced since 2011, have faced\nparticular difficulties in relation to reduced livelihoods, ethnic discrimination, and limited\naccess to education and health services. They have also reported arbitrary detention and ill-\ntreatment, especially by Misrata-based armed groups. Dialogue between Misrata and\nTawerghan communities on safe returns and reparations is now taking place."},{"id":"a-hrc-31-crp-3-p0307","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"307","seq":308,"section":"11. Children","text":"Children in Libya have faced significant challenges to the enjoyment of their rights,\nincluding education. The issues limiting girls’ access to education are particularly\npronounced - especially in areas controlled by Ansar al-Sharia and groups pledging\nallegiance to ISIL. Difficulties have also been encountered in Tripoli. Groups pledging\nallegiance to ISIL have forcibly recruited and used children in hostilities, and in some\ncases, subjected them to sexual abuse."},{"id":"a-hrc-31-crp-3-p0308","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"308","seq":309,"section":"12. Concluding observations","text":"Violations and abuses have not been limited to one area of Libya or to one actor;\nOHCHR documented such acts having also been perpetrated by State actors and armed\ngroups, some of which affiliated with Libya Dawn or Operation Dignity. Other groups may\nbe acting independently. Some actors were named with particular frequency during the\ninvestigation as being responsible for violations and abuses, including Operation Dignity\nforces and armed groups, such as the Al-Sai’qa Brigades of the Libyan National Army, and\nAwliaa al-Damm; armed groups affiliated with Libya Dawn; Ansar al-Sharia; groups\npledging allegiance to ISIL; and tribal armed groups in the south. Allegations were\nnonetheless not limited to these particular groups; other non-State actors, such as\nsmugglers, also committed human rights abuses."},{"id":"a-hrc-31-crp-3-p0309","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"309","seq":310,"section":"12. Concluding observations","text":"There appears to be no effective oversight or accountability in relation to the\ncommission of violations and abuses in Libya. No party to the conflict appears to have been\nexercising its responsibilities to address violations or abuses, nor have State authorities\nexercised their responsibilities to provide effective remedies to victims, to prevent future\nviolations or abuses, and to ensure non-repetition."},{"id":"a-hrc-31-crp-3-p0310","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"310","seq":311,"section":"12. Concluding observations","text":"Many of the violations and abuses documented may amount to war crimes and other\ncrimes under international law. With regard to war crimes, they included: subjecting\npersons taking no active part in hostilities to violence to life and person (including murder,\nmutilation, cruel treatment and torture); the taking of hostages; executions without any prior\npronouncement of a judgment by a regularly constituted court; directing attacks against the\ncivilian population; directing attacks against buildings, medical units and transport and\npersonnel bearing the distinct emblems of the Geneva Convention; intentionally directing\nattacks against humanitarian personnel; pillaging; rape and other forms of sexual violence;\nthe conscription or enlistment of children under the age of 15 years or using them to\nparticipate actively in hostilities; and destroying or seizing the property of an adversary."},{"id":"a-hrc-31-crp-3-p0311","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"311","seq":312,"section":"12. Concluding observations","text":"The aforementioned acts should be immediately and fully investigated as part of a\ncomprehensive criminal investigation, and those responsible should be brought to justice."},{"id":"a-hrc-31-crp-3-p0312","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"312","seq":313,"section":"1. Assessment of the justice sector","text":"The justice system has been significantly compromised by the security situation and\nstructural weaknesses. Section G on administration of justice in Chapter V of this present\nreport described the specific threats facing judicial actors presently, including\nassassinations, bomb attacks and threats which have caused courts in many areas to cease\nfunctioning. Ending these threats and ensuring an adequate protection system is in place is\nof the utmost importance. Equally, there is a need to continue the process of reforming and\nstrengthening the justice system. Both political will and significant national and\ninternational resources will be required to support this work."},{"id":"a-hrc-31-crp-3-p0313","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"313","seq":314,"section":"1. Assessment of the justice sector","text":"To understand the pre-existing challenges within the justice sector, it is necessary to\nconsider the politicisation and weakening of the system which occurred during the Qadhafi\nera. During that time, regular courts were often bypassed in favour of special courts and\nmilitary court systems, in particular for political crimes. Special courts included the\nPeople’s Court which was described by United Nations treaty bodies and many\ncommentators as failing even to comply with minimum fair trial standards.306 The later\nState Security Court was similarly regarded as repressive.307 After the abolition of the\nPeople’s Court, those who worked within it were reassigned to the ordinary court system,\n“carrying with them a legacy of arbitrary procedural practices”.308 Other judges were said to\nhave been appointed without legal training. 309 Judges, prosecutors, State-appointed lawyers,\npublic defenders and Government lawyers were considered as part of one corps, and so\ncould be transferred between functions, undermining notably the tenure of judges and\ncreating particular challenges for the independence of the judiciary."},{"id":"a-hrc-31-crp-3-p0314","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"314","seq":315,"section":"1. Assessment of the justice sector","text":"Executive control of the judiciary was maintained through a High Judicial Council,\nwhich was chaired by the Secretariat of Justice (equivalent to the current Ministry of\nJustice). Corruption was rampant and has continued to be regarded as a significant issue\nwith Libya being ranked 166 out of 175 on Transparency International’s Corruption\nPerception Index for 2014. 310 During the Qadhafi era, the private legal profession was\nabolished and replaced with “People’s Lawyers” (employed by the Government to provide\nlegal aid).311 However, the private legal profession continued, and by the later years of the\nregime the Bar Associations were a powerful force within their communities."},{"id":"a-hrc-31-crp-3-p0315","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"315","seq":316,"section":"1. Assessment of the justice sector","text":"From 2012 to 2014, a number of steps were taken to address this legacy. The Libyan\nauthorities removed the Ministry of Justice from the High Judicial Council to separate the\nexecutive and the judiciary. The jurisdiction of military courts over civilians was abolished.\nThe Constitutional Chamber of the Supreme Court formally overturned the law regulating\nthe People’s Court. Although the court had itself been abolished in 2005, the court ruling\nwas important to bring about an end to the use of the People’s Court’s procedures by\nprosecutors.312 A vetting process is understood to have commenced in relation to the\njudges, though was also reported to have progressed slowly.313 The vetting question was to\nsome extent overtaken by the passage of the law on political and administrative isolation of\n2013 (which came into effect in June 2014), which provided for the exclusion of those\nassociated with the Qadhafi regime and anyone who opposed the 2011 revolution from\npublic life for a period of 10 years. 314"},{"id":"a-hrc-31-crp-3-p0316","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"316","seq":317,"section":"1. Assessment of the justice sector","text":"Concerted planning and programming was undertaken by Libyan authorities in\nconjunction with international partners with a view to harnessing additional technical\nassistance and expertise. The range of international actors included UNSMIL/OHCHR,\nUNODC, UNDP; bilateral State partners and international non-governmental organizations.\nUNSMIL was tasked with coordination of international assistance to Libyan authorities and\ninstitutions. Particular assistance was provided in relation to the constitution-drafting\nprocess; screening of conflict-related detainees; transitional justice measures; legislative\nreform; training of judges and prosecutors; judicial reform; operation of the prosecution\nservices; building the capacity of the Judicial Police; supporting the private legal\nprofession; providing institutional support to the Ministry of Justice; and improving access\nto justice more broadly.315"},{"id":"a-hrc-31-crp-3-p0317","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"317","seq":318,"section":"1. Assessment of the justice sector","text":"Although some progress was made prior to the outbreak of conflict, obstacles were\nalso encountered. A recurring theme in many of the evaluations was the lack of reliable\ndata to gauge current operations and evaluate functioning. In addition, some programmes\nfaced difficulties in garnering sufficient buy-in from concerned actors.316 Practical safety\nconcerns were also raised as an inhibiting factor. In relation to one UNSMIL training\nprogramme, for instance, concerns were expressed by Libyan actors as to the implications\nof implementing full fair trial procedures, in particular foreseeing that a greater number of\nacquittals would prompt reprisals by interested armed groups.317"},{"id":"a-hrc-31-crp-3-p0318","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"318","seq":319,"section":"1. Assessment of the justice sector","text":"For any reform of the justice sector to be successful in Libya, support needs to\nemanate from the highest levels of the political and judicial systems in Libya. With the\nestablishment of the Government of National Accord, it is anticipated that there will be\nrenewed opportunity to review and reinstitute plans for coordinated technical assistance and\ncapacity-building within the justice sector. Areas in which this technical assistance might\nbe focused are further elaborated upon in this present report including in Annex III,\nspecifically in relation to moving forward with respect to criminal justice accountability for\nthose responsible for violations and abuses committed in 2014 and 2015."},{"id":"a-hrc-31-crp-3-p0319","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"319","seq":320,"section":"2. Moving towards accountability","text":"The sheer number of allegations of gross violations of international human rights\nlaw, serious violations of international humanitarian law, and serious abuses of human\nrights, and the fact that they have been committed by so many different parties in disparate\ngeographical areas present enormous challenges, in particular in overcoming the prevailing\nimpunity in Libya and securing accountability. To date, there have been very few\ninvestigations and no prosecutions of leaders or members of armed groups or armed forces\nrelating to the events of 2014 and 2015."},{"id":"a-hrc-31-crp-3-p0320","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"320","seq":321,"section":"2. Moving towards accountability","text":"International efforts are focused on the establishment of the Government of National\nAccord and bringing an end to the conflict. Justice will be vital to bring about a sustainable\npeace in Libya. In the Libyan Political Agreement, commitments have been made to end\nimpunity. Strong leadership and support will be required to combat the significant\nresistance that might be anticipated to realising this commitment, in particular from\ninfluential groups or individuals implicated in the violations and abuses."},{"id":"a-hrc-31-crp-3-p0321","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"321","seq":322,"section":"2. Moving towards accountability","text":"Criminal justice accountability in Libya is currently being pursued through both the\nInternational Criminal Court and the Libyan justice system.318\n(a)         International Criminal Court"},{"id":"a-hrc-31-crp-3-p0322","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"322","seq":323,"section":"2. Moving towards accountability","text":"In its resolution 1970 (2011), the Security Council referred the situation of Libya to\nthe Prosecutor of the International Criminal Court. On 25 July 2014, in the context of the\nworsening situation in Libya, the Prosecutor issued a statement that she “[would] not\nhesitate to investigate and prosecute those who commit crimes under the Court’s\nRights, A/HRC/25/42, 13 January 2014; and Report of the United Nations High Commissioner for\nHuman Rights on the situation of human rights in Libya and on related technical support and\ncapacity-building needs, A/HRC/28/51, 12 January 2015.\njurisdiction in Libya, irrespective of their official status or affiliation”. 319 In 2015, the\nProsecutor has twice affirmed the belief that the crimes committed in 2014 and 2015 fall\nwithin the purview of the referral, including crimes committed by groups “purportedly\naffiliated with or representing the self-proclaimed” ISIL. 320 The Prosecutor also publicly\nstated, however, that capacity to pursue these cases has been hampered by resource\nconstraints.321 The High Commissioner supports resourcing the Court further to enable it to\nexpand its investigations into events since 2014 as vital for breaking the cycle of impunity\nin Libya. It is however clear that the Court is not designed to address, and will never be\nable to pursue, such a large number of cases relating to crimes under international law\narising in Libya.\n(b)         Libyan justice system"},{"id":"a-hrc-31-crp-3-p0323","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"323","seq":324,"section":"2. Moving towards accountability","text":"While the Libyan Government bears the primary responsibility for investigating and\nprosecuting those responsible for serious violations and abuses it would appear that the\nLibyan justice system does not at present have the means or capacity to conduct prompt,\nindependent and credible investigations or to prosecute those responsible in a manner\nconsistent with human rights."},{"id":"a-hrc-31-crp-3-p0324","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"324","seq":325,"section":"2. Moving towards accountability","text":"At the very practical level, as this present report has noted, attacks on the justice\nsystem have severely limited its operation.322 In some areas, particularly in the eastern and\ncentral regions, courts have completely stopped operating. Criminal justice proceedings\nhave been particularly impacted as they attract more risk in terms of reprisal attacks."},{"id":"a-hrc-31-crp-3-p0325","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"325","seq":326,"section":"2. Moving towards accountability","text":"The safety of judicial actors including judges, prosecutors, defence counsel, victims,\nand witnesses, cannot at present be assured. Even prior to the outbreak of hostilities in\n2014, prosecutors and judges faced attacks, particularly where they ordered the release of\nformer regime members or the arrest of members of armed groups. Attacks on judicial\nactors have intensified, including bomb attacks, assassinations, and disappearances. Cases\nrelating to the events in 2014 and 2015 could be expected to involve significant security\nrisks. Victims and witnesses remain vulnerable to retaliation."},{"id":"a-hrc-31-crp-3-p0326","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"326","seq":327,"section":"2. Moving towards accountability","text":"A number of gross violations of international human rights law, serious violations of\ninternational humanitarian law, and serious abuses of human rights identified in this present\nreport are acts which, if established in a court of law, may amount to crimes under\ninternational law. Such crimes should be tried as crimes under international law to\ndemonstrate the gravity of the offences, to ensure appropriate prosecutions and sentencing,\nand to duly acknowledge the harm caused to the victims. Libya’s domestic legal framework\nis currently inadequate to deal with crimes under international law. Although there have\nbeen movements to augment the law, for instance, by criminalising torture and enforced\ndisappearance,323 and domestic criminal offences implicated in the violations, there is\ncurrently no coverage of crimes such as war crimes and crimes against humanity."},{"id":"a-hrc-31-crp-3-p0327","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"327","seq":328,"section":"2. Moving towards accountability","text":"In some quarters, there is a lack of confidence in the ability of the justice system to\nrender impartial justice, particularly in “political cases” relating to the conflict. A number\nof justice system officials bravely continue to carry out their functions. However, some are\nviewed as having compromised their independence by succumbing to pressure from armed\ngroups.324 Others have been accused of being politicised following recent events, such as\nthe appointment of judges by the General National Congress whose own authority is\ndisputed. Even if officials are not actually actively aligned with specific security or political\ninterests, there is an issue of perception of bias in some quarters. Furthermore, in relation to\nthe case of former Qadhafi regime senior officials, serious concerns were raised about the\ncapacity of the justice system to provide for fair trials which respect human rights\nstandards.325"},{"id":"a-hrc-31-crp-3-p0328","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"328","seq":329,"section":"2. Moving towards accountability","text":"Specific action by Libyan authorities together with targeted international assistance\nwill be vital to overcome the aforementioned issues. Priority actions needed include\naddressing the current security threats to the administration of justice. It is vital for effective\naction to be taken with respect to the threat posed by armed groups in particular. In addition\nto bringing an end to hostilities in general, specific risk assessments and adequate security\nmeasures should be developed and implemented to ensure that judicial actors can exercise\ntheir functions in safety and without being subject to threats or coercion. Fundamental\nreform of the Judicial Police is required to ensure it can provide effective and impartial\nprotection for judicial actors and court facilities. Such reform would include comprehensive\nvetting of Judicial Police personnel (particularly those integrated from armed groups) in\naccordance with standards of due process, and ensuring that the Judicial Police is provided\nwith sufficient equipment and training. A robust system of victim and witness protection is\nalso needed to allow individuals to come forward with information and engage in the\nproceedings."},{"id":"a-hrc-31-crp-3-p0329","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"329","seq":330,"section":"2. Moving towards accountability","text":"Continued reform of the Penal Code and the Code of Criminal Procedure will be of\nparticular importance to ensure that crimes under international law are criminalised under\ndomestic law, and that there is provision for the differing modes of criminal responsibility\nrecognised in international law (including command and superior responsibility). Reform is\nrequired for trial procedures to comply with international human rights standards. Relevant\npersonnel could be further trained in the investigation, prosecution and adjudication of\ncrimes under international law. Given the large number of cases arising in 2014 and 2015,\neffective case selection and management systems should be established."},{"id":"a-hrc-31-crp-3-p0330","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"330","seq":331,"section":"2. Moving towards accountability","text":"Trust in the ability of the Libyan justice system to render justice must be re-\nestablished. Members of the judiciary and other judicial actors should undergo a further\nprocess of vetting in accordance with standards of due process, to remove and prevent the\nrecruitment of individuals about whom there are reasonable grounds to believe that they\nhave been involved in human rights violations or abuses, or are responsible for corruption,\nbias, or incompetence. More generally, further measures should be taken to ensure the\nindependence of the judiciary and of investigations; to build the capacity of justice system\nactors (including the Ministry of Justice); to strengthen the provision of legal services; to\nincrease public access to laws; and to monitor performance. Annex III elaborates upon\nthese and further possible measures. A coordinated and comprehensive plan of action\naddressing the justice sector should to be devised and implemented accordingly."},{"id":"a-hrc-31-crp-3-p0331","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"331","seq":332,"section":"2. Moving towards accountability","text":"In order to maximise the quality and efficiency of proceedings and of technical\nassistance programmes in this area, the Government might consider creating a specialised\njudicial structure within Libyan courts to focus on crimes under international law. The\nstructure would need to be supported by specifically appointed judges, prosecutors,\ninvestigators and lawyers. Its design would have to take into account the security concerns\nfor those involved in the trials, including with regard to deciding on its location.\nConsideration could also be given to initially embedding foreign advisers or experts to\nwork in tandem with Libyan officials."},{"id":"a-hrc-31-crp-3-p0332","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"332","seq":333,"section":"2. Moving towards accountability","text":"Significant discussion would need to take place to further such efforts. The High\nCommissioner therefore supports the convening of a high-level meeting to bring together\nLibyan actors, international partners, and experts to discuss initiatives to foster\naccountability for the gross violations of international human rights law, serious violations\nof international humanitarian law, and serious abuses of human rights, including those that\nmay amount to crimes under international law, that have been committed in Libya."},{"id":"a-hrc-31-crp-3-p0333","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"333","seq":334,"section":"2. Moving towards accountability","text":"In addition to criminal investigations and prosecutions, steps should be taken to\nreinvigorate other transitional justice mechanisms, including truth-seeking, reparations, and\ninstitutional reform. Measures taken since 2011 (including the law on transitional justice,\nthe law on political and administrative isolation and recent amnesty laws) should be\nreviewed to ensure compliance with international human rights standards and appropriate\ncoverage of the events of 2014 and 2015.\n(c)     Sanctions"},{"id":"a-hrc-31-crp-3-p0334","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"334","seq":335,"section":"2. Moving towards accountability","text":"The High Commissioner also supports the listing of individuals responsible for\nplanning, directing, or committing acts that violate applicable international human rights\nlaw or international humanitarian law, or acts that constitute human rights abuses, under the\nsanctions regime of the Security Council,326 while urging that sanctions imposed be\naccompanied by rigorous procedural safeguards to guarantee minimum standards of due\nprocess."},{"id":"a-hrc-31-crp-3-p0335","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"335","seq":336,"section":"VIII. Update on technical assistance","text":"A report of the High Commissioner to the Human Rights Council on the human\nrights situation and technical assistance and capacity-building needs was issued in January\n2015.327 The report provided an overview of the human rights situation and of technical\nassistance provided to support key institutions and civil society actors in Libya during the\ncourse of 2014. This Chapter of the present report contains a further update of key activities\ncarried out since then, during which time OHCHR has continued to provide support to the\nhuman rights mandate of UNSMIL. This update has been prepared with the assistance of\nthe Human Rights, Transitional Justice and Rule of Law Division of UNSMIL. 328"},{"id":"a-hrc-31-crp-3-p0336","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"336","seq":337,"section":"VIII. Update on technical assistance","text":"Despite having the scope of its activities curtailed by its relocation from Libya to\nTunisia, and the increasingly entrenched political divisions affecting partner institutions,\nUNSMIL/OHCHR has remained in close contact with national counterparts, advising them\non international human rights and rule of law standards."},{"id":"a-hrc-31-crp-3-p0337","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"337","seq":338,"section":"VIII. Update on technical assistance","text":"Technical assistance was provided during the negotiations of the Libyan Political\nAgreement. As a result, a number of human rights provisions were incorporated in the\nAgreement, including commitments to end impunity; to remove all detainees from the\ncontrol of armed groups and to ensure their judicial screening; to facilitate the voluntary\nreturn of the displaced to their homes in dignity and safety; to address the issue of the\nmissing; and to resume the transitional justice process."},{"id":"a-hrc-31-crp-3-p0338","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"338","seq":339,"section":"VIII. Update on technical assistance","text":"UNSMIL/OHCHR continued to support the Constitution Drafting Assembly with\nexpert advice. In addition to giving written feedback on ensuring greater compliance of the\ndraft Constitution with international human rights law and standards, UNSMIL/OHCHR\nprovided advice in meetings with key members of the Assembly, including the heads of the\ncommittees on Rights and Liberties, Independent Authorities, and the Judiciary. Workshops\nwere facilitated, including a workshop in Geneva from 23 to 25 February 2015 for members\nof the Assembly to discuss the inclusion of human rights principles in the Libyan\nConstitution. The workshop was organised by UNSMIL/OHCHR with the support of the\nGovernment of Switzerland and included a detailed review of the draft chapter on rights\nand liberties, as well as thematic discussions on related topics such as rights of minorities\nand indigenous persons, freedom of expression and opinion, women’s rights, rights of\nmigrants, and the right to life."},{"id":"a-hrc-31-crp-3-p0339","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"339","seq":340,"section":"VIII. Update on technical assistance","text":"Close contact has continued with representatives of the judiciary and the prison\nsector, in order to assess the current needs and plan capacity-building support. In November\n2015, UNSMIL/OHCHR organized a meeting in Tunis for Libyan directors of\nrehabilitation and correction institutions (prison managers) in Tunis. 14 prison managers\nfrom different parts of Libya participated, including the manager of the women’s prison.\nParticipants adopted a new Code of Ethics and Conduct during the meeting."},{"id":"a-hrc-31-crp-3-p0340","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"340","seq":341,"section":"VIII. Update on technical assistance","text":"Despite the closure of some offices of NCCLHR, UNSMIL/OHCHR continued to\nwork on strengthening its capacity with respect to human rights monitoring and reporting.\nIn February 2015, UNSMIL/OHCHR facilitated sessions on human rights monitoring and\ndocumentation during a two-day workshop organized by the American Bar Association\nRule of Law Initiative targeting 15 participants including members of NCCLHR, the\nLibyan Defenders Network, and several academics. In May 2015, UNSMIL/OHCHR also\ncontributed to a three-day training workshop organized by the Cairo Institute for Human\nRights Studies, which targeted Libyan civil society organizations. Around 20 Libyan\nhuman rights defenders participated with representation of NGOs, community based\norganizations, internally displaced person communities, journalists, and the NCCLHR. The\nworkshop aimed to introduce the mandate of the investigation and train civil society\norganizations on effective tools in human rights monitoring, documentation and reporting.\nIn July 2015, UNSMIL/OHCHR contributed to a three-day training workshop organized by\nUNDP Libya for 20 civil society activists working in the fields of development, women’s\nrights, humanitarian aid, child protection, and the rights of persons living with disabilities."},{"id":"a-hrc-31-crp-3-p0341","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"341","seq":342,"section":"VIII. Update on technical assistance","text":"In order to increase the role of civil society in peace-building, on 19 to 20 August\n2015, UNSMIL convened a meeting of Libyan civil society organizations and activists to\nlearn of comparative practices, with inputs provided in relation to the experiences of\nNorthern Ireland, Tunisia and Yemen. The meeting adopted a set of recommendations\nincluding on the establishment of timelines to operationalize the Political Agreement and\nregarding mechanisms for the independent monitoring of its implementation with the\neffective participation of civil society. Recommendations also focused on enabling civil\nsociety to play an effective role in ongoing peace-building."},{"id":"a-hrc-31-crp-3-p0342","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"342","seq":343,"section":"VIII. Update on technical assistance","text":"Technical assistance was also provided to a joint committee formed by the two\nmunicipalities of Misrata and Tawergha aimed at facilitating the safe return of Tawerghans\nto their homes. Technical assistance focused on issues of reparations, accountability of\nperpetrators, and the reconstruction of Tawergha. A number of meetings of the Joint\nCommittee have been facilitated by UNSMIL/OHCHR, with the support of the\nGovernment of Germany and the Government of Switzerland. This initiative addresses one\nof the most intractable legacies of the armed conflict in 2011. The process led in December\n2015 to the adoption of a road map governing future returns."},{"id":"a-hrc-31-crp-3-p0343","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"343","seq":344,"section":"VIII. Update on technical assistance","text":"Once a Government of National Accord is established it is expected that the United\nNations will be able to increase its capacity-building activities."},{"id":"a-hrc-31-crp-3-p0344","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"344","seq":345,"section":"IX. Recommendations","text":"Recognizing the urgent need to bring an end to the widespread human rights\nviolations and abuses being committed in Libya, and to provide for justice and\naccountability, the High Commissioner appeals to all parties to the conflict promptly\nto cease hostilities and to support the establishment of a Government of National\nAccord, to move towards a State based on respect for human rights and the rule of\nlaw."},{"id":"a-hrc-31-crp-3-p0345","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"345","seq":346,"section":"IX. Recommendations","text":"Accordingly, the High Commissioner recommends that all parties to the\nconflict:\n(a)   Desist immediately from all violations of international human rights law\nand international humanitarian law and abuses of human rights, including those\namounting to crimes under international law;\n(b)    Declare that such acts will not be tolerated and remove those suspected\nof such acts from active duty pending investigation."},{"id":"a-hrc-31-crp-3-p0346","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"346","seq":347,"section":"IX. Recommendations","text":"The High Commissioner recommends that the Government of Libya:\n(a)    Ensure that all people within the territory of Libya whose rights have\nbeen violated are afforded an effective remedy;\n(b)   Ensure prompt, thorough and effective investigations by independent\nand impartial bodies of allegations of violations and abuses, and that those responsible\nare held accountable;\n(c)     Address urgently the proliferation of armed groups, including by\ninstituting a programme of disarmament, demobilization and reintegration;\n(d)  Resume State-building activities as soon as feasible, with a particular\nfocus on building inclusive institutions, effective law enforcement agencies, an\nindependent and impartial justice sector and a unified armed force operating under\ncivilian control;\n(e)    Institute a comprehensive vetting programme compliant with standards\nof due process to remove and prevent the recruitment into State services – including\narmed forces, law enforcement and judicial services – of individuals about whom\nthere are reasonable grounds to believe they have been involved in violations of\ninternational human rights law or international humanitarian law, or abuses of\nhuman rights;\n(f)    Address the situation of conflict-related detainees, including by ensuring\nthat the State is in control of all detention facilities, and that the cases of detainees are\nappropriately screened with a view to either charge or release them in accordance\nwith international standards;\n(g)     Ensure the proper treatment of all individuals in detention or deprived\nof liberty, including by eliminating torture and other ill-treatment, including sexual\nviolence; access must be ensured to medical treatment, sufficient food and water.\nDetainees should have access to legal counsel and courts to seek legal review, as well as\nto their families and other relevant individuals. International and national monitoring\norganizations should be permitted regular, unhindered and without-notice access to\nall places of detention;\n(h)     Support the independence of the National Council for Civil Liberties and\nHuman Rights, and ensure its ability to operate safely and in accordance with\ninternational standards;\n(i)     Respect and promote the role of civil society, including by ensuring the\nprotection of human rights defenders and journalists;\n(j)    Address urgently the situation of migrants to ensure that all individuals,\nregardless of their status, are able to enjoy their human rights, including by adopting\nand implementing an effective refugee status determination procedure and\nimplementing alternatives to migration-related detention, and taking effective action\nto combat human trafficking;\n(k)    Facilitate the voluntary return of persons who are currently internally\ndisplaced, including the Tawerghan community, in a safe and dignified manner;\n(l)   Ensure respect for the rights of children, including by combating\nrecruitment and the use of children by groups pledging allegiance to ISIL, and\nredressing gaps in children’s enjoyment of rights, including the right to education;\n(m) Take effective action to eliminate sexual and gender-based violence,\nincluding by implementing a gender-sensitive protection and reporting mechanism\nand providing rehabilitation services and access to justice for victims;\n(n)    Review budgetary arrangements that limit funding for programmes\nrelating to economic and social rights (such as food, education and health care), and\ntake immediate steps to remedy damage to facilities and to bolster systems of\nemergency response, including through coordinated international assistance;\n(o)    In relation to further criminal justice accountability measures:\n(i) Extend full cooperation with and support for the International\nCriminal Court by assisting its investigations and complying with its\nrulings;\n(ii) Consider the establishment of a specialized judicial structure within\nLibyan courts to focus specifically on crimes under international law,\nsupported by specifically appointed judges, prosecutors, investigators\nand lawyers, with the possibility of at least initially embedding\nforeign advisers or experts to work in tandem with Libyan officials;\n(p)   With regard to the justice sector:\n(i) Urgently ensure protection for judges, prosecutors and other justice\nsystem staff and courts;\n(ii) Implement an effective witness protection programme;\n(iii) Prioritize reform of the Penal Code and the Code of Criminal\nProcedure to encompass violations of international human rights and\nhumanitarian law, including crimes under international law, and\nensure that procedures are consistent with international human\nrights standards;\n(iv) Institute a vetting programme of the judicial police, the judiciary and\nother justice system actors in accordance with standards of due\nprocess to remove and prevent the recruitment of individuals about\nwhom there are reasonable grounds to believe that they have been\ninvolved in human rights violations or abuses, or are responsible for\ncorruption, bias or incompetence;\n(v) Devise and implement a plan of action to strengthen the justice\nsector, including in relation to the priority areas identified in Annex\nIII of this present report;\n(q)    Review transitional justice measures introduced after 2011 with a view\nto ensuring compliance with international human rights standards, and appropriate\ncoverage of events in 2014 and 2015. Future transitional justice initiatives should be\nbased on genuine, inclusive national consultations, with a particular focus on victim\ncommunities."},{"id":"a-hrc-31-crp-3-p0347","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"347","seq":348,"section":"IX. Recommendations","text":"The High Commissioner recommends that the international community:\n(a)    Support the International Criminal Court, particularly by providing the\nOffice of the Prosecutor with the resources necessary to investigate and prosecute the\nalleged crimes under international law committed in Libya since 2014;\n(b)   Provide assistance to strengthen the capacity of the justice and related\nsectors, and provide support to transitional justice mechanisms that are compliant\nwith international standards;\n(c)     Support the convening of a high-level meeting in consultation with the\nLibyan authorities to bring together Libyan actors and international partners to\ndiscuss initiatives to increase accountability in Libya;\n(d)    Prioritize support for a programme of demobilization, disarmament and\nreintegration of members of armed groups, to be conducted in compliance with\ninternational human rights standards;\n(e)  Apply stringent screening procedures to recipients of technical assistance\nor other persons involved in peacekeeping or military exchanges or training\nprogrammes;\n(f)    Ensure protection of and practical assistance to Libyan human rights\ndefenders (including by facilitating emergency visas, temporary shelter and relocation\nwhere necessary), and consider the establishment of a fund to support human rights\ndefenders at risk;\n(g)     Ensure respect for the principle of non-refoulement, and provide\nprotection, in accordance with international law, for those with a well-founded fear of\npersecution."},{"id":"a-hrc-31-crp-3-p0348","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"348","seq":349,"section":"IX. Recommendations","text":"The High Commissioner recommends that the Human Rights Council:\n(a)   Continue to monitor developments in Libya and, to that end, to consider\nthe establishment of a mandate of independent expert on Libya, to report to the\nCouncil on progress made towards accountability and on the situation of human\nrights;\n(b)   Encourage relevant special procedure mandate holders to make visits to\nLibya when feasible;\n(c)   Share a copy of the present report with the General Assembly and the\nSecurity Council for deliberation."},{"id":"a-hrc-31-crp-3-p0349","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":"349","seq":350,"section":"IX. Recommendations","text":"The High Commissioner recommends that the Security Council:\n(a)   Take action with respect to listing individuals responsible for violations\nor abuses under the current sanctions regime of the Security Council, while ensuring\nthat any sanctions imposed are accompanied by rigorous procedural safeguards that\nguarantee minimum standards of due process;\n(b)    Increase the capacity of the Human Rights Division of UNSMIL to carry\nout monitoring and capacity-building activities, and mandate UNSMIL to undertake\nappropriate follow-up to the findings and recommendations contained in the present\nreport.\nANNEXES"},{"id":"a-hrc-31-crp-3-u0351","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":351,"section":"II. Indicative mapping of security and armed groups associated","text":"with Operation Dignity and Libya Dawn as at 2014\nThis indicative mapping has been prepared based on information received during the\ninvestigation. There are a large number of armed actors, particularly armed groups,\noperating in Libya, and this mapping does not cover all groupings. It instead seeks to cover\nsome of the major groupings associated with Operation Dignity and Libya Dawn\nhighlighted during the investigation. A more detailed description is set out in Chapter IV of\nthe present report. This mapping is also limited to describing the situation as at 2014, given\nsome alliances/allegiances may have since changed. Further investigation would be needed\nto prepare an updated, detailed, and accurate mapping.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0352","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":352,"section":"III. Priority areas for strengthening the justice sector","text":"(a)   Ensuring a safe environment for all judicial actors\n• Security measures should be implemented to address the protection needs of judges,\nprosecutors, staff and those attending at court facilities. In order to do this, a\ncomprehensive risk assessment needs to be undertaken and planning commenced\naccordingly. Crucial to this process will be addressing deficiencies within the Judicial\nPolice, including through the vetting and capacity-building processes described below.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0353","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":353,"section":"III. Priority areas for strengthening the justice sector","text":"(b)   Ensuring the protection of victims and witnesses\n• A victim and witness protection programme should be implemented which mitigates\nthreats faced by those coming forward with information concerning human rights\nviolations and abuses. The programme should be tailored to ensure it is appropriate for all\nvictims and witnesses, including victims of sexual and gender-based violence.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0354","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":354,"section":"III. Priority areas for strengthening the justice sector","text":"(c)   Implementing an effective vetting programme of justice system actors\n• A vetting programme of the Judicial Police, the judiciary and other justice system actors\nshould be instituted in accordance with standards of due process to remove and prevent\nthe recruitment of individuals about whom there are reasonable grounds to believe that\nthey have been involved in human rights violations or abuses, or are responsible for\ncorruption, bias, or incompetence. Whilst some vetting of personnel has been undertaken\nin previous years, OHCHR notes reports that, for example, the vetting of Judicial Police\n(including integrated armed group members) was not sufficiently comprehensive.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0355","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":355,"section":"III. Priority areas for strengthening the justice sector","text":"(d)   Addressing the situation of detainees\n• Conflict-related detainees currently under the control of armed groups should be\ntransferred into the custody of the State. Unofficial places of detention should be closed.\nDetainees’ cases should be individually screened by prosecutors, so that individuals are\neither charged where there is sufficient supporting evidence or released. Judicial review\nto consider the legality of detention should be made available to detainees.\n• A detainee data management system should be established to manage information on\npersons held in all places of detention. The information should be independently verified,\nand include details of their detention from the time of arrest to any post-trial detention as\nappropriate. Information on the whereabouts of detainees should be made available to\nfamily members. A full list of places of detention should be made public.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0356","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":356,"section":"III. Priority areas for strengthening the justice sector","text":"(e)   Undertaking legal review and reform\n• National legislation and the Constitution should be reviewed and reformed as necessary\nto ensure compliance with international human rights standards, with priority afforded to\nthe Penal Code, the Code of Criminal Procedure and the law on amnesty and other\ntransitional justice-related laws such as the law on political and administrative isolation.\nIn this regard consideration should be given to a moratorium on the use of the death\npenalty, or to limiting it to the most serious crimes in compliance with international law,\nwith a view to its eventual abolition.\n• National legislation should be adopted to ensure the criminalisation of crimes under\ninternational law and to ensure provision is made for the differing modes of criminal","unnumbered":true},{"id":"a-hrc-31-crp-3-u0357","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":357,"section":"III. Priority areas for strengthening the justice sector","text":"responsibility recognised in international law (including command and superior\nresponsibility). No statute of limitations or amnesty should apply to gross human rights\nviolations or serious violations of international humanitarian law, including those\namounting to crimes under international law. Any amnesties introduced should not impair\nvictims’ right to a remedy, including reparation, or victims’ or societies’ right to the truth.\n• The military justice system should be reviewed and reformed as necessary to eliminate\ninconsistencies and overlap in jurisdiction with the civil justice system, and to ensure that\ncivilians are not subject to a military justice system.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0358","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":358,"section":"III. Priority areas for strengthening the justice sector","text":"(f)   Ensuring the independence of the judiciary\n• The principle of judicial independence must not only be enshrined in law, but respected\nin practice. In this respect, a review should be undertaken to ensure appropriate systems\nfor such matters as the appointment, removal, and conditions of service of judges.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0359","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":359,"section":"III. Priority areas for strengthening the justice sector","text":"(g)   Ensuring the independence of investigations\n• The office of the Attorney-General should operate through an independent budget, and\nshould be mandated with the authority to undertake all necessary investigations without\nrequiring permissions from other authorities.\n• An independent oversight body reporting directly to the Attorney-General should be\nconsidered to receive and investigate complaints related to alleged violations by police\nand prison officials.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0360","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":360,"section":"III. Priority areas for strengthening the justice sector","text":"(h)   Strengthening the capacity of actors within the justice system\n• Training programmes for judges and prosecutors should be strengthened, through the\nHigh Judicial Institute, including in relation to continuing education for sitting judges and\nprosecutors. Further initiatives should be undertaken with respect to increasing\nknowledge of the practical application of international human rights law, international\nhumanitarian law and international criminal law. Specialised training should also be\nprovided on the topic of investigating, prosecuting and adjudicating crimes of sexual\nviolence.\n• The capacity of the Judicial Police should be strengthened through dedicated training\nprogrammes, as well as the provision of equipment.\n• The capacity of the prosecution service (the office of the Attorney-General and associated\noffices) should be strengthened, including with respect to collection and analysis of\ninformation, case management, and integration of witness protection mechanisms.\n• The capacity of the Ministry of Justice should be strengthened, in particular in the areas\nof policy development, human rights related review of legislation, administration and\nhuman resources. The capacity of the ministry to coordinate international assistance in\nthe justice sector should also be strengthened.\n• The forensic capacity of the sector should be increased to ensure it is adequately\nresourced including for DNA testing, forensic anthropology and archaeology.\n• Efforts should be intensified to increase the number of women at all levels within the\njustice sector.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0361","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":361,"section":"III. Priority areas for strengthening the justice sector","text":"(j)   Increasing access to laws\n• Libyan laws and regulations should be held in public digital collection in order to\nimprove accessibility. Any such collection could be maintained by the Ministry of\nJustice.","unnumbered":true},{"id":"a-hrc-31-crp-3-u0362","rec_id":"rec7FMRMxNt00GOh1","symbol":"A/HRC/31/CRP.3","n":null,"seq":362,"section":"III. Priority areas for strengthening the justice sector","text":"(k)   Strengthening the evidence base of current performance\n• Systems to collect and monitor data on key performance indicators within the justice\nsector should be enhanced to improve policy-development, monitoring, and evaluation\nprocesses.","unnumbered":true}]});